window.ANS = {
"acuka":{"a":"Acuka","k":"Baharat","e":"Türk mutfağının acılı biber-ceviz ezmesi","o":"Kırmızı biber salçası, ceviz, pul biber ve baharatların bir araya getirilmesiyle yapılan, koyu kırmızı ve acılı bir Türk mezesidir. Genellikle sarımsak ve nar ekşisiyle zenginleştirilir, ekmeğe sürülerek tüketilir.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, yaklaşık)","~310 kcal"],["i-box-archive","Saklama (yüzeyine ince bir zeytinyağı tabakası eklemek tazeliğini korur)","Buzdolabında kapalı kapta birkaç gün"]],"b":[["Acuka Nedir?",[["p","Acuka, kırmızı biber salçası, dövülmüş ceviz, pul biber, sarımsak ve baharatların bir araya getirilmesiyle yapılan, Türk mutfağının acılı bir mezesidir. Özellikle Güneydoğu Anadolu ve Akdeniz bölgesinde yaygındır."],["p","Rengi koyu kırmızı, dokusu kalın-ezme kıvamındadır; muhammaraya çok benzese de genellikle daha acı ve nar ekşisi ölçüsü tariften tarife değişen bir Türk yorumudur."]]],["Acukanın Besin Değerleri",[["p","100 gram acuka yaklaşık 310 kcal enerji içerir; cevizden ve zeytinyağından gelen <b>yağ</b> taşır. Değerler tarife göre değişir, yaklaşıktır."]]],["Acuka Nasıl Tüketilmeli?",[["p","Acuka, dengeli beslenmenin bir parçası şeklinde, meze/sos olarak ölçülü miktarlarda tüketilir."],["p","Bu bilgiler geneldir; acuka bir besindir, tıbbi tedavi yerine geçmez. Kuruyemiş alerjisi olanların ve acı toleransı düşük kişilerin ölçülü tüketmesi önerilir."]]],["Acuka Nasıl Seçilir?",[["p","İyi bir acuka; rengi koyu kırmızı, kokusu belirgin biber-cevizli ve içindekiler listesinde gerçek biber salçası ve ceviz oranı yüksek olandır."],["ul",["Rengi koyu kırmızı olmalı","Kokusu belirgin biber-cevizli olmalı, bayat-küf kokmamalı","İçindekiler listesinde gerçek biber salçası ve ceviz oranı yüksek olmalı"]]]],["Acuka Nasıl Saklanır?",[["p","Acuka, buzdolabında kapalı bir kapta birkaç gün saklanabilir; yüzeyine ince bir zeytinyağı tabakası eklemek havayla temasını azaltıp tazeliğini uzatır."]]],["Mutfakta Acuka Kullanımı",[["p","Acuka en çok kahvaltı sofrasında ekmeğe sürülerek, meze tabağının parçası olarak ve bazı yöresel çorbalara tat vermek için kullanılır."]]]],"s":[["Acuka ile muhammara aynı şey mi?","Yakın akrabadır; ikisi de kırmızı biber ve ceviz temellidir ama acuka Türk mutfağının kendi yorumudur ve genellikle daha acılı, muhammara ise Halep kökenlidir ve nar ekşisi daha belirgindir."],["Acuka evde nasıl yapılır?","Kırmızı biber salçası, dövülmüş ceviz, pul biber, sarımsak ve isteğe göre nar ekşisi karıştırılıp zeytinyağıyla kıvam verilerek hazırlanabilir."],["Acuka Türkiye'nin her yerinde bulunur mu?","Özellikle Güneydoğu Anadolu ve Akdeniz mutfağında yaygındır; büyük şehirlerde de yöresel ürün reyonlarında bulunabilir."]],"q":[["i-carrot","Belirgin acılı","Muhammaraya göre genellikle daha yoğun acı bir profile sahiptir"],["i-wheat-awn","Ekmeğe sürülür","Kahvaltı sofrasında ve meze tabağının parçası olarak ekmekle servis edilir"],["i-arrow-rotate-left","Alternatifi","Muhammara (benzer biber-ceviz mantığı, farklı bölgesel tarif ve nar ekşisi ağırlıklı)"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","n":["(100 g, ~yaklaşık)",[["Enerji","~310 kcal"],["Yağ","~22 g (ceviz ve zeytinyağından)"]]]},
"anason":{"a":"Anason","k":"Baharat","e":"Tatlımsı aromalı tohum","o":"Küçük, gri-kahverengi ve belirgin tatlımsı-meyanımsı aromalı bir baharat tohumu. Türk mutfağında rakının ve bazı çöreklerin, tatlıların aromasını verir.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, tohum (tarifte çok az kullanılır))","337 kcal"],["i-box-archive","Saklama (bütün tohum öğütülmüşten uzun dayanır)","Kapalı kavanozda serin, karanlık yerde 2 yıl"]],"b":[["Anason Nedir?",[["p","Anason (<i>Pimpinella anisum</i>), maydanozgiller familyasından bir bitkinin küçük, gri-kahverengi tohumudur. Belirgin tatlımsı, meyan kökünü ve rezeneyi andıran karakteristik bir aromaya sahiptir; Akdeniz ve Orta Doğu mutfaklarının klasik baharatlarındandır."],["p","Türkiye’de en çok rakının aromasını veren baharat olarak bilinir; ayrıca bazı çörek, kurabiye ve tatlılara tatlımsı bir aroma katar. Yıldız anason ile karıştırılır ancak farklı bir bitkidir; aromaları benzese de aynı değildir."]]],["Anasonun Besin Değerleri",[["p","Anason tohumu 100 gramda yaklaşık 337 kcal enerji ile yoğun <b>lif</b>, yağ ve özellikle çok yüksek <b>demir</b> içerir; ancak bir tarifte kullanılan miktar çok küçük olduğundan günlük beslenmeye pratik katkısı sınırlıdır."]]],["Anasonun Faydaları Nelerdir?",[["p","Anason geleneksel olarak sindirim sonrası ferahlık için ve aroma vermek amacıyla kullanılır; içerdiği uçucu yağlar (özellikle anetol) üzerine araştırmalar sürmektedir. Bir baharat olarak küçük miktarlarda tüketildiğinden lezzet katkısı ön plandadır."],["p","Bu bilgiler geneldir; anason bir baharattır, tıbbi tedavi yerine geçmez."]]],["Anason Nasıl Seçilir?",[["p","Kaliteli anason tohumu bütün, dolgun ve güçlü tatlımsı aromalı olmalıdır; tozlaşmış, kokusu zayıflamış ürünler tazeliğini yitirmiştir. Bütün tohum, öğütülmüş forma göre aromasını daha uzun korur."],["ul",["Tohumlar bütün, dolgun ve gri-kahverengi olmalı","Ovulduğunda belirgin tatlımsı-anasonlu koku vermeli","Nem çekmiş, topaklaşmış ürünler alınmamalı"]]]],["Anason Nasıl Saklanır?",[["p","Anason kapalı bir kavanozda, ışık görmeyen serin bir yerde yaklaşık 2 yıl saklanabilir; bütün tohum hâlinde saklamak ve kullanmadan önce öğütmek aromayı korur."]]],["Mutfakta Anason Kullanımı",[["p","Anason en çok çörek, kurabiye, ekmek ve tatlılarda tatlımsı aroma vermek için; ayrıca bazı içki ve şuruplarda kullanılır. Bütün ya da hafif ezilmiş tohum olarak hamura ve şuruba katılır."]]],["Anasonlu Çörek Nasıl Yapılır?",[["p","Hamura hafif ezilmiş anason tohumu eklenir; pişerken tohumlar aromasını hamura yayar ve çöreğe tatlımsı, karakteristik bir koku verir."]]],["Anason ile Yıldız Anason Farkı Nedir?",[["p","Anason (Pimpinella anisum) küçük tohumlu bir maydanozgil; yıldız anason (Illicium verum) ise yıldız biçimli, farklı bir bitkinin meyvesidir. Aromaları anetol nedeniyle benzese de ayrı baharatlardır."]]],["Anason Hangi Tariflerle Kullanılır?",[["p","Anasonlu çörek ve kurabiye, bazı ekmekler, tatlı şurupları ve geleneksel içecekler anasonun en bilinen kullanımlarıdır."]]]],"s":[["Anason neye benzer bir tada sahiptir?","Tatlımsı, meyan kökünü ve rezeneyi andıran karakteristik bir aromaya sahiptir; bu aroma anetol adlı bileşenden gelir."],["Anason rakıya neden konur?","Rakının karakteristik tadını ve suyla karıştığında beyazlaşmasını (aslanısütü etkisi) sağlayan aromatik bileşen anasondan gelir."],["Anason ile rezene aynı mı?","Hayır; ikisi de maydanozgillerden olup benzer tatlımsı aroma taşır, ancak farklı bitkilerdir ve tohumları ile kullanımları ayrıdır."],["Anason nasıl saklanmalı?","Kapalı bir kavanozda, ışık almayan serin bir yerde; tercihen bütün tohum hâlinde saklanmalı ve kullanmadan önce öğütülmelidir."],["Anason çayı olur mu?","Olur; ezilmiş anason tohumu sıcak suda demlenerek tatlımsı bir bitki çayı hazırlanabilir, geleneksel olarak yemek sonrası tüketilir."]],"q":[["i-flask","Rakının aroması","Rakıya karakteristik anason tadını verir"],["i-utensils","Çörek-tatlıda","Bazı çörek ve tatlılara tatlımsı aroma katar"],["i-circle-question","Yıldız anasondan farklı","Farklı bitkilerdir; aroma benzer ama aynı değildir"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Pimpinella anisum","n":["(100 g tohum (USDA, anason tohumu; kullanım miktarı çok küçük))",[["Enerji","337 kcal"],["Protein","17,6 g"],["Yağ","15,9 g"],["Lif","14,6 g"],["Demir","36,9 mg"]]],"tb":"Anasonlu tarifler","t":[{"a":"Vietnam Usulü Tavuk Phở | Kişnişli Çorba","k":"Tavuk ve Hindi","g":"2609","d":"95 dk","z":"Orta","p":"4 kişilik","s":"Doruk Bademci","r":"0,0","b":2}]},
"ancho-biberi":{"a":"Ancho Biberi","k":"Baharat","e":"Kurutulmuş olgun poblano biberi","o":"Olgunlaşıp koyu kırmızıya dönen poblano biberinin kurutulmasıyla yapılan, geniş ve düz, koyu kahverengi bir Meksika biberidir. Hafif tatlı-üzümsü tadıyla mole soslarının temel malzemelerinden biridir.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu (kurutulmuş olarak satılır)"],["i-fire","Kalori (100 g, kuru, yaklaşık)","~270 kcal"],["i-box-archive","Saklama (nem çekmemesi önemlidir)","Kuru, karanlık dolapta kapalı kapta"]],"b":[["Ancho Biberi Nedir?",[["p","Ancho biberi, olgunlaşıp kırmızıya dönen poblano biberinin güneşte ya da fırında kurutulmasıyla yapılan bir Meksika biberidir. \"Ancho\" ismi İspanyolca \"geniş\" anlamına gelir, biberin düz-geniş şeklinden gelir."],["p","Kurutulmuş Meksika biberleri içinde en hafif acılı ve en tatlımsı olanlardan biridir; kuru erik ve tütün notaları taşıyan karmaşık bir tada sahiptir."]]],["Ancho Biberinin Besin Değerleri",[["p","100 gram kuru ancho biberi yaklaşık 270 kcal enerji içerir; yüksek <b>lif</b> taşır. Değerler yaklaşıktır."]]],["Ancho Biberi Nasıl Tüketilmeli?",[["p","Ancho biberi, dengeli beslenmenin bir parçası şeklinde, yemeklere baharat/sos katkısı olarak ölçülü miktarlarda kullanılır."],["p","Bu bilgiler geneldir; ancho biberi bir besindir, tıbbi tedavi yerine geçmez."]]],["Ancho Biberi Nasıl Seçilir?",[["p","İyi bir ancho biberi; rengi koyu kırmızı-kahverengi, dokusu esnek-buruşuk ve kokusu tatlımsı-meyvemsi olandır. Taş gibi sertleşmiş ya da tozlaşmış olanlar bayatlamıştır."],["ul",["Rengi koyu kırmızı-kahverengi olmalı","Dokusu esnek-buruşuk olmalı, taş gibi sertleşmemiş olmalı","Kokusu tatlımsı-meyvemsi olmalı, küf kokmamalı"]]]],["Ancho Biberi Nasıl Saklanır?",[["p","Ancho biberi, kuru ve karanlık bir dolapta kapalı kabında uzun süre saklanabilir; nem çekmesi küflenmeye yol açabilir."]]],["Mutfakta Ancho Biberi Kullanımı",[["p","Ancho biberi en çok mole soslarında, enchilada soslarında ve güveçlerde kullanılır; genellikle önce ıslatılıp yumuşatılır, ardından ezilerek sosa katılır."]]]],"s":[["Ancho biberi ile poblano aynı biber mi?","Evet, aynı türdür; ancho poblanonun olgunlaşıp kurutulmuş hâlidir. Taze poblano ise işlenmemiş, koyu yeşil hâlidir."],["Ancho biberi nasıl yumuşatılır?","Sapı ve çekirdekleri çıkarılıp sıcak suda 15-20 dakika bekletilerek yumuşatılır, ardından blenderdan geçirilip sosa eklenir."],["Ancho biberi Türkiye'de bulunur mu?","Gurme market ve Meksika ürünleri satan özel yerlerde, online olarak bulunabilir."]],"q":[["i-leaf","Hafif acı, tatlı üzümsü","Kurutulmuş Meksika biberleri arasında en hafif acılı ve en tatlımsı olanlardan biridir"],["i-jar","Mole'nin temeli","Geleneksel mole soslarının vazgeçilmez bileşenlerinden biridir"],["i-arrow-rotate-left","Alternatifi","Mulato biberi (yakın akraba, biraz daha koyu-tatlı)"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Capsicum annuum","n":["(100 g, kuru, ~yaklaşık)",[["Enerji","~270 kcal"],["Lif","yüksek"]]]},
"antep-fistigi":{"a":"Antep Fıstığı","k":"Kuruyemiş","e":"Yeşil kuruyemiş","o":"Canlı yeşil rengi ve kendine özgü tadıyla tanınan, Gaziantep yöresiyle özdeşleşmiş bir kuruyemiş. Baklava dolgusundan dondurmaya, tuzlu atıştırmalıklardan tatlılara kadar geniş kullanım alanı vardır.","y":[["i-layer-group","Kategori","Kuruyemiş"],["i-calendar-days","Mevsim","Eylül hasadı, tüm yıl tüketilir"],["i-fire","Kalori (100 g, çiğ)","560 kcal"],["i-box-archive","Saklama (nem almasın)","Kabuksuz halde hava almayan kapta serin yerde 2–3 ay, buzdolabında 6 ay"]],"b":[["Antep Fıstığı Nedir?",[["p","Antep fıstığı (<i>Pistacia vera</i>), sakızgiller familyasından bir ağacın kabuklu meyvesidir. Adını Türkiye’de en çok yetiştirildiği Gaziantep yöresinden alır; kurak ve sıcak iklimlerde yetişir."],["p","Sert, açık renkli kabuğunun içinde canlı yeşil, hafif mor damarlı, yağlı ve tatlımsı bir iç bulunur. Bu belirgin yeşil rengi, dondurma ve tatlılarda görsel bir işaret olarak da kullanılır."]]],["Antep Fıstığının Besin Değerleri",[["p","Antep fıstığı, kuruyemişler arasında protein oranı en yüksek olanlardan biridir; 100 gramı yaklaşık 560 kcal, 20,2 g protein ve 10,6 g lif içerir. Ayrıca <b>potasyum</b> bakımından diğer kuruyemişlere göre öne çıkar."]]],["Antep Fıstığının Faydaları Nelerdir?",[["p","Yüksek protein ve lif içeriğiyle antep fıstığı, dengeli beslenmenin bir parçası olarak tercih edilen kuruyemişlerdendir. İçerdiği potasyum ve bitkisel bileşiklerin kalp-damar sağlığıyla ilişkisini inceleyen çalışmalar sürmektedir."],["p","Bu bilgiler geneldir; antep fıstığı bir besindir, tıbbi tedavi yerine geçmez. Kalori yoğunluğu nedeniyle günlük bir avuç (yaklaşık 20-30 g) ölçüsü önerilir."]]],["Antep Fıstığı Nasıl Seçilir?",[["p","Kaliteli antep fıstığında kabuk hafifçe aralanmış, iç renk canlı yeşil olmalıdır."],["ul",["Kabuğu tamamen kapalı fıstıklar olgunlaşmamış ya da erken toplanmış olabilir.","İç rengi soluk sarımsı olanlar tazeliğini yitirmiş olabilir.","Küf kokusu ya da lekesi olan fıstıklar kesinlikle tüketilmemeli."]]]],["Antep Fıstığı Nasıl Saklanır?",[["p","Kabuksuz antep fıstığı, yağ oranı nedeniyle hava almayan bir kapta serin ve karanlık bir yerde 2–3 ay; buzdolabında 6 aya, dondurucuda 1 yıla kadar tazeliğini korur. Kabuklu haliyle saklama süresi biraz daha uzundur."]]],["Mutfakta Antep Fıstığı Kullanımı",[["p","Antep fıstığı; çiğ ya da kavrulmuş atıştırmalık olarak, dövülüp baklava ve tatlı dolgularında, dondurmalarda ve tuzlu-tatlı yemeklerde süsleme malzemesi olarak kullanılır."]]],["Antep Fıstıklı Baklava İçin Fıstık Nasıl Hazırlanır?",[["p","Kabuğu soyulmuş fıstıklar önce hafifçe kavrulur, ardından iri çekilerek baklava katları arasına serpilir. İri çekim, hem dokuyu hem görünümü korur."]]],["Antep Fıstığı Kavrulur mu?",[["p","Evet, kuru bir tavada ya da fırında düşük ısıda birkaç dakika kavrularak aroması belirginleştirilebilir; yüksek ısıda hızlı kavurma acılaşmaya yol açabilir."]]],["Antep Fıstığı Hangi Tariflerle Kullanılır?",[["p","Antep fıstıklı baklava, fıstıklı dondurma, fıstık ezmesi, fıstıklı kurabiye ve fıstıklı tavuk sote antep fıstığının en bilinen kullanım alanlarıdır."]]]],"s":[["Antep fıstığı günde ne kadar yenmeli?","Kalori yoğunluğu nedeniyle günde bir avuç (yaklaşık 20-30 g, 25-30 adet) dengeli bir porsiyon sayılır."],["Antep fıstığı ile şam fıstığı aynı mı?","Halk arasında bazen karıştırılsa da şam fıstığı çoğunlukla iç bakla veya yer fıstığı çeşitlerini tanımlamak için kullanılır; antep fıstığı ayrı bir tür (<i>Pistacia vera</i>) olup kendine has yeşil rengiyle tanınır."],["Kabuğu açık antep fıstığı ne anlama gelir?","Kabuğun doğal olarak hafifçe aralanmış olması olgunlaşmanın bir işaretidir ve genellikle kaliteli fıstıklarda görülür; tamamen açılmamış kabuk erken hasadı gösterebilir."],["Antep fıstığı çiğ mi yenir kavrulmuş mu?","Her iki şekilde de tüketilebilir; çiğ hali daha nötr bir tat verirken kavurma aromayı belirginleştirir. Tuzlu kavrulmuş versiyonlarda tuz miktarına dikkat edilmelidir."],["Antep fıstığı alerjisi var mı?","Antep fıstığı, sert kabuklu yemiş alerjileri arasında yer alır; hassasiyeti olan kişiler tüketmeden önce doktoruna danışmalıdır."]],"q":[["i-jar","Hava almayan kapta sakla","Nem alırsa küflenme riski artar"],["i-scale-balanced","Bir avuç ölçü","Günlük 20-30 g dengeyi korur"],["i-arrow-rotate-left","Alternatifi","Kaju, badem"]],"i":["ceviz","badem","findik"],"ic":"i-seedling","l":"Pistacia vera","n":["(100 g çiğ)",[["Enerji","560 kcal"],["Protein","20,2 g"],["Yağ","45,3 g"],["Karbonhidrat","27,7 g"],["Lif","10,6 g"],["Potasyum","1025 mg"]]],"tb":"Antep fıstıklı tarifler","t":[{"a":"Katmer | Fıstıklı Kaymaklı Antep Usulü Tava Böreği","k":"Hamur İşi","g":"1576","d":"75 dk","z":"Ustalık Gerektirir","p":"8 dilim","s":"Rüya Öymen","r":"2,0","b":2},{"a":"Gaziantep Katmeri | Kaymaklı Fıstıklı Kahvaltılık Yufka Tatlısı","k":"Kahvaltılık","g":"1652","d":"45 dk","z":"Zor","p":"4 dilim","s":"Mert Doğan","r":"3,5","b":3},{"a":"Şam Fıstıklı Pilav | Antakya Usulü","k":"Pilav","g":"1789","d":"55 dk","z":"Orta","p":"4 kişilik","s":"Kutay Alyanak","r":"4,0","b":2}]},
"armut":{"a":"Armut","k":"Meyve","e":"Sonbahar meyvesi","o":"İnce kabuğu ve kumlu-sulu dokusuyla tanınan, tatlı ve hafif kokulu bir meyve. Çiğ tüketimin yanı sıra komposto, tatlı ve peynir tabaklarında da kullanılır.","y":[["i-layer-group","Kategori","Meyve"],["i-calendar-days","Mevsim","Sonbahar"],["i-fire","Kalori (100 g, çiğ)","57 kcal"],["i-box-archive","Saklama","Oda sıcaklığında olgunlaştırılıp buzdolabında birkaç gün"]],"b":[["Armut Nedir?",[["p","Armut (<i>Pyrus communis</i>), gülgiller familyasından, elmayla akraba bir meyvedir. Sapa yakın kısmı ince, göbeğe doğru genişleyen karakteristik formuyla tanınır. Williams, Deveci ve Ankara armudu gibi çok sayıda çeşidi vardır."],["p","Olgunlaşmamışken sert olan armut, sofrada genellikle bekletilerek yumuşatıldıktan sonra tüketilir. Eti kumlu bir dokuya sahiptir ve tatlılık derecesi çeşide göre değişir."]]],["Armutun Besin Değerleri",[["p","Armut, 100 gramında yaklaşık 57 kcal enerji ve 3,1 g lif barındıran, düşük kalorili bir meyvedir. Kabuğuyla tüketildiğinde lif oranı daha da yükselir; ayrıca az miktarda <b>C vitamini</b> ve potasyum içerir."]]],["Armutun Faydaları Nelerdir?",[["p","Yüksek lif içeriğiyle armut, dengeli beslenmenin bir parçası olarak sindirim düzenine katkıda bulunabilecek meyvelerdendir. Su oranının yüksek olması da günlük sıvı alımını desteklemesine yardımcı olur."],["p","Bu bilgiler geneldir; armut bir besindir, tıbbi tedavi yerine geçmez."]]],["Armut Nasıl Seçilir?",[["p","Taze armut, sapa yakın kısmından hafifçe bastırıldığında az miktarda esneklik gösterendir; tamamen sert olan armut henüz olgunlaşmamıştır."],["ul",["Kabuk pürüzsüz ve derin çürük lekesiz olsun.","Sapın dibi hafifçe bastırıldığında yumuşuyorsa yemeye hazırdır.","Ağırlığı boyutuna göre dengeli olmalı; çok hafif armutlar içten kurumuş olabilir."]]]],["Armut Nasıl Saklanır?",[["p","Olgunlaşmamış armut oda sıcaklığında birkaç gün bekletilerek yumuşatılır; olgunlaştıktan sonra buzdolabında birkaç gün daha tazeliğini korur. Erken buzdolabına konursa olgunlaşma süreci yavaşlar ya da durur."]]],["Mutfakta Armut Kullanımı",[["p","Armut en çok çiğ tüketilir; ayrıca komposto, tart ve tatlı soslarında pişirilir. Peynir tabaklarında, özellikle beyaz peynir ve cevizle birlikte de sıkça sunulur."]]],["Armut Kompostosu Nasıl Yapılır?",[["p","Soyulup dilimlenen armutlar su, şeker, tarçın çubuğu ve karanfille birlikte yumuşayana kadar kaynatılır. Soğutulup ılık ya da soğuk servis edilir."]]],["Fırında Armut",[["p","İkiye bölünen armutların çekirdek evi çıkarılır, üzeri bal ve tarçınla harmanlanıp fırında 20–25 dakika pişirilir. Dondurma ya da kaymakla servis edilir."]]],["Armut Hangi Tariflerle Kullanılır?",[["p","Armut kompostosu, fırında armut, armutlu tart ve armut-ceviz salatası en sevilen tariflerdendir. İnce dilimlenmiş armut, peynir tabaklarını da tamamlar."]]]],"s":[["Armut neye iyi gelir?","Armut; lif, C vitamini ve potasyum içeren, dengeli beslenmenin parçası olarak tüketilebilecek bir meyvedir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Armut ne zaman olgunlaşır?","Çoğu armut çeşidi ağaçta değil, toplandıktan sonra oda sıcaklığında olgunlaşır. Sapının dibi hafifçe yumuşadığında yemeye hazır demektir."],["Armut kabuğuyla mı yenir?","Evet, iyice yıkandığı sürece kabuğuyla yenebilir; kabukta ek lif ve bitkisel bileşikler bulunur."],["Armut kaç kalori?","Orta boy bir armut (yaklaşık 180 g) 100–105 kcal civarındadır; 100 gramında ise ortalama 57 kcal bulunur."],["Armut neden çabuk kararır?","Kesilen yüzeydeki enzimler oksijenle tepkimeye girip kahverengileşmeye neden olur. Limon suyu gezdirmek ya da soğuk suda bekletmek bu süreci yavaşlatır."]],"q":[["i-fire","Oda sıcaklığında olgunlaştır","Sapının dibi hafif yumuşayınca yenmeye hazırdır"],["i-droplet","Kesince limonla","Kararmayı geciktirir"],["i-arrow-rotate-left","Alternatifi","Elma, ayva"]],"i":["avokado","elma","cilek"],"ic":"i-apple-whole","l":"Pyrus communis","n":["(100 g çiğ)",[["Enerji","57 kcal"],["Protein","0,4 g"],["Lif","3,1 g"],["Karbonhidrat","15,2 g"],["C Vitamini","4,3 mg"],["Potasyum","119 mg"]]],"tb":"Armutlu tarifler","t":[{"a":"Ballı Cevizli Fırın Armudu | Tarçınlı Fırın Armudu","k":"Meyve Tarifleri","g":"1384","d":"35 dk","z":"Kolay","p":"4 kişilik","s":"Burcu Menemencioğlu","r":"5,0","b":2},{"a":"Yoğurtlu Armut Ezmesi | 8 Ay ve Üzeri Bebekler İçin","k":"Bebek Tarifleri","g":"1410","d":"15 dk","z":"Çok Kolay","p":"2 kişilik","s":"Bora Küçükler","r":"0,0","b":1},{"a":"Armut Reçeli | Karanfilli Ev Yapımı Tarif","k":"Reçel","g":"2394","d":"65 dk","z":"Kolay","p":"28 kişilik","s":"Rüya Pekkan","r":"3,0","b":1}]},
"arpacik-sogani":{"a":"Arpacık Soğanı","k":"Sebze","e":"Küçük yumuşak soğan","o":"Küçük boylu, hafif tatlı ve narin aromalı bir soğan çeşidi (şalot). Bütün soğanlanan yemeklerde, sos ve turşularda ince lezzetiyle sevilir.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, çiğ)","72 kcal"],["i-box-archive","Saklama (nemden ve ışıktan korunmalı)","Kuru-serin ve havadar yerde uzun süre"]],"b":[["Arpacık Soğanı Nedir?",[["p","Arpacık soğanı (<i>Allium cepa</i> var. <i>aggregatum</i>), baş soğandan daha küçük boylu, kümeler hâlinde büyüyen bir soğan çeşididir; mutfak dilinde çoğunlukla “şalot” olarak da anılır. Kahverengi-pembemsi kabuğu ve narin dişleriyle tanınır."],["p","Baş soğana göre daha yumuşak, tatlı ve ince bir aromaya sahiptir; keskinliği düşüktür. Bu narin lezzeti onu soslarda ve zarif yemeklerde soğanın tercih edilen biçimi hâline getirir."]]],["Arpacık Soğanının Besin Değerleri",[["p","100 gram çiğ arpacık soğanı yaklaşık 72 kcal enerji, 17 g karbonhidrat ve 3,2 g <b>lif</b> içerir; potasyuma katkı sağlar. Baş soğana benzer, biraz daha yoğun bir profile sahiptir."]]],["Arpacık Soğanının Faydaları Nelerdir?",[["p","Lif, potasyum ve soğangillere özgü bitkisel bileşikler içeriğiyle arpacık soğanı, dengeli beslenmenin lezzet katan bir parçası olarak değerlendirilebilir."],["p","Bu bilgiler geneldir; arpacık soğanı bir besindir, tıbbi tedavi yerine geçmez."]]],["Arpacık Soğanı Nasıl Seçilir?",[["p","İyi arpacık soğanı sıkı, kuru kabuklu ve filizlenmemiş olmalıdır; yumuşamış, filiz vermiş ya da küflü örnekler tercih edilmez."],["ul",["Baş sıkı ve ağır olmalı, yumuşamamış olmalı","Kabuk kuru ve bütün olmalı","Filizlenmiş ve küflü örnekler alınmamalı"]]]],["Arpacık Soğanı Nasıl Saklanır?",[["p","Arpacık soğanı kuru, serin ve havadar bir yerde, ağı ya da açık kapta uzun süre saklanır; nem ve ışıktan korunmalıdır. Buzdolabında nemden çabuk yumuşayabilir."]]],["Mutfakta Arpacık Soğanı Kullanımı",[["p","Arpacık soğanı yahni ve güveçlerde bütün olarak, soslarda ince kıyılmış olarak, salata soslarında (vinaigrette) çiğ olarak kullanılır; küçük boyu turşuluk için de idealdir. Karamelize edildiğinde tatlı bir garnitür olur."]]],["Arpacık Soğanı Nasıl Soyulur?",[["p","Kökü kesilip birkaç dakika sıcak suda bekletilen arpacık soğanının kabuğu kolayca soyulur; küçük olduğundan bütün soğanlamada zaman kazandırır."]]],["Arpacık Soğanı Karamelize Nasıl Yapılır?",[["p","Soyulan bütün arpacık soğanları az yağ ve bir tutam şekerle kısık ateşte, altın-kahve rengini alana dek yavaşça pişirilir; et yemeklerine tatlı bir garnitür olur."]]],["Arpacık Soğanı Hangi Tariflerle Kullanılır?",[["p","Soğanlı yahni, arpacık turşusu, vinaigrette sos ve karamelize soğan garnitürü en bilinen kullanımlarıdır."]]]],"s":[["Arpacık soğanı ile baş soğan arasındaki fark nedir?","Arpacık soğanı daha küçük, daha yumuşak ve tatlıdır; keskinliği azdır. Baş soğan daha iri ve daha keskindir."],["Arpacık soğanı turşuluk mudur?","Evet; küçük ve sıkı yapısı onu bütün hâlde turşu kurmaya çok uygun kılar."],["Arpacık soğanı çiğ yenir mi?","Evet; hafif ve tatlı aroması sayesinde salata ve soslarda çiğ olarak kullanılabilir."],["Arpacık soğanı yerine baş soğan kullanılır mı?","Kullanılabilir; ancak baş soğan daha keskin olduğundan miktarı ayarlanmalı, mümkünse daha az konulmalıdır."]],"q":[["i-circle-check","Küçük ve tatlı","Baş soğandan küçük, daha yumuşak ve tatlıdır"],["i-bowl-food","Bütün soğanlanır","Yahni ve güveçlerde bütün olarak kullanılır"],["i-jar","Turşuluk","Küçük boyu turşu için idealdir"]],"i":["ispanak","kabak","enginar"],"ic":"i-carrot","l":"Allium cepa var. aggregatum","n":["(100 g çiğ (USDA, şalot/arpacık soğanı))",[["Enerji","72 kcal"],["Karbonhidrat","17 g"],["Lif","3,2 g"],["Potasyum","334 mg"]]]},
"avokado":{"a":"Avokado","k":"Meyve","e":"Sağlıklı yağ","o":"Kremamsı dokusu ve tekli doymamış yağlarıyla öne çıkan tropik bir meyve. Kahvaltı tabağından tatlıya, salatadan soslara kadar çok yönlü kullanılır.","y":[["i-layer-group","Kategori","Meyve"],["i-calendar-days","Mevsim","Sonbahar–İlkbahar (yerli hasat)"],["i-fire","Kalori (100 g)","160 kcal"],["i-box-archive","Saklama (olgununu buzdolabında 2–3 gün)","Oda sıcaklığında olgunlaşır"]],"b":[["Avokado Nedir?",[["p","Avokado (<i>Persea americana</i>), defnegiller familyasından, tereyağı kıvamında etli bir meyvedir. Botanik olarak meyve sayılsa da tatlı değil, yağlı ve nötr bir karaktere sahip olduğu için mutfakta çoğunlukla sebze gibi kullanılır. Türkiye’de ağırlıkla Antalya ve Mersin çevresinde yetişir."],["p","İç etinin yumuşak ve kremamsı yapısı, onu ezmelerin, sosların ve tostların ideal malzemesi yapar. Ortasında iri bir çekirdeği bulunur; kabuğu çeşide göre pürüzlü koyu yeşilden düz açık yeşile kadar değişir."]]],["Avokadonun Besin Değerleri",[["p","Avokado enerjisinin büyük kısmını yağdan alır: 100 gramında yaklaşık 160 kcal ve 14,7 g yağ bulunur. Bu yağın önemli bölümü <b>tekli doymamış</b> türdendir. Ayrıca 6,7 g lif ve yüksek miktarda potasyum içermesiyle dikkat çeker; yağda eriyen vitaminlerin emilimine de katkıda bulunur."]]],["Avokadonun Faydaları Nelerdir?",[["p","İçerdiği tekli doymamış yağlar ve lif nedeniyle avokado, dengeli beslenmenin bir parçası olarak kalp sağlığını destekleyebilecek besinler arasında gösterilir. Yüksek potasyum içeriği ve tok tutan yapısı da öne çıkan özelliklerindendir."],["p","Bu ifadeler genel bilgi niteliğindedir; avokado bir besindir, herhangi bir rahatsızlığı iyileştirme iddiası taşımaz. Kalori yoğunluğu yüksek olduğundan porsiyon dengesi gözetilmelidir."]]],["Avokado Nasıl Seçilir?",[["p","Olgunluk avokadoda her şeydir. Hafifçe bastırıldığında az esneyen ama dağılmayan meyveler tüketime hazırdır; taş gibi sert olanlar birkaç gün beklemek ister."],["ul",["Sap yuvasını kaldır: altı canlı yeşilse olgun, kahverengiyse fazla olgunlaşmıştır.","Kabukta çökme ve yumuşak lekeler içinin ezildiğini gösterir.","Hemen tüketmeyeceksen sert olanı seçip evde olgunlaştır."]]]],["Avokado Nasıl Saklanır?",[["p","Sert avokado oda sıcaklığında birkaç günde olgunlaşır; süreci hızlandırmak için muz ya da elmayla aynı kağıt keseye konur. Olgun meyve buzdolabında 2–3 gün bekleyebilir. Kesilmiş yarısı, çekirdeği üstünde bırakılıp kesik yüzeyine limon sıkılarak ve streçlenerek daha yavaş kararır."]]],["Mutfakta Avokado Kullanımı",[["p","Avokado ısıyla iyi anlaşmaz; pişince acımsı bir tat alabilir. Bu yüzden çoğunlukla çiğ kullanılır ve sıcak yemeklere ocaktan alındıktan sonra, en son eklenir."]]],["Avokado Ezmesi (Guacamole) Nasıl Yapılır?",[["p","Olgun avokado çatalla ezilir; üzerine ince kıyılmış soğan, domates, limon suyu ve tuz eklenir. İsteğe göre kişniş ve acı biberle zenginleştirilir. Kararmaması için hemen servis edilmesi ya da yüzeyine limon sıkılması önerilir."]]],["Kahvaltıda Avokado",[["p","Kızarmış ekmek üzerine ezilmiş avokado, bir tutam tuz ve zeytinyağıyla klasik bir avokadolu tost olur. Yanına haşlanmış yumurta ya da peynir eşlik edebilir."]]],["Avokado Hangi Tariflerle Kullanılır?",[["p","Avokadolu tost, guacamole, avokadolu salata, poke kase ve avokadolu smoothie en yaygın tariflerdir. Kremamsı dokusu, çiğ salatalara yoğunluk ve içeceklere ipeksi bir kıvam kazandırır."]]]],"s":[["Avokado neye iyi gelir?","Avokado; tekli doymamış yağlar, lif ve potasyum açısından zengindir ve dengeli beslenmenin parçası olarak kalp sağlığını destekleyebilecek besinler arasında sayılır. Bir besindir, hastalık iyileştirme iddiası taşımaz."],["Avokado nasıl olgunlaştırılır?","Sert avokadoyu muz ya da elmayla birlikte kağıt bir keseye koyup oda sıcaklığında bekletmek 1–2 günde olgunlaşmayı hızlandırır. Olgunlaşınca buzdolabına alarak birkaç gün daha bekletebilirsin."],["Kesilen avokadonun kararması nasıl önlenir?","Kesik yüzeye limon ya da misket limonu suyu sürmek ve meyveyi çekirdeğiyle birlikte sıkıca streçleyip buzdolabında saklamak kararmayı belirgin şekilde yavaşlatır."],["Avokado pişirilir mi?","Genellikle çiğ tüketilir; uzun pişirme acımsı bir tat verebilir. Sıcak yemeklerde kullanılacaksa ocaktan alındıktan sonra en son eklenmesi lezzetini korur."],["Günde kaç avokado yenebilir?","Kalorisi ve yağ oranı yüksek olduğundan çoğu kişi için günde yarım ila bir avokado dengeli bir porsiyon kabul edilir. İhtiyaç kişiden kişiye değişir."]],"q":[["i-person","Olgunluk testi","Sap yuvası kolay çıkıp altı yeşilse hazır"],["i-apple-whole","Kararmayı önle","Kesik yüzeye limon suyu"],["i-fire","Hızlı olgunlaştır","Muzla aynı kese içinde 1–2 gün"]],"i":["elma","armut","cilek"],"ic":"i-apple-whole","l":"Persea americana","n":["(100 g)",[["Enerji","160 kcal"],["Yağ","14,7 g"],["Lif","6,7 g"],["Protein","2,0 g"],["Potasyum","485 mg"],["Karbonhidrat","8,5 g"]]],"tb":"Avokadolu tarifler","t":[{"a":"Avokado Muz Püresi | 6 Ay ve Üzeri Bebekler İçin","k":"Bebek Tarifleri","g":"1404","d":"5 dk","z":"Çok Kolay","p":"2 kişilik","s":"Ada Önür","r":"5,0","b":1},{"a":"Karidesli Yeşil Salata | Avokadolu","k":"Salata","g":"1461","d":"20 dk","z":"Kolay","p":"2 kişilik","s":"Burcu Erginsoy","r":"3,8","b":3},{"a":"Avokado Sos | Guacamole Usulü","k":"Sos","g":"1468","d":"10 dk","z":"Çok Kolay","p":"4 kişilik","s":"Esma Kasapoğlu","r":"4,0","b":2}]},
"badem":{"a":"Badem","k":"Kuruyemiş","e":"E vitamini deposu","o":"İnce kahverengi zarla kaplı, beyaz özlü bir kuruyemiş; çiğ, kavrulmuş, tuzlu ya da badem sütü/unu şeklinde geniş bir kullanım alanına sahiptir.","y":[["i-layer-group","Kategori","Kuruyemiş"],["i-calendar-days","Mevsim","Hasat: Yaz sonu, yıl boyu kuru olarak"],["i-fire","Kalori (100 g, çiğ)","579 kcal"],["i-box-archive","Saklama (hava almaz kapta)","Kuru serin yerde birkaç ay, buzdolabında daha uzun"]],"b":[["Badem Nedir?",[["p","Badem (<i>Prunus dulcis</i>), erik ve kayısıyla aynı familyadan bir ağacın çekirdeğidir; yenen kısım, sert bir kabuğun içindeki ince kahverengi zarla kaplı beyaz özdür. Akdeniz ve Orta Doğu kökenli olup Türkiye'nin özellikle Ege bölgesinde yetiştirilir."],["p","Tatlı badem çeşitleri mutfakta kullanılırken, acı badem türleri toksik bileşikler içerdiğinden işlenmeden tüketilmez. Hafif tatlımsı, yağlı bir tadı ve çıtır dokusu vardır."]]],["Bademin Besin Değerleri",[["p","Badem, yüksek yağ ve protein içeriğiyle doyurucu bir kuruyemiştir; 100 gramı yaklaşık 579 kcal enerji, 21,2 g protein ve 12,5 g lif barındırır. Özellikle <b>E vitamini</b> bakımından zengindir, ayrıca kalsiyum ve magnezyum gibi mineraller taşır."]]],["Bademin Faydaları Nelerdir?",[["p","Yüksek E vitamini, lif ve protein içeriğiyle badem, dengeli beslenmenin parçası olarak öne çıkan kuruyemişlerdendir. Porsiyon kontrollü tüketimin genel beslenme düzenine katkısı üzerine çalışmalar sürmektedir."],["p","Bu bilgiler geneldir; badem bir besindir, tıbbi tedavi yerine geçmez. Kuruyemiş alerjisi olanların dikkatli olması önerilir."]]],["Badem Nasıl Seçilir?",[["p","Kabuklu badem alırken ağırlığına bakmak en pratik yöntemdir; iç badem alırken tazelik ve renk göz önünde bulundurulmalıdır."],["ul",["Kabuklu badem elde tutulduğunda dolu ve ağır hissettirmeli.","İç bademin zarı açık kahverengi, özü krem-beyaz olmalı; koyulaşmış, buruşuk taneler bayatlamıştır.","Küf kokusu ya da acı yağ kokusu olmamalı."]]]],["Badem Nasıl Saklanır?",[["p","Kabuklu badem serin ve kuru bir yerde birkaç ay saklanabilir. Kabuğu soyulmuş iç badem, yağ oranı yüksek olduğundan hava almaz bir kapta buzdolabında saklandığında tazeliğini daha uzun korur; dondurucuda aylarca bekletilebilir."]]],["Mutfakta Badem Kullanımı",[["p","Badem çiğ, kavrulmuş, tuzlu, dilimlenmiş (badem yaprağı) ya da öğütülmüş (badem unu) formlarda kullanılır. Tatlıdan tuzluya geniş bir yelpazede yer alır: kurabiye ve kek hamuru, badem şekeri, salata garnitürü ve badem sütü en yaygın kullanımlarındandır."]]],["Badem Nasıl Soyulur?",[["p","İç badem kaynar suda yaklaşık 1 dakika bekletilip soğuk suya alınır; bu işlem ince zarın kolayca sıyrılmasını sağlar. Soyulmuş badem tatlı ve süsleme işlerinde daha zarif bir görünüm sunar."]]],["Badem Sütü Nasıl Yapılır?",[["p","Bir gece suda bekletilen bademler süzülüp temiz suyla birlikte blenderdan geçirilir, ardından tülbentten süzülerek ev yapımı badem sütü elde edilir. Süt yerine sos ve smoothie'lerde kullanılabilir."]]],["Badem Hangi Tariflerle Kullanılır?",[["p","Bademli kurabiye, badem unlu kek, bademli tarator ve badem şekeri en sevilen tariflerdendir. Dilimlenmiş badem, salata ve pilavlara çıtırlık katmak için de sıkça kullanılır."]]]],"s":[["Badem neye iyi gelir?","Badem; E vitamini, protein ve lif açısından zengindir ve dengeli beslenmenin parçası olarak öne çıkan kuruyemişlerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Günde kaç badem yenmeli?","Kalori yoğunluğu yüksek olduğundan günde bir avuç (yaklaşık 20–23 adet) makul bir porsiyon olarak kabul edilir. Kişisel ihtiyaçlar farklılık gösterebileceğinden diyetisyene danışmak en sağlıklısıdır."],["Acı badem yenir mi?","Hayır, çiğ acı badem toksik bileşikler (amigdalin) içerir ve işlenmeden tüketilmemelidir. Mutfakta kullanılan badem, güvenli olan tatlı badem çeşididir."],["Badem kabuğuyla mı soyulmadan mı saklanmalı?","Kabuklu badem dış etkenlere karşı daha korunaklı olduğundan daha uzun süre taze kalır. Soyulmuş iç badem pratik olsa da yağı havayla temas ettiğinden daha hızlı bayatlar."],["Badem unu buğday unu yerine kullanılabilir mi?","Kısmen; badem unu glutensiz tariflerde ve bazı kek-kurabiye formüllerinde buğday ununun bir kısmının yerini alabilir, ancak bağlayıcı gluten içermediğinden tarifin tamamen değiştirilmesi gerekebilir."]],"q":[["i-fire-burner","Kuru tavada uyandır","3–4 dk kavurma aromayı belirginleştirir"],["i-droplet","Kabuğunu soymak için haşla","1 dk kaynar suda bekletmek zarını gevşetir"],["i-arrow-rotate-left","Alternatifi","Fındık, kaju"]],"i":["ceviz","findik","antep-fistigi"],"ic":"i-seedling","l":"Prunus dulcis","n":["(100 g çiğ)",[["Enerji","579 kcal"],["Protein","21,2 g"],["Yağ","50 g"],["Lif","12,5 g"],["E Vitamini","25,6 mg"],["Kalsiyum","269 mg"]]],"tb":"Bademli tarifler","t":[{"a":"Acıbadem Kurabiyesi | Glutensiz Bademli Tarif","k":"Kurabiye","g":"1334","d":"45 dk","z":"Orta","p":"18 kişilik","s":"Ogün Fahri","r":"0,0","b":2},{"a":"Perde Pilavı | Siirt Usulü Tavuklu Perde Pilavı","k":"Pilav","g":"1549","d":"85 dk","z":"Zor","p":"6 kişilik","s":"İrem Ağaoğlu","r":"4,3","b":3},{"a":"Bademli Süt | Ev Yapımı Bitkisel Süt Alternatifi","k":"İçecek","g":"1618","d":"495 dk","z":"Kolay","p":"4 kişilik","s":"Ogün Fahri","r":"0,0","b":2}]},
"bakla":{"a":"Bakla","k":"Bakliyat","e":"İlkbahar sebzesi","o":"Taze halinde ilkbaharın müjdecisi, kuru halinde yıl boyu bulunan iri taneli bir bakliyat. Zeytinyağlısından ezmesine geniş bir kullanım alanı vardır.","y":[["i-layer-group","Kategori","Bakliyat"],["i-calendar-days","Mevsim","İlkbahar (taze) · Yıl boyu (kuru)"],["i-fire","Kalori (100 g, haşlanmış)","110 kcal"],["i-box-archive","Saklama (taze baklası buzdolabında 4–5 gün)","Kuru, kapalı kapta serin yerde 1 yıl"]],"b":[["Bakla Nedir?",[["p","Bakla (<i>Vicia faba</i>), iri, düz taneleriyle bilinen ve dünyanın en eski yetiştirilen bakliyatlarından biridir. Türkiye’de taze hâliyle ilkbaharın habercisi sayılır; olgunlaşıp kurutulduğunda ise yıl boyu tüketilebilen bir bakliyata dönüşür."],["p","Taze baklanın dış kabuğu (bakla kılıfı) ve iç tane zarı yenmeden ayıklanır; kuru baklada ise genelde iç zar da soyularak acılığı azaltılır."]]],["Baklanın Besin Değerleri",[["p","Haşlanmış 100 gram kuru bakla yaklaşık 110 kcal, 7,6 g <b>bitkisel protein</b> ve 5,4 g <b>lif</b> içerir. Demir ve folat açısından da zengindir."]]],["Baklanın Faydaları Nelerdir?",[["p","Bitkisel protein ve lif kaynağı olan bakla, dengeli beslenmenin parçası olarak taze sebze mevsiminde hafif bir seçenektir. Folat içeriği, geleneksel olarak özellikle bahar aylarında tüketilen besinler arasında değerli görülmesine katkı sağlar."],["p","Bu bilgiler geneldir; bakla bir besindir, tıbbi tedavi yerine geçmez. Favizm (G6PD eksikliği) rahatsızlığı olanların bakla tüketimi konusunda mutlaka doktoruna danışması gerekir."]]],["Bakla Nasıl Seçilir?",[["p","Taze baklada kılıf sertliği ve renk canlılığı, kuru baklada ise tane bütünlüğü ve rengi aranır."],["ul",["Taze bakla kılıfı parlak yeşil ve kırılınca çıtır sesi vermeli.","Kılıf içindeki taneler henüz küçükse bakla daha körpe ve tatlıdır.","Kuru baklada kırık tane ve toz oranı düşük olmalı."]]]],["Bakla Nasıl Saklanır?",[["p","Taze bakla buzdolabında delikli poşette 4–5 gün taze kalır; kılıfından ayıklanıp dondurulursa aylarca saklanabilir. Kuru bakla ise kapalı bir kapta serin ve karanlık bir dolapta 1 yıla kadar bozulmaz."]]],["Mutfakta Bakla Kullanımı",[["p","Taze bakla zeytinyağlı yemeklerde, kuru bakla ise çorba ve ezme kıvamındaki tariflerde değerlendirilir. Her iki hâli de dereotu ile iyi uyum sağlar."]]],["Zeytinyağlı Bakla Nasıl Yapılır?",[["p","Ayıklanmış taze bakla; soğan, zeytinyağı ve az suyla kısık ateşte 20–25 dakika pişirilir, üzerine dereotu ve limon eklenip soğuk servis edilir."]]],["Bakla Ezmesi Nasıl Yapılır?",[["p","Haşlanıp iç zarı soyulan kuru bakla; sarımsak, zeytinyağı ve limon suyuyla püre kıvamına getirilir. Mezelik olarak nane ve kırmızı toz biberle servis edilir."]]],["Bakla Hangi Tariflerle Kullanılır?",[["p","Zeytinyağlı bakla, bakla ezmesi, etli bakla yemeği ve baklalı pilav en sevilen tariflerdendir."]]]],"s":[["Bakla çiğ yenir mi?","Çok körpe taze bakla, iç zarı soyulduktan sonra çiğ olarak da tüketilebilir; ancak olgunlaşmış taneler sertleştiği ve acılaştığı için pişirilmesi önerilir."],["Bakla neye iyi gelir?","Bitkisel protein, lif ve folat açısından zengindir; dengeli beslenmenin parçası olarak değerlidir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Bakla neden acı olur?","Tane olgunlaştıkça iç zarı kalınlaşır ve hafif acı bir tat kazanır; bu yüzden olgun tanelerde iç zarın soyulması önerilir."],["Herkes bakla yiyebilir mi?","G6PD enzim eksikliği (favizm) olan kişilerde bakla ciddi bir reaksiyona yol açabilir; bu kişilerin bakla tüketmeden önce mutlaka doktoruna danışması gerekir."],["Taze bakla ile kuru bakla aynı şekilde mi pişirilir?","Hayır; taze bakla kısa sürede (20–25 dakika) pişerken kuru bakla önce ıslatılıp ardından 40–60 dakika haşlanmalıdır."]],"q":[["i-droplet","İç zarı soyulur","Kuru baklada acılığı azaltır"],["i-fire-burner","Taze baklada kısa pişirme","Fazla pişirmek rengini soldurur"],["i-arrow-rotate-left","Alternatifi","Kuru bakla yerine barbunya kullanılabilir"]],"i":["barbunya","kirmizi-mercimek","kinoa"],"ic":"i-seedling","l":"Vicia faba","n":["(100 g haşlanmış)",[["Enerji","110 kcal"],["Protein","7,6 g"],["Lif","5,4 g"],["Karbonhidrat","19,7 g"],["Demir","1,5 mg"]]],"tb":"Baklalı tarifler","t":[{"a":"Zeytinyağlı Bakla | Dereotlu Taze Bakla","k":"Zeytinyağlılar","g":"1522","d":"50 dk","z":"Kolay","p":"4 kişilik","s":"Ege Köylüoğlu","r":"4,5","b":1},{"a":"Ful Medames | Mısır Usulü Bakla Kahvaltısı","k":"Kahvaltılık","g":"1646","d":"30 dk","z":"Kolay","p":"4 kişilik","s":"Ada Tanrıkulu","r":"5,0","b":1},{"a":"Fıstıklı Baklava | Antep Fıstıklı Yufka Katlı Şerbetli Klasik","k":"Tatlı","g":"1875","d":"100 dk","z":"Ustalık Gerektirir","p":"20 dilim","s":"Ebru Tokatlıoğlu","r":"4,0","b":3}]},
"barbunya":{"a":"Barbunya","k":"Bakliyat","e":"Bitkisel protein","o":"Kırmızı-beyaz benekli taneleriyle tanınan, kurusu ve tazesiyle sevilen bir fasulye türü. Zeytinyağlı barbunya pilakisi Türk mutfağının klasik mezelerindendir.","y":[["i-layer-group","Kategori","Bakliyat"],["i-calendar-days","Mevsim","Yıl boyu (kuru); tazesi Yaz–Sonbahar"],["i-fire","Kalori (100 g, kuru çiğ)","335 kcal"],["i-box-archive","Saklama (kapalı kavanozda, ışıktan uzak)","Kuru serin yerde 6–12 ay"]],"b":[["Barbunya Nedir?",[["p","Barbunya (<i>Phaseolus vulgaris</i>), baklagiller familyasından, kırmızı-beyaz benekli kabuğuyla tanınan bir fasulye çeşididir. Hem taze hem kuru hâliyle tüketilir; kuruduğunda benekli deseni belirginleşir."],["p","Pişince kremamsı, hafif tatlımsı bir tada sahiptir; tanesi diğer fasulye türlerine göre biraz daha yumuşak bir dokuya sahiptir."]]],["Barbunyanın Besin Değerleri",[["p","Kuru barbunya yüksek protein ve lif içeriğiyle dikkat çeker; 100 gramı yaklaşık 335 kcal enerji, 23 g protein ve 24,7 g lif taşır. <b>Demir</b> ve <b>potasyum</b> bakımından da zengindir."]]],["Barbunyanın Faydaları Nelerdir?",[["p","Yüksek bitkisel protein ve lif içeriğiyle barbunya, dengeli beslenmenin parçası olarak öne çıkan baklagillerdendir. Baklagillerin genel özelliği olan yavaş sindirilen karbonhidrat yapısı, tokluk hissine katkı sağlayabilir."],["p","Bu bilgiler geneldir; barbunya bir besindir, tıbbi tedavi yerine geçmez."]]],["Barbunya Nasıl Seçilir?",[["p","Kuru barbunya alırken taneler pürüzsüz, parlak ve kırılmamış olmalıdır; taze barbunyada ise kabuk sıkı ve nemli görünümlü olmalıdır."],["ul",["Kuru tanelerde kırık, buruşuk veya delikli olanlar ayıklanmalı.","Taze barbunyada kabuk parlak ve sıkı olmalı, solmuş kabuklardan kaçınılmalı.","Aynı boydaki taneler tercih edilmeli; eşit pişme için önemlidir."]]]],["Barbunya Nasıl Saklanır?",[["p","Kuru barbunya kapalı bir kavanozda, serin ve ışıktan uzak bir yerde 6-12 ay saklanabilir. Pişmiş barbunya buzdolabında 3-4 gün, dondurucuda ise birkaç ay bekletilebilir."]]],["Mutfakta Barbunya Kullanımı",[["p","Barbunya en çok zeytinyağlı pilaki olarak, ayrıca etli yemeklerde ve salatalarda kullanılır. Kuru barbunya pişirilmeden önce bir gece suda bekletilirse hem daha kısa sürede pişer hem de sindirimi kolaylaşır."]]],["Barbunya Nasıl Pişirilir?",[["p","Bir gece ıslatılan barbunya süzülüp bol taze suyla kaynatılır; tuz, taneler yumuşadıktan sonra eklenir. Düdüklü tencerede 20-25 dakika, normal tencerede ise 1-1,5 saat pişer."]]],["Barbunya Hangi Tariflerle Kullanılır?",[["p","Zeytinyağlı barbunya pilakisi, etli barbunya yemeği ve barbunya salatası en bilinen tariflerdendir. Piyazlarda ve güveçlerde de sıkça kullanılır."]]]],"s":[["Barbunya neye iyi gelir?","Barbunya; bitkisel protein, lif, demir ve potasyum açısından zengindir, dengeli beslenmenin parçası olarak öne çıkan baklagillerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Barbunya neden ıslatılır?","Islatmak hem pişirme süresini kısaltır hem de baklagillerdeki bazı sindirimi zorlaştırıcı bileşiklerin bir kısmının suya geçmesini sağlar."],["Barbunya ıslatılmadan pişirilebilir mi?","Evet ama pişirme süresi belirgin şekilde uzar; acil durumlarda düdüklü tencere kullanmak süreyi kısaltabilir."],["Barbunya ile şeker fasulyesi aynı mı?","Barbunya ve şeker fasulyesi yakın akraba türlerdir, görünüşleri benzeyebilir; ancak barbunyanın benekleri genelde daha koyu kırmızı-kahverengi tonlardadır."],["Barbunya tuzlu suda mı pişirilmeli?","Tuz pişirmenin başında eklenirse tane kabuğunu sertleştirebilir; bu yüzden tuzun taneler yumuşadıktan sonra, pişirmenin son aşamasında eklenmesi önerilir."]],"q":[["i-droplet","Bir gece ıslatın","Islatmak pişirme süresini kısaltır ve sindirimi kolaylaştırır"],["i-fire-burner","Tuzu sona bırakın","Erken tuz ilavesi tanelerin sertleşmesine yol açar"],["i-arrow-rotate-left","Alternatifi","Şeker fasulyesi, kuru fasulye"]],"i":["kirmizi-mercimek","kinoa","nohut"],"ic":"i-seedling","l":"Phaseolus vulgaris","n":["(100 g kuru çiğ)",[["Enerji","335 kcal"],["Protein","23,0 g"],["Lif","24,7 g"],["Karbonhidrat","60,1 g"],["Demir","5,0 mg"],["Potasyum","1332 mg"]]],"tb":"Barbunyalı tarifler","t":[{"a":"Barbunya Pilaki | Zeytinyağlı Soğuk Servis","k":"Bakliyat","g":"1296","d":"85 dk","z":"Kolay","p":"5 kişilik","s":"Rüya Öymen","r":"0,0","b":1},{"a":"Barbunya Piyazı | Yumurtalı Meze Tabağı","k":"Meze","g":"1773","d":"65 dk","z":"Kolay","p":"4 kişilik","s":"Görkem Özberk","r":"0,0","b":1},{"a":"Barbunyalı Bulgur Pilavı | Zeytinyağlı Taze Fasulyeli Pilav","k":"Pilav","g":"1822","d":"55 dk","z":"Orta","p":"4 kişilik","s":"Emel Karaduman","r":"4,5","b":1}]},
"beyaz-biber":{"a":"Beyaz Biber","k":"Baharat","e":"Görünmez Baharat","o":"Karabiberle aynı bitkiden, olgunlaşmış tanelerin kabuğu soyularak elde edilen, daha keskin ve mayalı bir aromaya sahip beyaz renkli baharat. Açık renkli soslarda ve inceliğin arandığı yemeklerde tercih edilir.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, öğütülmüş)","296 kcal"],["i-box-archive","Saklama","Kapalı kavanozda serin, karanlık yerde 2-3 yıl (tane); öğütülmüş 1 yıl"]],"b":[["Beyaz Biber Nedir?",[["p","Beyaz biber (<i>Piper nigrum</i>), karabiberle tamamen aynı bitkiden elde edilir; fark, tanelerin tam olgunlaşmasının beklenip dış kabuğunun suda bekletilerek soyulmasıdır. Geriye kalan iç çekirdek kurutulunca beyaz biberi oluşturur."],["p","Karabibere göre daha az keskin ama daha mayalı, hafif ekşimsi bir aroması vardır; genellikle görünürlüğün istenmediği açık renkli yemeklerde tercih edilir."]]],["Beyaz Biberin Besin Değerleri",[["p","Beyaz biber 100 gramda yaklaşık 296 kcal enerji, 10,4 g protein ve 26,2 g lif içerir; demir açısından da dikkat çekici bir orana sahiptir. Ancak tarifte kullanılan miktar (bir tutam) çok küçük olduğundan günlük beslenmeye pratik bir katkısı yoktur."]]],["Beyaz Biberin Faydaları Nelerdir?",[["p","Beyaz biber, karabiber gibi piperin içerir; piperin üzerine çeşitli araştırmalar sürmektedir, ancak bu bulgular henüz kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; beyaz biber bir baharattır, tıbbi tedavi yerine geçmez."]]],["Beyaz Biber Nasıl Seçilir?",[["p","Kaliteli beyaz biber tanesi krem-bej renginde, sert ve düzgün yüzeyli olmalıdır; grileşmiş, tozlu ya da kokusuz taneler bayatlamıştır."],["ul",["Tane rengi krem-bej olmalı; kararmış taneler eskimiştir.","Öğütüldüğünde keskin, mayalı bir koku yayması taze olduğunun işareti.","Mümkünse tane hâlde alınıp kullanılacağı zaman öğütülmeli."]]]],["Beyaz Biber Nasıl Saklanır?",[["p","Beyaz biber taneleri, kapalı bir kavanozda serin ve karanlık bir yerde 2-3 yıla kadar aromasını korur; öğütülmüş hâli ise daha hızlı bayatladığından yaklaşık 1 yıl içinde tüketilmesi önerilir."]]],["Mutfakta Beyaz Biber Kullanımı",[["p","Beyaz biber; beşamel sos, patates püresi, açık renkli çorbalar ve bazı deniz ürünü yemeklerinde, siyah benek bırakmaması istendiğinde tercih edilir."]]],["Beşamel Sosta Beyaz Biber Nasıl Kullanılır?",[["p","Sos pişerken bir tutam beyaz biber eklenir; hem hafif keskin bir aroma katar hem de sosun açık renginin bozulmasını önler."]]],["Beyaz Biber Hangi Tariflerle Kullanılır?",[["p","Beşamel soslu makarna, patates püresi, balık çorbası ve bazı Uzak Doğu mutfağı tariflerinde beyaz biber kullanılır."]]]],"s":[["Beyaz biber ile karabiber arasındaki fark nedir?","İkisi de aynı bitkiden (Piper nigrum) elde edilir; karabiber olgunlaşmamış tanenin kabuğuyla birlikte kurutulmasıyla, beyaz biber ise olgun tanenin kabuğu soyulup iç çekirdeğin kurutulmasıyla elde edilir. Beyaz biber daha az keskin, daha mayalı bir tada sahiptir."],["Beyaz biber neden açık renkli yemeklerde tercih edilir?","Beyaz biberin rengi, açık renkli soslarda ve püre gibi yemeklerde siyah benekler bırakmadığından, görsel bütünlüğü bozmadan baharat aroması katmak için tercih edilir."],["Beyaz biber nasıl üretilir?","Olgunlaşmış kırmızı-yeşil biber taneleri birkaç gün suda bekletilir, bu süreçte dış kabuk yumuşayıp ayrılır; geriye kalan çekirdek yıkanıp kurutularak beyaz biber elde edilir."],["Beyaz biber daha mı acıdır?","Beyaz biber genellikle karabiberden biraz daha az keskin kabul edilir, ancak fermantasyon sürecinden dolayı daha mayalı-ekşimsi bir tat notu taşır."],["Beyaz biber tane mi toz mu tercih edilmeli?","Mümkünse tane hâlde alınıp kullanılacağı an öğütülmesi önerilir; hazır toz beyaz biber, tane hâline göre çok daha hızlı aromasını kaybeder."]],"q":[["i-ban","Açık renkli soslarda kullan","Beyaz renginden dolayı beşamel gibi soslarda siyah leke bırakmaz"],["i-mortar-pestle","Tane hâlde öğüt","Kullanmadan önce öğütülürse aroması çok daha güçlü olur"],["i-arrow-rotate-left","Alternatifi","Karabiber daha keskin ama görünürlüğü fark eden bir alternatiftir"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Piper nigrum","n":["(100 g öğütülmüş)",[["Enerji","296 kcal"],["Protein","10,4 g"],["Yağ","2,1 g"],["Karbonhidrat","68,6 g"],["Lif","26,2 g"],["Demir","14,3 mg"]]],"tb":"Beyaz biberli tarifler","t":[{"a":"Çin Böreği | Kıymalı Kızartma Hamur Kesesi","k":"Hamur İşi","g":"1567","d":"60 dk","z":"Orta","p":"15 dilim","s":"Ebru Ozansoy","r":"5,0","b":1},{"a":"Deniz Tarağı Sote | Sarımsaklı Beyaz Biberli","k":"Balık ve Deniz Ürünleri","g":"2796","d":"25 dk","z":"Orta","p":"2 kişilik","s":"Sarp Bakırcıoğlu","r":"4,0","b":3},{"a":"Ekşi Tatlı Çorba | Çin Usulü Baharatlı Mantarlı Çorba","k":"Çorba","g":"","d":"35 dk","z":"Orta","p":"5 kişilik","s":"Ece Özdenak","r":"0,0","b":1}]},
"beyaz-peynir":{"a":"Beyaz Peynir","k":"Peynir","e":"Kahvaltı klasiği","o":"Sağılan sütün mayalanıp salamura edilmesiyle elde edilen, Türk kahvaltı sofralarının vazgeçilmez peyniri. İnek, koyun ya da keçi sütünden, farklı yağ oranlarında üretilir.","y":[["i-layer-group","Kategori","Peynir"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g (yaklaşık, yağ oranına göre değişir))","~264 kcal"],["i-box-archive","Saklama (açıldıktan sonra kapalı kapta)","Buzdolabında salamurasında 2–3 hafta"]],"b":[["Beyaz Peynir Nedir?",[["p","Beyaz peynir, inek, koyun, keçi sütü ya da bunların karışımından yapılan, mayalandıktan sonra salamurada olgunlaştırılan bir peynir türüdür. Türkiye'nin hemen her bölgesinde üretilen, kahvaltı sofralarının temel bileşenlerinden biridir."],["p","Yağ oranına göre tam yağlı, yarım yağlı ve light olarak sınıflandırılır; süt kaynağına ve olgunlaşma süresine göre kıvamı yumuşaktan serte, tadı hafiften keskine kadar değişebilir."]]],["Beyaz Peynirin Besin Değerleri",[["p","Beyaz peynir, kesin değerleri markaya ve yağ oranına göre değişmekle birlikte, benzer salamura peynirlere yakın olarak 100 gramda yaklaşık 264 kcal enerji ve 14,2 g protein içerir. Kalsiyum bakımından zengindir, ancak salamura süreci nedeniyle sodyum (tuz) oranı da yüksektir."]]],["Beyaz Peynirin Faydaları Nelerdir?",[["p","Protein ve kalsiyum içeriğiyle beyaz peynir, dengeli beslenmenin parçası olarak öne çıkan bir süt ürünüdür. Kalsiyumun kemik sağlığındaki rolü üzerine geniş bir literatür bulunmaktadır."],["p","Bu bilgiler geneldir; beyaz peynir bir besindir, tıbbi tedavi yerine geçmez. Yüksek tuz içeriği nedeniyle tansiyon takibi yapanların porsiyona dikkat etmesi önerilir."]]],["Beyaz Peynir Nasıl Seçilir?",[["p","Taze beyaz peynir salamurası berrak, kokusu hafif ekşimsi-sütlü olmalıdır."],["ul",["Yüzeyde sararma, küf ya da amonyak kokusu olmamalı.","Kıvamı elde dağılmayacak kadar bütün, aşırı kurumuş ya da sulanmış olmamalı.","Etiketteki üretim ve son kullanma tarihine, yağ oranına bakılmalı."]]]],["Beyaz Peynir Nasıl Saklanır?",[["p","Beyaz peynir kendi salamurasında buzdolabında 2–3 hafta saklanabilir; salamura hem tazeliği korur hem de tuz dengesini sağlar. Açılan paket, hava almayan bir kapta ve mümkünse az miktarda ilave salamura ile saklanmalıdır."]]],["Mutfakta Beyaz Peynir Kullanımı",[["p","Beyaz peynir en çok kahvaltı sofralarında dilim ya da küp halinde çiğ tüketilir; ayrıca börek içi, salata ve fırın tarifi malzemesi olarak da kullanılır. Yüksek tuz oranı nedeniyle tarife eklenirken ayrıca tuz eklemeden önce tadına bakılması önerilir."]]],["Peynirli Börek Nasıl Yapılır?",[["p","Ufalanmış beyaz peynir, maydanoz ve isteğe bağlı yumurtayla karıştırılıp yufka arasına sarılarak fırında ya da tavada peynirli börek hazırlanır."]]],["Beyaz Peynirin Tuzu Nasıl Azaltılır?",[["p","Peynir dilimleri birkaç saat ya da bir gece süt veya suda bekletilerek fazla tuzun bir kısmı giderilebilir; bu yöntem özellikle çok tuzlu peynirlerde tercih edilir."]]],["Beyaz Peynir Hangi Tariflerle Kullanılır?",[["p","Peynirli börek, peynirli mantı, çoban salatası ve peynirli omlet en sevilen kullanım alanlarıdır. Kahvaltı tabaklarında zeytin ve domatesle klasik bir üçlü oluşturur."]]]],"s":[["Beyaz peynir neye iyi gelir?","Beyaz peynir; protein ve kalsiyum açısından zengin bir süt ürünüdür ve dengeli beslenmenin parçası olarak öne çıkar. Herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Beyaz peynir açıkken mi kapalı paket mi tercih edilmeli?","Kapalı paket ürünler üretim koşulları ve son kullanma tarihi net olduğundan daha güvenilir bir tercih olabilir; açık peynir alınacaksa güvenilir, hijyenik satış noktaları tercih edilmelidir."],["Beyaz peynirin yağ oranları neyi ifade eder?","Yağ oranı, peynirin yapıldığı sütün yağ içeriğine göre belirlenir; tam yağlı daha kremamsı ve dolgun, light/yarım yağlı ise daha hafif ve daha az kalorilidir."],["Beyaz peynir dondurulabilir mi?","Dondurmak dokusunu gevrekleştirip su kaybına yol açabileceğinden önerilmez; beyaz peynir en iyi sonucu buzdolabında salamurasında saklandığında verir."],["Ezine peyniri ile beyaz peynir aynı mıdır?","Ezine peyniri, coğrafi işaretli, belirli bir bölgede koyun-keçi-inek sütü karışımıyla üretilen özel bir beyaz peynir türüdür; genel anlamda “beyaz peynir” kategorisinin tescilli bir alt çeşididir."]],"q":[["i-droplet","Salamurada sakla","Kuru kalırsa hızla sertleşip tuzlanır"],["i-scale-balanced","Yağ oranını kontrol et","Tam yağlı, yarım yağlı ve light çeşitleri vardır"],["i-arrow-rotate-left","Alternatifi","Lor peyniri, ezine peyniri"]],"i":["kasar-peyniri","lor-peyniri","tulum-peyniri"],"ic":"i-cheese","n":["(100 g (feta benzeri beyaz peynir verisine yakın, ~))",[["Enerji","~264 kcal"],["Protein","~14,2 g"],["Yağ","~21,5 g"],["Sodyum","~917 mg"],["Kalsiyum","~493 mg"]]],"tb":"Beyaz peynirli tarifler","t":[{"a":"Yunan Usulü Çoban Salatası | Klasik Horiatiki Tarifi","k":"Salata","g":"1279","d":"15 dk","z":"Çok Kolay","p":"4 kişilik","s":"Ahmet Ayaydın","r":"3,0","b":2},{"a":"Su Böreği | Fırında Kat Kat Peynirli Börek","k":"Hamur İşi","g":"1317","d":"85 dk","z":"Zor","p":"8 dilim","s":"Ali Öztuna","r":"5,0","b":2},{"a":"Sigara Böreği | Çıtır Peynirli Kızarmış Börek","k":"Hamur İşi","g":"1318","d":"35 dk","z":"Kolay","p":"6 kişilik","s":"İrem Yıldızoğlu","r":"4,2","b":1}]},
"brokoli":{"a":"Brokoli","k":"Sebze","e":"C vitamini deposu","o":"Koyu yeşil çiçekli tomurcuklarıyla turpgillerden besleyici bir kış sebzesi. Buharda, fırında ve sotede; salatadan çorbaya kadar çok yönlü kullanılır.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","Sonbahar–Kış"],["i-fire","Kalori (100 g, çiğ)","34 kcal"],["i-box-archive","Saklama (yıkanmadan, delikli poşette)","Buzdolabında 4–7 gün"]],"b":[["Brokoli Nedir?",[["p","Brokoli (<i>Brassica oleracea var. italica</i>), lahana ve karnabaharın akrabası olan turpgiller familyasından bir sebzedir. Yenen kısmı, henüz açmamış koyu yeşil çiçek tomurcuklarından oluşan sıkı başı ve etli sapıdır. Serin havayı sever; Türkiye’de en lezzetli dönemi sonbahar ve kıştır."],["p","Hafif fındığımsı ve toprağımsı bir tadı vardır; doğru pişirildiğinde çıtır kalır, fazla pişirildiğinde ise yumuşayıp kendine has kükürtlü kokusunu belirginleştirir. Bu yüzden mutfakta en kritik nokta pişirme süresidir."]]],["Brokolinin Besin Değerleri",[["p","Brokoli düşük kalorili ama besin yoğunluğu yüksek bir sebzedir; 100 gramı yaklaşık 34 kcal enerji, 2,8 g protein ve 2,6 g lif içerir. Özellikle <b>C vitamini</b> ve <b>K vitamini</b> bakımından zengindir, ayrıca folat ve çeşitli bitkisel bileşikler taşır."]]],["Brokolinin Faydaları Nelerdir?",[["p","Yüksek lif ve vitamin içeriğiyle brokoli, dengeli beslenmenin bir parçası olarak öne çıkan sebzelerdendir. İçerdiği bitkisel bileşikler (ör. sülforafan) üzerine araştırmalar sürmektedir; bu çalışmalar henüz genel bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; brokoli bir besindir ve tıbbi tedavi yerine geçmez. Guatr ilacı kullananların turpgiller tüketimini uzmanına danışması önerilir."]]],["Brokoli Nasıl Seçilir?",[["p","Taze brokoli sıkı, koyu yeşil ve tomurcukları kapalı olandır; sararma ilk bayatlama işaretidir."],["ul",["Baş sıkı ve ağır olsun; dağınık, gevşek tomurcuk tazeliğini yitirmiştir.","Renk canlı koyu yeşil (bazen morumsu) olmalı; sarı tonlar yaşlanmayı gösterir.","Sap kesildiğinde nemli ve diri görünmeli, kurumuş-boşalmış olmamalı."]]]],["Brokoli Nasıl Saklanır?",[["p","Brokoli buzdolabının sebzeliğinde, yıkanmadan ve delikli bir poşette 4–7 gün tazeliğini korur. Nem bekletmek çürümeyi hızlandırdığından yıkama işlemi pişirmeden hemen önce yapılmalıdır. Uzun saklama için çiçekler ayrılıp kısa süre haşlandıktan (blanch) sonra dondurulabilir."]]],["Mutfakta Brokoli Kullanımı",[["p","Brokoli buharda, haşlanarak, fırında rostoyla ya da sotelenerek pişirilir. Besin değerini ve rengini en iyi koruyan yöntem, kısa süreli buharda pişirmedir. Çiçekler eşit boyda ayrılırsa hepsi aynı anda pişer."]]],["Buharda Brokoli Nasıl Yapılır?",[["p","Eşit boyda ayrılmış çiçekler, kaynayan suyun buharında 4–5 dakika, diri ve parlak yeşil kalacak şekilde pişirilir. Üzerine zeytinyağı, limon ve tuz gezdirilerek servis edilir; istenirse sarımsakla sotelenip zenginleştirilir."]]],["Fırında Brokoli",[["p","Çiçekler zeytinyağı, tuz ve karabiberle harmanlanıp yüksek ısılı fırında kenarları hafif kızarana dek 18–22 dakika kavrulur. Bu yöntem brokolinin doğal tatlılığını öne çıkarır."]]],["Brokoli Hangi Tariflerle Kullanılır?",[["p","Buharda brokoli, brokoli çorbası, fırında sebzeli brokoli, brokolili makarna ve tavuklu brokoli sote en sevilen tariflerdir. Haşlanmış çiçekler salatalara ve kahvaltı tabaklarına da eklenir."]]]],"s":[["Brokoli neye iyi gelir?","Brokoli; C ve K vitamini, folat ve lif açısından zengindir ve dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Brokoli ne kadar pişirilmeli?","Buharda 4–5 dakika, çiçekler diri ve parlak yeşil kalacak şekilde pişirmek yeterlidir. Fazla pişirmek hem dokusunu yumuşatır hem kükürtlü kokusunu artırır ve C vitamini kaybını hızlandırır."],["Brokoli çiğ yenir mi?","Evet, iyice yıkanmış brokoli çiğ olarak salatalarda tüketilebilir; çıtır dokusu ve tazeliğiyle sevilir. Sindirimi bazı kişilerde zorlayabildiğinden hafif buharda pişirmek daha rahat ettirebilir."],["Brokolinin sapı kullanılır mı?","Kesinlikle. Etli sap, dış kabuğu soyulduktan sonra ince doğranıp çiçeklerle birlikte pişirilebilir; hafif tatlı bir tadı vardır ve israfı önler. Çorbalarda özellikle iyi sonuç verir."],["Brokolinin kokusu nasıl azaltılır?","Kükürtlü koku fazla pişirmeyle artar; bu yüzden kısa süreli buharda pişirme en iyi yoldur. Pişirme suyuna bir dilim limon eklemek ve tencerenin kapağını tamamen kapatmamak da kokuyu hafifletir."]],"q":[["i-fire-burner","Buharda 4–5 dk","Diri ve parlak yeşil kalınca en lezzetli"],["i-droplet","Tuzlu suda beklet","Çiçekler arasındaki gizli kiri çıkarır"],["i-arrow-rotate-left","Alternatifi","Karnabahar, brüksel lahanası"]],"i":["ispanak","kabak","enginar"],"ic":"i-carrot","l":"Brassica oleracea var. italica","n":["(100 g çiğ)",[["Enerji","34 kcal"],["Protein","2,8 g"],["Lif","2,6 g"],["Karbonhidrat","6,6 g"],["C Vitamini","89 mg"],["K Vitamini","102 µg"]]],"tb":"Brokolili tarifler","t":[{"a":"Brokoli Patates Püresi | 8 Ay ve Üzeri Bebekler İçin","k":"Bebek Tarifleri","g":"1412","d":"23 dk","z":"Çok Kolay","p":"3 kişilik","s":"Bora Küçükler","r":"3,5","b":1},{"a":"Brokoli Çorbası | Kremalı Fırın Ekmekli","k":"Çorba","g":"1502","d":"40 dk","z":"Kolay","p":"4 kişilik","s":"Kutay Alyanak","r":"3,8","b":1},{"a":"Zeytinyağlı Brokolili Makarna | Sarımsaklı Akdeniz Tarifi","k":"Makarna","g":"1741","d":"25 dk","z":"Kolay","p":"4 kişilik","s":"Ahmet Örge","r":"2,9","b":1}]},
"ceviz":{"a":"Ceviz","k":"Kuruyemiş","e":"Omega-3 kaynağı","o":"Sert kabuğunun içinde kıvrımlı, yağ oranı yüksek bir çekirdek barındıran kışlık bir kuruyemiş. Kahvaltıdan tatlıya, salatadan hamur işine kadar mutfağın her köşesinde kullanılır.","y":[["i-layer-group","Kategori","Kuruyemiş"],["i-calendar-days","Mevsim","Sonbahar (hasat), yıl boyu kuru olarak"],["i-fire","Kalori (100 g, iç)","654 kcal"],["i-box-archive","Saklama (kırılmış iç hava almaz kapta buzdolabında)","Kabuklu serin ve kuru yerde aylarca"]],"b":[["Ceviz Nedir?",[["p","Ceviz (<i>Juglans regia</i>), Juglandaceae familyasından bir ağacın sert kabuklu meyvesidir; yenen kısmı bu kabuğun içindeki kıvrımlı, yağ oranı yüksek çekirdektir. Anadolu, ağacın doğal yayılış alanlarından biridir ve ceviz yüzyıllardır Türk mutfağının tanıdık bir kuruyemişidir."],["p","Taze (yaş) ceviz kısa bir mevsimde, kabuğu henüz sertleşmeden tüketilirken, kuru ceviz yıl boyu raf ömrü uzun bir kuruyemiş olarak bulunur. Hafif buruk, yağlı ve zengin bir tadı vardır."]]],["Cevizin Besin Değerleri",[["p","Ceviz, yağ oranı yüksek ama besin yoğunluğu da yüksek bir kuruyemiştir; 100 gram iç yaklaşık 654 kcal enerji, 15,2 g protein ve 65,2 g yağ içerir. Bu yağın önemli bir kısmı, bitkisel kaynaklar arasında nadir bulunan <b>omega-3 (ALA)</b> yağ asididir; ayrıca lif ve çeşitli mineraller taşır."]]],["Cevizin Faydaları Nelerdir?",[["p","Omega-3 yağ asidi ve lif içeriğiyle ceviz, dengeli beslenmenin parçası olarak öne çıkan kuruyemişlerdendir. Bitkisel kaynaklı omega-3 alımına katkısı üzerine çalışmalar sürmektedir; porsiyon kontrolü önemlidir çünkü kalori yoğunluğu yüksektir."],["p","Bu bilgiler geneldir; ceviz bir besindir, tıbbi tedavi yerine geçmez. Kuruyemiş alerjisi olanların dikkatli olması önerilir."]]],["Ceviz Nasıl Seçilir?",[["p","Kabuklu ceviz alırken ağırlığına bakmak en pratik yöntemdir; hafif kalan kabuklar genellikle boş ya da kurumuş içe işaret eder."],["ul",["Kabuklu ceviz elde tutulduğunda ağır ve dolu hissettirmeli; çıngırdayan, hafif olanlardan kaçının.","İç ceviz alırken renk canlı krem-bej olmalı; koyu kahverengi-siyah lekeler acılaşmayı gösterir.","Koklandığında küf ya da acı yağ kokusu olmamalı; taze cevizin kokusu hafif ve nötrdür."]]]],["Ceviz Nasıl Saklanır?",[["p","Kabuklu ceviz serin, kuru ve karanlık bir yerde aylarca saklanabilir; kabuk, içi hava ve ışıktan bir ölçüde korur. Kırılmış iç ceviz ise yağ oranı yüksek olduğundan çabuk acılaşır; hava almaz bir kapta buzdolabında birkaç ay, dondurucuda daha uzun süre tazeliğini korur."]]],["Mutfakta Ceviz Kullanımı",[["p","Ceviz çoğunlukla çiğ ya da hafif kavrulmuş olarak tüketilir; kavurma aromasını belirgin şekilde güçlendirir. Tatlıdan tuzluya geniş bir yelpazede kullanılır: baklava içi, kek ve kurabiye hamuru, cevizli sos ve salata garnitürü en yaygın kullanım alanlarıdır."]]],["Ceviz Nasıl Kavrulur?",[["p","İç cevizler kuru bir tavada orta ateşte 2–3 dakika, ara ara karıştırılarak kavrulur; koku belirginleşip hafif renk değiştirdiğinde ocaktan alınır. Fazla kavurmak acılaşmaya yol açabileceğinden süre kısa tutulmalıdır."]]],["Cevizli Sos Nasıl Yapılır?",[["p","Kavrulmuş ceviz, sarımsak, ekmek içi ve zeytinyağıyla robotta çekilerek Karadeniz mutfağının tanıdığı cevizli sos elde edilir; balık ve sebze yemeklerinin yanında servis edilir."]]],["Ceviz Hangi Tariflerle Kullanılır?",[["p","Cevizli baklava, cevizli kurabiye, cevizli erişte ve ceviz soslu salata en sevilen tariflerdendir. Kavrulmuş ceviz kırıntıları çorbalarda ve kahvaltı tabaklarında da sıkça kullanılır."]]]],"s":[["Ceviz neye iyi gelir?","Ceviz; omega-3 yağ asidi, protein ve lif açısından zengindir ve dengeli beslenmenin parçası olarak öne çıkan kuruyemişlerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Günde kaç ceviz yenmeli?","Kalori yoğunluğu yüksek olduğundan günde bir avuç (yaklaşık 5–7 adet iç ceviz) makul bir porsiyon olarak kabul edilir. Kişisel ihtiyaçlar farklılık gösterebileceğinden diyetisyene danışmak en sağlıklısıdır."],["Ceviz neden acılaşır?","Cevizdeki doymamış yağlar havayla temas ettiğinde oksitlenir ve acı bir tat oluşur. Bu süreci yavaşlatmak için iç ceviz serin, karanlık ve hava almayan koşullarda saklanmalıdır."],["Kabuklu ceviz mi iç ceviz mi tercih edilmeli?","Kabuklu ceviz, kabuğun koruyucu etkisi sayesinde daha uzun taze kalır ancak kırma zahmeti gerektirir. İç ceviz pratik olsa da acılaşmaya daha açıktır; tüketim hızına göre tercih yapılabilir."],["Cevizin yeşil dış kabuğu kullanılır mı?","Olgunlaşmamış cevizin yeşil dış kabuğu geleneksel olarak reçel ve bazı yöresel içeceklerde değerlendirilir, ancak elleri koyu renge boyayan güçlü bir boyayıcı özelliği vardır. Günümüz mutfağında yaygın kullanımı sınırlıdır."]],"q":[["i-fire-burner","Kuru tavada uyandır","2–3 dk kavurma aromayı katlar"],["i-snowflake","İçi soğukta sakla","Yağı oda sıcaklığında acılaşır"],["i-arrow-rotate-left","Alternatifi","Fındık, pekan cevizi"]],"i":["badem","findik","antep-fistigi"],"ic":"i-seedling","l":"Juglans regia","n":["(100 g iç, çiğ)",[["Enerji","654 kcal"],["Yağ","65,2 g"],["Protein","15,2 g"],["Karbonhidrat","13,7 g"],["Lif","6,7 g"],["Omega-3 (ALA)","9,1 g"]]],"tb":"Cevizli tarifler","t":[{"a":"İçli Köfte | Geleneksel Ovma İnce Kabuklu","k":"Köfte ve Kebap","g":"1286","d":"95 dk","z":"Ustalık Gerektirir","p":"6 kişilik","s":"Ebru Ozansoy","r":"0,0","b":2},{"a":"Revani | Şerbetli İrmik Tatlısı","k":"Tatlı","g":"1326","d":"50 dk","z":"Kolay","p":"8 dilim","s":"Koray Karaer","r":"0,0","b":1},{"a":"Kalburabastı | Cevizli Şerbetli Tarif","k":"Tatlı","g":"1327","d":"65 dk","z":"Orta","p":"8 kişilik","s":"Koray Karaer","r":"5,0","b":2}]},
"cheddar":{"a":"Cheddar","k":"Peynir","e":"Yoğun aromalı","o":"İngiltere kökenli, olgunlaştıkça sararan ve keskinleşen sert-yarı sert bir inek sütü peyniri. Sandviçte, burgerde ve eriyen sos tariflerinde sıkça tercih edilir.","y":[["i-layer-group","Kategori","Peynir"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g)","403 kcal"],["i-box-archive","Saklama","Buzdolabında, mumlu kağıda sarılı 3–4 hafta"]],"b":[["Cheddar Nedir?",[["p","Cheddar, İngiltere'nin Somerset bölgesindeki Cheddar köyünden adını alan, inek sütünden yapılan sert-yarı sert bir peynirdir. \"Cheddaring\" adı verilen özel bir işleme tekniğiyle üretilir; bu işlem peynire yoğun ve pürüzsüz bir doku kazandırır."],["p","Genç (hafif), olgun (keskin) ve ekstra olgun (çok keskin) gibi olgunlaşma derecelerine göre satılır; renk genellikle doğal krem tonundadır, turuncu cheddarlar ise annatto ile renklendirilir."]]],["Cheddarın Besin Değerleri",[["p","Cheddar, 100 gramında yaklaşık 403 kcal enerji, 23,7 g <b>protein</b> ve 721 mg kalsiyum içeren, yoğun besinli bir peynirdir. Yüksek yağ oranı, onu enerji yoğunluğu fazla bir besin yapar."]]],["Cheddarın Faydaları Nelerdir?",[["p","Yüksek kalsiyum ve protein içeriğiyle cheddar, dengeli beslenmenin bir parçası olarak tercih edilebilecek peynirlerdendir. Yağ ve kalori yoğunluğu nedeniyle porsiyon kontrolü önemlidir."],["p","Bu bilgiler geneldir; cheddar bir besindir, tıbbi tedavi yerine geçmez. Kolesterol takibi olan kişiler tüketim miktarına dikkat etmelidir."]]],["Cheddar Nasıl Seçilir?",[["p","Cheddar seçerken istenen keskinlik derecesine (genç-olgun-ekstra olgun) ve dokunun pürüzsüz, çatlaksız olmasına dikkat edilmelidir."],["ul",["Genç cheddar daha yumuşak ve hafif tatlıdır, sandviç için uygundur.","Olgun ve ekstra olgun cheddar daha keskin ve ufalanabilir bir dokuya sahiptir.","Ambalajın hasarsız ve son kullanma tarihinin uzak olması tazelik göstergesidir."]]]],["Cheddar Nasıl Saklanır?",[["p","Cheddar buzdolabında, önce mumlu kağıda sonra folyoya sarılarak 3–4 hafta tazeliğini korur. Hava almayan plastik poşetler nem tutup küflenmeyi hızlandırabileceğinden tercih edilmemelidir."]]],["Mutfakta Cheddar Kullanımı",[["p","Cheddar; sandviç ve burgerlerde eritilerek, mac and cheese gibi kremalı soslarda, omlet ve kızarmış ekmek üzerinde kullanılır. Olgun cheddar ayrıca peynir tabaklarında tek başına da servis edilir."]]],["Cheddar Sos Nasıl Yapılır?",[["p","Tereyağı ve un kavrulup süt eklenerek beşamel bazlı bir sos hazırlanır; kısık ateşte rendelenmiş cheddar azar azar karıştırılarak eritilir, pürüzsüz bir kıvam elde edilene kadar devam edilir."]]],["Cheddar Hangi Tariflerle Kullanılır?",[["p","Cheeseburger, mac and cheese, cheddarlı omlet, grilled cheese sandviç ve nachos en bilinen cheddar tarifleridir."]]]],"s":[["Cheddar neye iyi gelir?","Cheddar; kalsiyum ve protein bakımından zengin bir peynirdir. Herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Turuncu cheddar ile beyaz cheddar arasındaki fark nedir?","İkisi de aynı üretim sürecinden geçer; turuncu renk, doğal bir bitki boyası olan annatto ile elde edilir ve tat üzerinde belirgin bir fark yaratmaz."],["Cheddar neden olgunlaştıkça keskinleşir?","Olgunlaşma süresi uzadıkça peynirdeki proteinler ve yağlar daha fazla parçalanır; bu süreç cheddara daha yoğun, keskin bir aroma ve daha ufalanabilir bir doku kazandırır."],["Cheddar mac and cheese için en iyi peynir midir?","Cheddar, iyi erime özelliği ve belirgin tadı nedeniyle mac and cheese tarifinin klasik tercihidir; genellikle daha nötr eriyen bir peynirle (ör. mozzarella) karıştırılarak da kullanılır."],["Cheddar dondurulabilir mi?","Cheddar dondurulabilir ancak çözüldüğünde dokusu daha ufalanır hale gelebilir; bu yüzden özellikle rendelenerek pişirilecek tariflerde kullanılması önerilir."]],"q":[["i-bowl-food","Burgerde erit","Kalın dilimler ısıyı tutup daha pürüzsüz erir"],["i-clock","Olgunluk seç","Genç cheddar yumuşak, olgun cheddar daha keskindir"],["i-arrow-rotate-left","Alternatifi","Kaşar, gouda"]],"i":["beyaz-peynir","kasar-peyniri","lor-peyniri"],"ic":"i-cheese","n":["(100 g)",[["Enerji","403 kcal"],["Protein","23,7 g"],["Yağ","33,1 g"],["Karbonhidrat","1,3 g"],["Kalsiyum","721 mg"]]],"tb":"Cheddarlı tarifler","t":[{"a":"Klasik Ev Burgeri | Cheddarlı Dana Burger","k":"Sandviç, Burger ve Dürüm","g":"1388","d":"27 dk","z":"Orta","p":"4 kişilik","s":"Ümran Numanoğlu","r":"4,0","b":2},{"a":"Tavuklu Tortilla Dürüm | Cheddarlı Meksika Usulü Wrap","k":"Sandviç, Burger ve Dürüm","g":"2471","d":"30 dk","z":"Kolay","p":"2 kişilik","s":"Bora Pektemek","r":"5,0","b":2},{"a":"Acılı Meksika Burger | Jalapeñolu Baharatlı Dana Burger","k":"Sandviç, Burger ve Dürüm","g":"2479","d":"40 dk","z":"Kolay","p":"2 kişilik","s":"Esma Karaböcek","r":"3,3","b":2}]},
"cemen":{"a":"Çemen","k":"Baharat","e":"Çemen otu tohumlu baharat harcı","o":"Çemen otu (boy tohumu) başta olmak üzere sarımsak, kırmızı biber ve baharatların su ile karıştırılıp macun kıvamına getirilmesiyle yapılan harç. En çok pastırmayı kaplamada kullanılır.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (çeşni/harç; az kullanılır)","—"],["i-box-archive","Saklama (macun hâli buzdolabında tutulur)","Buzdolabında, ağzı kapalı kapta"]],"b":[["Çemen Nedir?",[["p","Çemen, çemen otunun (boy tohumu; <i>Trigonella foenum-graecum</i>) öğütülmüş tohumu başta olmak üzere bol sarımsak, kırmızı toz biber ve suyun karıştırılmasıyla elde edilen, macun kıvamında bir baharat harcıdır. En bilinen kullanımı pastırmanın üzerini kaplamaktır."],["p","Kendine özgü, baharatlı ve hafif acımsı-toprağımsı bir aroması vardır. Türkçede “çemen” hem bu harcı hem de temel bileşeni olan çemen otu tohumunu anlatacak biçimde kullanılır."]]],["Çemenin Besin Değerleri",[["p","Çemen bir baharat harcı olarak çok az miktarda (kaplama ya da çeşni) kullanıldığından öğün besin değerine katkısı sınırlıdır; bu nedenle ayrıntılı bir besin tablosu verilmemiştir. Değeri yoğun aromasından gelir."]]],["Çemen Nasıl Kullanılmalı?",[["p","Çemen aroması yoğun olduğundan az miktarda kullanılır; en yaygın biçimi pastırmayı kaplamaktır, ayrıca bazı yemeklere baharat notası katmak için de değerlendirilir. Sarımsağı bol olduğundan güçlü bir tat verir."],["p","Bu bilgiler geneldir; çemen bir besindir, tıbbi tedavi yerine geçmez."]]],["Çemen Nasıl Seçilir?",[["p","İyi çemen (harç); taze, canlı renkli, hoş-baharatlı kokan ve kıvamı düzgün olandır. Ekşimiş, küflenmiş ya da kokusu bozulmuş harç tercih edilmez. Toz çemen otu ise canlı renkli ve güçlü kokan olmalıdır."],["ul",["Taze ve hoş-baharatlı kokmalı","Ekşimiş-küflenmiş olmamalı","Toz çemen otu canlı renkli olmalı"]]]],["Çemen Nasıl Saklanır?",[["p","Hazır çemen harcı buzdolabında, ağzı kapalı bir kapta saklanır; su içerdiğinden oda sıcaklığında çabuk bozulur. Toz çemen otu ise ağzı kapalı kavanozda, serin ve kuru yerde uzun süre dayanır."]]],["Mutfakta Çemen Kullanımı",[["p","Çemen en çok pastırma kaplamada; ayrıca bazı yöresel yemek, çorba ve baharat karışımlarında (çemen otu tohumu olarak köri ve harçlarda) kullanılır. Harç hâli et kaplamada, toz hâli ise baharat olarak değerlendirilir."]]],["Çemen ile Çemen Otu Aynı mı?",[["p","Çemen otu bitkinin tohumudur; çemen (harç) ise bu tohumun sarımsak, biber ve suyla macun hâline getirilmiş şeklidir. Biri hammadde, diğeri ondan yapılan karışımdır."]]]],"s":[["Çemen neden pastırmada kullanılır?","Çemen harcı pastırmayı kaplayarak ona karakteristik aromasını ve dış katmanını kazandırır; aynı zamanda yüzeyi örterek geleneksel kurutma-olgunlaştırma sürecine katkı sağlar."],["Çemen acı mıdır?","Çemen otu tohumu doğal olarak hafif acımsıdır; harca eklenen kırmızı biber de acılık katabilir. Genel tadı baharatlı ve keskindir, çok baskın olmayacak biçimde kullanılır."],["Evde çemen harcı yapılır mı?","Evet; toz çemen otu, ezilmiş sarımsak, kırmızı biber ve su karıştırılıp macun kıvamına getirilerek yapılır. Kıvam ve baharat oranı tercihe göre ayarlanır."]],"q":[["i-mortar-pestle","Çemen otundan","Öğütülmüş çemen otu tohumu esaslıdır"],["i-bacon","Pastırma harcı","En çok pastırmayı kaplamada kullanılır"],["i-carrot","Sarımsak-biber","Sarımsak ve kırmızı biberle harmanlanır"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Trigonella foenum-graecum","n":["(baharat harcı; çok az kullanıldığından tabloya işlenmez)",[["Kullanım","baharat harcı/kaplama"],["Ana bileşen","çemen otu tohumu"],["Aroma","baharatlı-hafif acımsı"]]],"tb":"Çemenli tarifler","t":[{"a":"Ghormeh Sabzi | İran Usulü Kuru Limonlu Otlu Kuzu Yahnisi","k":"Kırmızı Et","g":"","d":"130 dk","z":"Zor","p":"6 kişilik","s":"Göktürk Dizdar","r":"0,0","b":2},{"a":"Rfissa | Fas Usulü Mercimekli Tavuk ve Katmerli Ekmek","k":"Tavuk ve Hindi","g":"","d":"85 dk","z":"Orta","p":"6 kişilik","s":"Cem Aydan","r":"0,0","b":2}]},
"ceri-domates":{"a":"Çeri Domates","k":"Domates","e":"Tatlı ve sulu","o":"Küçük, yuvarlak ve yoğun tatlı-ekşi aromasıyla bilinen bir domates çeşidi. Salatalarda çiğ, fırında ise karamelize olarak tüketilir.","y":[["i-layer-group","Kategori","Domates"],["i-calendar-days","Mevsim","Yaz"],["i-fire","Kalori (100 g, çiğ)","18 kcal"],["i-box-archive","Saklama (buzdolabı aromasını azaltabilir)","Oda sıcaklığında 3–4 gün"]],"b":[["Çeri Domates Nedir?",[["p","Çeri domates (<i>Solanum lycopersicum</i>), patlıcangiller familyasından, normal domatesin küçük ve yuvarlak bir çeşididir. Adını kiraz büyüklüğündeki boyutundan alır."],["p","Kabuk-et oranı normal domatese göre daha yüksek olduğundan tadı genelde daha yoğun ve tatlıdır. Kırmızı, sarı ve turuncu gibi farklı renk çeşitleri bulunur."]]],["Çeri Domatesin Besin Değerleri",[["p","Çeri domates düşük kalorilidir; 100 gramı yaklaşık 18 kcal enerji taşır. <b>C vitamini</b> ve <b>potasyum</b> kaynağıdır, ayrıca likopen adı verilen bir bitkisel pigment içerir."]]],["Çeri Domatesin Faydaları Nelerdir?",[["p","Düşük kalori ve yüksek su içeriğiyle çeri domates, dengeli beslenmenin parçası olarak tercih edilen sebzelerdendir. İçerdiği likopen üzerine araştırmalar sürmektedir; bu çalışmalar henüz kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; çeri domates bir besindir, tıbbi tedavi yerine geçmez."]]],["Çeri Domates Nasıl Seçilir?",[["p","İyi bir çeri domates parlak kabuklu, sapı taze ve elde hafif ağırlık hissettirendir."],["ul",["Kabuk parlak ve gergin olmalı; buruşuk veya yumuşak domatesler bayatlamıştır.","Sap yeşil ve taze görünmeli; kurumuş sap uzun süre bekletildiğini gösterir.","Renk türüne göre homojen olmalı, yeşilimsi lekeler olgunlaşmamışlığı gösterir."]]]],["Çeri Domates Nasıl Saklanır?",[["p","Çeri domates en iyi aromasını oda sıcaklığında, doğrudan güneş almayan bir yerde 3-4 gün korur. Buzdolabında saklamak dokusunu unlaştırıp tadını azaltabilir; olgunlaşmamış domatesler oda sıcaklığında bekletilmelidir."]]],["Mutfakta Çeri Domates Kullanımı",[["p","Çeri domates en çok çiğ olarak salatalarda, ayrıca fırında kavrularak makarna soslarına ve mezelere eklenir. Bütün halde kullanılabildiği gibi ikiye kesilerek de tüketilir."]]],["Fırında Çeri Domates Nasıl Yapılır?",[["p","İkiye kesilen domatesler zeytinyağı, tuz ve kekik ile harmanlanıp yüksek ısılı fırında 15-20 dakika, kenarları hafif kızarana dek kavrulur. Bu yöntem doğal şekerini belirginleştirir."]]],["Çeri Domates Hangi Tariflerle Kullanılır?",[["p","Çeri domatesli salata, fırında çeri domatesli makarna, bruschetta ve kapreze en bilinen tariflerdendir. Şişte sebze ve mezelerde de sıkça yer alır."]]]],"s":[["Çeri domates neye iyi gelir?","Çeri domates; C vitamini, potasyum ve likopen açısından zengindir, dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Çeri domates buzdolabında mı saklanmalı?","Kısa süreli saklamada oda sıcaklığı tercih edilir; aroma ve doku daha iyi korunur. Uzun süre bekletilecekse buzdolabına konulabilir, ancak tüketmeden önce oda sıcaklığına gelmesi beklenmelidir."],["Çeri domates ile normal domates farkı nedir?","Çeri domates boy olarak küçüktür ve kabuk-et oranı daha yüksektir; bu da genellikle daha yoğun ve tatlı bir aroma anlamına gelir."],["Çeri domates dondurulabilir mi?","Evet, bütün olarak dondurulabilir; ancak çözüldüğünde dokusu yumuşadığından çoğunlukla pişmiş soslarda kullanılması önerilir."],["Sarı çeri domates ile kırmızısı arasında fark var mı?","Renk farkı büyük ölçüde farklı pigment oranlarından kaynaklanır; sarı çeşitler genellikle biraz daha az asidik ve hafif daha tatlı bir tat sunar."]],"q":[["i-droplet","Oda sıcaklığında saklayın","Soğuk aromayı ve dokuyu bozabilir"],["i-fire-burner","Fırında karamelize edin","Zeytinyağıyla kavrulunca doğal şekeri belirginleşir"],["i-arrow-rotate-left","Alternatifi","Kokteyl domates, salkım domates"]],"i":["kurutulmus-domates","pembe-domates","salkim-domates"],"ic":"i-carrot","l":"Solanum lycopersicum","n":["(100 g çiğ)",[["Enerji","18 kcal"],["Protein","0,9 g"],["Lif","1,2 g"],["Karbonhidrat","3,9 g"],["C Vitamini","13,7 mg"],["Potasyum","237 mg"]]]},
"cilek":{"a":"Çilek","k":"Meyve","e":"C vitamini deposu","o":"Parlak kırmızı rengi ve yoğun aromasıyla ilkbaharın habercisi olan bir meyve. Çiğ tüketimden reçele, tatlıdan smoothiye kadar geniş kullanım alanı vardır.","y":[["i-layer-group","Kategori","Meyve"],["i-calendar-days","Mevsim","İlkbahar"],["i-fire","Kalori (100 g, çiğ)","32 kcal"],["i-box-archive","Saklama","Buzdolabında 2–3 gün, yıkanmadan"]],"b":[["Çilek Nedir?",[["p","Çilek (<i>Fragaria × ananassa</i>), gülgiller familyasından, botanik olarak aslında bir “yalancı meyve”dir; gördüğümüz kırmızı gövde çiçek tablasının şişmesinden oluşur, gerçek meyveler ise yüzeyindeki minik sarı taneciklerdir."],["p","İlkbaharda hasat edilir, yoğun kokusu ve ekşi-tatlı dengesiyle tanınır. Türkiye’de Mersin ve Bursa gibi bölgeler çilek üretiminde öne çıkar."]]],["Çileğin Besin Değerleri",[["p","Çilek düşük kalorili ama besin yoğunluğu yüksek bir meyvedir; 100 gramı yaklaşık 32 kcal enerji içerirken, günlük ihtiyacın büyük kısmını karşılayacak kadar <b>C vitamini</b> barındırır. Ayrıca lif ve potasyum kaynağıdır."]]],["Çileğin Faydaları Nelerdir?",[["p","Yüksek C vitamini içeriğiyle çilek, dengeli beslenmenin parçası olarak öne çıkan meyvelerdendir. İçerdiği antioksidan bileşikler üzerine araştırmalar sürmektedir; bu çalışmalar henüz kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; çilek bir besindir, tıbbi tedavi yerine geçmez."]]],["Çilek Nasıl Seçilir?",[["p","Taze çilek parlak kırmızı, yeşil yapraklı ve sıkı dokuludur; beyazımsı uçlar henüz olgunlaşmadığının işaretidir."],["ul",["Renk baştan uca kırmızı olmalı; beyaz veya yeşilimsi bölge tazeliği eksik gösterir.","Yaprak tacı diri ve yeşil olsun, solmuş yapraklar bayatlama işaretidir.","Kutuda su birikintisi veya ezik tane varsa küflenme riski yüksektir."]]]],["Çilek Nasıl Saklanır?",[["p","Çilek buzdolabında, yıkanmadan ve sapları çıkarılmadan 2–3 gün taze kalır; nem çürümeyi hızlandırdığından yıkama işlemi yemeden hemen önce yapılmalıdır. Uzun saklama için yıkanıp saplarından ayrılan çilekler dondurulabilir."]]],["Mutfakta Çilek Kullanımı",[["p","Çilek en çok çiğ tüketilir; ayrıca reçel, tatlı sosu ve smoothie yapımında kullanılır. Kesilmeden önce yıkanması, aromasının ve dokusunun korunmasını sağlar."]]],["Çilek Reçeli Nasıl Yapılır?",[["p","Ayıklanan çilekler şeker ve limon suyuyla birlikte kaynatılıp koyulaşana kadar pişirilir. Ilıman ateşte pişirmek, meyvenin rengini ve aromasını korumaya yardımcı olur."]]],["Çilekli Smoothie",[["p","Dondurulmuş çilek, yoğurt ve az bal blenderdan geçirilerek hazırlanır. İstenirse muz ya da süt eklenerek kıvamı ve tadı zenginleştirilebilir."]]],["Çilek Hangi Tariflerle Kullanılır?",[["p","Çilekli cheesecake, çilek reçeli, çilekli smoothie ve çilekli salata en sevilen tariflerdendir. Dilimlenmiş çilek, kahvaltı tabaklarına ve pastalara da sıkça eklenir."]]]],"s":[["Çilek neye iyi gelir?","Çilek; C vitamini, lif ve potasyum içeren, dengeli beslenmenin parçası olarak tüketilebilecek bir meyvedir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Çilek ne zaman yıkanmalı?","Çilek yemeden ya da kullanmadan hemen önce yıkanmalıdır; erken yıkama nem tutarak küflenmeyi ve çürümeyi hızlandırır."],["Çilek dondurulabilir mi?","Evet, yıkanıp saplarından ayrıldıktan sonra tepside tek sıra halinde dondurulup ardından poşetlenebilir; smoothie ve tatlı yapımı için uygundur."],["Çilek kaç kalori?","100 gram çilek yaklaşık 32 kcal içerir; bir avuç (yaklaşık 150 g) çilek ise 48 kcal civarındadır."],["Çileğin yaprağı yenir mi?","Yaprak tacı genellikle yenmez, tüketim öncesi ayıklanır; ancak temiz ve organik yetiştirilmişse dekoratif amaçla bırakılabilir."]],"q":[["i-droplet","Yemeden hemen önce yıka","Erken yıkama çürümeyi hızlandırır"],["i-snowflake","Sapını sonra çıkar","Su almasını önler"],["i-arrow-rotate-left","Alternatifi","Ahududu, böğürtlen"]],"i":["avokado","elma","armut"],"ic":"i-apple-whole","l":"Fragaria × ananassa","n":["(100 g çiğ)",[["Enerji","32 kcal"],["Protein","0,7 g"],["Lif","2,0 g"],["Karbonhidrat","7,7 g"],["C Vitamini","58,8 mg"],["Potasyum","153 mg"]]],"tb":"Çilekli tarifler","t":[{"a":"Çilekli Pişmeyen Cheesecake | Bisküvi Tabanlı Soğuk Tatlı","k":"Dondurma ve Soğuk Tatlılar","g":"1337","d":"270 dk","z":"Kolay","p":"8 dilim","s":"Ebru Çörekçi","r":"4,0","b":2},{"a":"Çilek Reçeli | Ev Yapımı Klasik Tarif","k":"Reçel","g":"1338","d":"70 dk","z":"Kolay","p":"30 kişilik","s":"Ebru Çörekçi","r":"0,0","b":1},{"a":"Çilekli Smoothie | Muzlu Yoğurtlu Çilek Smoothie","k":"İçecek","g":"1374","d":"5 dk","z":"Çok Kolay","p":"2 kişilik","s":"Rüya Akal","r":"4,7","b":2}]},
"corek-otu":{"a":"Çörek Otu","k":"Baharat","e":"Simit Süsü","o":"Küçük, siyah ve köşeli taneleriyle tanınan, hafif acımsı ve kekik-kimyon arası bir tada sahip baharat. Ekmek, simit ve peynirlerin üzerinde sıkça görülür.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-box-archive","Saklama","Kapalı kavanozda serin, karanlık yerde 1-2 yıl"]],"b":[["Çörek Otu Nedir?",[["p","Çörek otu (<i>Nigella sativa</i>), düğünçiçeğigiller familyasından bir bitkinin küçük, siyah ve köşeli tohumlarından oluşan bir baharattır. 'Kara kimyon' ya da 'kalonji' gibi isimlerle de bilinir, ancak kimyonla botanik olarak ilgisi yoktur."],["p","Hafif acımsı, kekik ve kimyon arası bir tat ve kavrulunca belirginleşen odunsu bir aroma taşır. Türk mutfağında en çok simit, poğaça ve bazı peynirlerin üzerinde görülür."]]],["Çörek Otunun Besin Değerleri",[["p","Çörek otu için güvenilir, tek bir kamu kaynağına dayanan ayrıntılı besin değeri verisi bu ansiklopedi standardında doğrulanamadığından bu bölüm bilinçli olarak boş bırakılmıştır. Bir tarifte kullanılan miktar (bir tutam) çok az olduğundan, besin katkısı pratikte önemsizdir; kullanım amacı aroma ve görünümdür."]]],["Çörek Otunun Faydaları Nelerdir?",[["p","Çörek otu, geleneksel tıpta yüzyıllardır kullanılan ve günümüzde bitkisel bileşiği timokinon üzerinden çeşitli araştırmalara konu olan bir tohumdur; bu araştırmalar henüz kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; çörek otu bir baharattır, tıbbi tedavi yerine geçmez."]]],["Çörek Otu Nasıl Seçilir?",[["p","Kaliteli çörek otu koyu siyah renkte, kuru ve birbirine yapışmamış tanecikler hâlinde olmalıdır; nemlenmiş ya da topaklanmış tohumlardan kaçınılmalıdır."],["ul",["Tane rengi mat siyah olmalı; grileşmiş ya da soluk taneler bayatlamıştır.","Elle ovulduğunda hafif bir koku yayması tazeliğinin işaretidir.","Nemlenip topaklaşmamış, akıcı taneler tercih edilmeli."]]]],["Çörek Otu Nasıl Saklanır?",[["p","Çörek otu, kapalı bir kavanozda serin ve karanlık bir yerde 1-2 yıl saklanabilir. Nem almaması için kapağının sıkıca kapalı tutulması önemlidir."]]],["Mutfakta Çörek Otu Kullanımı",[["p","Çörek otu; simit, poğaça, ekmek ve bazı peynirlerin üzerinde süsleme ve aroma amacıyla kullanılır. Bazı tariflerde salata ve yoğurtlu mezelere de eklenir."]]],["Simitte Çörek Otu Nasıl Kullanılır?",[["p","Şekillendirilmiş simit hamuru fırına girmeden önce ıslatılıp susam ve çörek otu karışımına bulanır; pişerken tohumlar hamura yapışarak karakteristik görünümü ve aromayı verir."]]],["Çörek Otu Hangi Tariflerle Kullanılır?",[["p","Simit, poğaça, kaşar-çörek otlu ekmek ve bazı otlu peynirlerde çörek otu kullanılır; ayrıca bazı yoğurt ve salata tariflerinde de yer alır."]]]],"s":[["Çörek otu neye iyi gelir?","Çörek otu geleneksel olarak sindirim ve genel sağlık amacıyla tüketilmiştir; bir baharattır ve herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Çörek otu ile kimyon aynı şey midir?","Hayır; isimlerindeki benzerliğe rağmen çörek otu (Nigella sativa) ile kimyon (Cuminum cyminum) tamamen farklı bitkilerdir ve tat-koku profilleri de birbirinden ayrılır."],["Çörek otu kavrulmalı mı?","Kavrulması zorunlu değildir ama kuru tavada birkaç dakika hafifçe kavrulduğunda tohumların aroması belirgin şekilde güçlenir."],["Çörek otu yağı ile tohumu aynı şekilde mi kullanılır?","Hayır; çörek otu yağı genellikle takviye ya da harici kullanım amacıyla tüketilirken, tohum doğrudan mutfakta pişirme ve süsleme amacıyla kullanılır."],["Çörek otu hangi ekmeklerde kullanılır?","En çok simit ve bazı köy ekmeklerinin üzerinde kullanılır; bazı bölgesel tariflerde pide ve poğaça hamurlarına da eklenir."]],"q":[["i-wheat-awn","Ekmek üstüne serp","Pişirmeden önce hamurun üzerine serpilerek kullanılır"],["i-fire-burner","Hafif kavurma aromayı açar","Kuru tavada birkaç dakika kavrulduğunda kokusu belirginleşir"],["i-arrow-rotate-left","Alternatifi","Tam bir eşdeğeri yoktur; susam kısmen benzer bir görsel/doku katabilir"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Nigella sativa","tb":"Çörek otlu tarifler","t":[{"a":"Peynirli Poğaça | Yumuşacık Kahvaltı Poğaçası","k":"Hamur İşi","g":"1319","d":"80 dk","z":"Kolay","p":"12 kişilik","s":"İrem Yıldızoğlu","r":"4,3","b":1},{"a":"Tuzlu Kraker | Ev Yapımı Çıtır","k":"Atıştırmalık","g":"1357","d":"35 dk","z":"Kolay","p":"6 kişilik","s":"Ada Tanrıkulu","r":"0,0","b":1},{"a":"Tuzlu Peynirli Kurabiye | Çörek Otlu Tarif","k":"Kurabiye","g":"1479","d":"42 dk","z":"Kolay","p":"20 kişilik","s":"Burcu Erçetin","r":"3,0","b":1}]},
"defne-yapragi":{"a":"Defne Yaprağı","k":"Baharat","e":"Yemeklerin Klasiği","o":"Akdeniz kökenli defne ağacının kurutulmuş yapraklarından elde edilen, hafif acımsı ve odunsu aromaya sahip klasik bir baharat. Çorba, yahni, pilav ve turşularda demlenerek kullanılır.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, kuru yaprak)","313 kcal"],["i-box-archive","Saklama","Kapalı kavanozda serin ve karanlık yerde 1-2 yıl"]],"b":[["Defne Yaprağı Nedir?",[["p","Defne yaprağı (<i>Laurus nobilis</i>), Akdeniz kökenli, herdem yeşil defne ağacının sert, parlak yapraklarının kurutulmasıyla elde edilen bir baharattır. Antik dönemden beri hem mutfakta hem de sembolik olarak (defne tacı) kullanılmıştır."],["p","Taze yaprak sert ve hafif acı bir tada sahiptir; kurutulduktan sonra aroması yoğunlaşır ve pişirme sırasında yemeklere odunsu, hafif tatlımsı bir derinlik katar."]]],["Defne Yaprağının Besin Değerleri",[["p","Kuru defne yaprağı 100 gramda yaklaşık 313 kcal enerji, yüksek oranda lif (26,3 g) ve dikkat çekici düzeyde kalsiyum, demir ve magnezyum içerir. Ancak bir tencereye genellikle 1-2 yaprak atıldığından ve pişirme sonunda çıkarıldığından, bu değerlerin günlük beslenmeye pratikte bir katkısı yoktur."]]],["Defne Yaprağının Faydaları Nelerdir?",[["p","Defne yaprağı geleneksel olarak sindirimi rahatlatmak amacıyla demlenerek tüketilir; içerdiği uçucu yağlar üzerine çeşitli araştırmalar sürmektedir, ancak bu bulgular kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; defne yaprağı bir baharattır, tıbbi tedavi yerine geçmez."]]],["Defne Yaprağı Nasıl Seçilir?",[["p","Kaliteli kuru defne yaprağı koyu yeşil renkte, kırılgan ama parçalanmamış ve belirgin kokulu olmalıdır; solgun, tozlu ya da kokusuz yapraklar bayatlamıştır."],["ul",["Renk koyu yeşile yakın olmalı; kahverengiye dönmüş yapraklar eskimiştir.","İki yaprak birbirine sürtüldüğünde belirgin bir koku yayması taze olduğunun işaretidir.","Kırık parça yerine bütün yaprak tercih edilmeli; aroma daha uzun korunur."]]]],["Defne Yaprağı Nasıl Saklanır?",[["p","Defne yaprağı, kapalı bir kavanozda ışık görmeyen serin bir yerde 1-2 yıl saklanabilir. Zamanla rengi solup aroması zayıflar; bu noktada yenilenmesi önerilir."]]],["Mutfakta Defne Yaprağı Kullanımı",[["p","Defne yaprağı; et suları, çorbalar, yahniler, pilavlar ve turşularda pişirme suyuna eklenerek kullanılır. Genellikle pişirmenin başında eklenir ve servis öncesi yemekten çıkarılır."]]],["Defne Yapraklı Et Suyu Nasıl Yapılır?",[["p","Kaynayan et suyuna 1-2 defne yaprağı eklenip yavaş ateşte pişirilir; yaprak suya odunsu bir derinlik katar ve pişirme sonunda süzülerek çıkarılır."]]],["Turşuda Defne Yaprağı Nasıl Kullanılır?",[["p","Turşu kavanozuna sirkeli salamura ile birlikte 1-2 defne yaprağı eklenir; hem koruyucu hem aromatik bir katkı sağlar."]]],["Defne Yaprağı Hangi Tariflerle Kullanılır?",[["p","Kuru fasulye, et sote, tavuk suyu çorbası, pilav ve karışık turşu tariflerinde sıkça yer alır; genellikle diğer baharatlarla (karabiber, kimyon) birlikte kullanılır."]]]],"s":[["Defne yaprağı neye iyi gelir?","Defne yaprağı geleneksel olarak sindirimi rahatlatmak amacıyla demlenerek tüketilir; bir baharattır ve herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Defne yaprağı yemekte bırakılır mı, yenir mi?","Defne yaprağı yenmez; sert ve kesici kenarları olduğundan boğazda tahrişe yol açabilir, bu yüzden servis öncesi yemekten çıkarılması önerilir."],["Taze defne yaprağı ile kuru olanı arasında fark var mı?","Taze yaprak daha hafif ve keskin acı bir tada sahiptir; kurutulduktan sonra aroması yoğunlaşır ve daha yumuşak, odunsu bir karaktere döner. Tariflerde genellikle kuru olan tercih edilir."],["Defne yaprağı ne kadar süre pişirilmeli?","Aromasının yemeğe geçmesi için en az 15-20 dakika pişmesi yeterlidir; uzun pişen yahni ve çorbalarda baştan eklenip sonunda çıkarılır."],["Defne yaprağı hangi baharatlarla iyi gider?","Karabiber, kimyon, kekik ve karanfille uyumludur; özellikle et suları ve yahnilerde bu baharatlarla birlikte kullanılır."]],"q":[["i-leaf","Bütün yaprak kullan","Pişerken kırılıp yemeğe karışmaması için tercih edilir"],["i-clock","Yemeğin sonunda çıkar","Sert kenarları boğaza takılabileceğinden servis öncesi alınır"],["i-arrow-rotate-left","Alternatifi","Taze defne yaprağı bulunmazsa kuru olanı daha az miktarda kullanılır"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Laurus nobilis","n":["(100 g kuru yaprak)",[["Enerji","313 kcal"],["Protein","7,6 g"],["Lif","26,3 g"],["Kalsiyum","834 mg"],["Demir","43 mg"],["Magnezyum","120 mg"]]],"tb":"Defne yapraklı tarifler","t":[{"a":"Kuzu Tandır | Fırında Ağır Ateş Tarifi","k":"Kırmızı Et","g":"1280","d":"270 dk","z":"Orta","p":"6 kişilik","s":"Ahmet Ayaydın","r":"5,0","b":3},{"a":"İşkembe Kavurma | Sarımsaklı Tava","k":"Sakatat","g":"1494","d":"110 dk","z":"Orta","p":"4 kişilik","s":"Ebru Ekşioğlu","r":"4,0","b":2},{"a":"Dil Söğüş | Haşlanmış Dana Dili","k":"Sakatat","g":"1498","d":"115 dk","z":"Orta","p":"4 kişilik","s":"Atakan Gümüşpala","r":"0,0","b":2}]},
"dereotu":{"a":"Dereotu","k":"Ot","e":"İnce, tüylü yeşillik","o":"İnce, tüy gibi yapraklarıyla hafif anason kokusu taşıyan bir yeşillik. Zeytinyağlılar, yoğurtlu mezeler ve balık yemeklerinde Türk mutfağının vazgeçilmez otlarındandır.","y":[["i-layer-group","Kategori","Ot"],["i-calendar-days","Mevsim","İlkbahar–Yaz"],["i-fire","Kalori (100 g, taze)","43 kcal"],["i-box-archive","Saklama (nemli kağıt havluya sarılı)","Buzdolabında 4–6 gün"]],"b":[["Dereotu Nedir?",[["p","Dereotu (<i>Anethum graveolens</i>), maydanozgiller familyasından, ince ve tüy gibi yapraklara sahip bir yeşilliktir. Hafif anason ve limon notaları taşıyan kendine özgü bir aroması vardır. Türkiye'de özellikle zeytinyağlı sebze yemeklerinde ve yoğurtlu mezelerde sıkça kullanılır."],["p","Bitkinin hem yaprakları hem de tohumları (dereotu tohumu, farklı bir baharat olarak) mutfakta değerlendirilir; ancak \"dereotu\" denince genelde taze yaprak kısmı kastedilir."]]],["Dereotunun Besin Değerleri",[["p","Dereotu düşük kalorili bir yeşilliktir; 100 gramı yaklaşık 43 kcal enerji ve 3,5 g protein içerir. Özellikle <b>C vitamini</b> ve <b>kalsiyum</b> bakımından öne çıkar, ayrıca demir de sağlar."]]],["Dereotunun Faydaları Nelerdir?",[["p","Dereotu, C vitamini ve mineral içeriğiyle dengeli beslenmenin bir parçası olarak öne çıkan yeşilliklerdendir. Geleneksel olarak sindirimi rahatlatıcı bir ot olarak da tüketilir."],["p","Bu bilgiler geneldir; dereotu bir besindir ve tıbbi tedavi yerine geçmez."]]],["Dereotu Nasıl Seçilir?",[["p","Taze dereotu demeti canlı yeşil, ince tüylü ve solmamış olmalıdır."],["ul",["Yapraklar canlı yeşil ve dik duruyor olmalı; sararma bayatlama işaretidir.","Demet ıslak değil hafif nemli hissettirmeli; aşırı ıslaklık çürümeyi hızlandırır.","Ezildiğinde belirgin anason kokusu vermeli."]]]],["Dereotu Nasıl Saklanır?",[["p","Dereotu, nemli bir kağıt havluya sarılıp buzdolabının sebzeliğinde 4–6 gün tazeliğini korur. Sap uçları suya batırılmış bir bardakta da birkaç gün canlı tutulabilir. Uzun süreli saklama için yapraklar ince kıyılıp dondurucu poşetinde dondurulabilir; bu haliyle çorba ve yemeklerde direkt kullanılabilir."]]],["Mutfakta Dereotu Kullanımı",[["p","Dereotu zeytinyağlı bakla, enginar ve taze fasulye gibi sebze yemeklerinde, yoğurtlu soslarda ve balık yemeklerinde kullanılır. Aroması pişirmeyle zayıfladığından genellikle yemeğin son dakikalarında veya servis anında eklenir."]]],["Taze Dereotu Dondurularak Nasıl Saklanır?",[["p","Yıkanıp kurutulan dereotu ince kıyılır, küçük porsiyonlar hâlinde dondurucu poşetlerine veya buz kalıplarına konularak dondurulur. Dondurulmuş dereotu çözülmeden doğrudan pişen yemeğe eklenebilir; taze halinden daha yumuşak bir dokuya sahip olsa da aromasını büyük ölçüde korur."]]],["Dereotu Hangi Tariflerle Kullanılır?",[["p","Dereotlu enginar, zeytinyağlı bakla, yoğurtlu semizotu salatası ve dereotlu somon en sevilen tariflerdendir. Ayrıca cacık ve haydari gibi mezelere de taze kıyılarak eklenir."]]]],"s":[["Dereotu neye iyi gelir?","Dereotu C vitamini ve kalsiyum açısından zengindir; dengeli beslenmenin parçası olarak öne çıkan yeşilliklerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Dereotu pişirilir mi, çiğ mi kullanılır?","Genellikle çiğ veya yemeğin pişirme süresinin sonuna doğru eklenir; uzun süre kaynatılırsa aroması büyük ölçüde kaybolur. Zeytinyağlılarda soğuduktan sonra eklenmesi de yaygın bir yöntemdir."],["Dereotu ve maydanoz aynı şey mi?","Hayır, ikisi de yeşil yapraklı otlar olsa da farklı bitkilerdir. Dereotu ince tüy gibi yapraklara ve anasona yakın bir aromaya sahipken, maydanoz daha düz yapraklı ve daha nötr bir tada sahiptir."],["Dereotu tohumu ile dereotu yaprağı aynı mı kullanılır?","Hayır, farklı amaçlarla kullanılırlar. Yapraklar taze yeşillik olarak sebze ve salatalarda, tohumlar ise turşu ve marine sularında baharat olarak değerlendirilir; aroma yoğunlukları da birbirinden farklıdır."],["Dereotu hangi sebzelerle en iyi gider?","Enginar, bakla, taze fasulye, kabak ve semizotu gibi zeytinyağlı sebze yemekleriyle klasik bir uyum sergiler. Yoğurtlu soslarda da salatalık ile birlikte sık kullanılır."]],"q":[["i-utensils","İnce sapları da kullanılır","Yalnız uç kısmı değil ince saplar da doğranabilir"],["i-droplet","Servisten önce ekle","Pişirmenin sonunda eklenmezse aroma zayıflar"],["i-arrow-rotate-left","Alternatifi","Maydanoz (aroma farklı olsa da renk-doku benzer)"]],"i":["maydanoz","feslegen","nane"],"ic":"i-seedling","l":"Anethum graveolens","n":["(100 g taze)",[["Enerji","43 kcal"],["Protein","3,5 g"],["Lif","2,1 g"],["C Vitamini","85 mg"],["Kalsiyum","208 mg"],["Demir","6,6 mg"]]],"tb":"Dereotulu tarifler","t":[{"a":"Zeytinyağlı Enginar | Bezelyeli Etsiz Tarif","k":"Zeytinyağlılar","g":"1304","d":"60 dk","z":"Orta","p":"4 kişilik","s":"Rüya Evliyaoğlu","r":"3,0","b":2},{"a":"Poşe Yumurtalı Kızarmış Ekmek","k":"Yumurta Tarifleri","g":"1346","d":"15 dk","z":"Orta","p":"2 kişilik","s":"Derin Durmaz","r":"0,0","b":1},{"a":"Peynirli Tuzlu Muffin | Kaşarlı Kek","k":"Atıştırmalık","g":"1360","d":"40 dk","z":"Kolay","p":"6 kişilik","s":"Mert Doğan","r":"4,0","b":2}]},
"elma":{"a":"Elma","k":"Meyve","e":"Lif kaynağı","o":"Kabuğuyla birlikte yenen, çıtır dokusu ve ekşi-tatlı dengesiyle yıl boyu sofralarda yer bulan bir meyve. Çiğ tüketimden tatlıya, komposto ve salataya kadar geniş bir kullanım alanı vardır.","y":[["i-layer-group","Kategori","Meyve"],["i-calendar-days","Mevsim","Sonbahar (yıl boyu bulunur)"],["i-fire","Kalori (100 g, çiğ (kabuklu))","52 kcal"],["i-box-archive","Saklama (serin ve nemli ortamda)","Buzdolabında 3–4 hafta"]],"b":[["Elma Nedir?",[["p","Elma (<i>Malus domestica</i>), gülgiller familyasından, ılıman iklimlerde yetişen ve dünyada en çok tüketilen meyvelerden biridir. Yüzlerce çeşidi bulunur; kimi ekşi-mayhoş, kimi bal gibi tatlıdır. Türkiye’de Amasya, Isparta ve Niğde gibi bölgeler elma üretiminde öne çıkar."],["p","Kabuğu ince ve yenebilir olduğundan genellikle soyulmadan tüketilir. Odun gibi sert değil, çıtır ve sulu bir dokusu vardır; kesildiğinde havayla temas eden yüzeyi hızla kararır."]]],["Elmanın Besin Değerleri",[["p","Elma düşük kalorili, suyu bol bir meyvedir; 100 gramı yaklaşık 52 kcal enerji ve 2,4 g lif içerir. Kabuğunda yoğunlaşan lif, doygunluk hissine katkıda bulunur. Ayrıca az miktarda <b>C vitamini</b> ve potasyum barındırır."]]],["Elmanın Faydaları Nelerdir?",[["p","Yüksek lif içeriğiyle elma, dengeli beslenmenin parçası olarak sindirim düzenine katkıda bulunabilecek meyvelerdendir. Kabuğunda bulunan bitkisel bileşikler üzerine çeşitli araştırmalar sürmektedir."],["p","Bu bilgiler geneldir; elma bir besindir, tıbbi tedavi yerine geçmez."]]],["Elma Nasıl Seçilir?",[["p","Taze elma sert, pürüzsüz ve parlak kabuklu olandır; basınca hemen iz bırakmamalıdır."],["ul",["Kabuk gergin ve lekesiz olsun; buruşukluk bayatlama işaretidir.","Sapı diri ve yeşilimsi olmalı, kurumuş sap eski hasadı gösterir.","Elma elde tutulduğunda ağır hissettirmeli; hafiflik iç boşluğuna işaret edebilir."]]]],["Elma Nasıl Saklanır?",[["p","Elma buzdolabının sebzeliğinde 3–4 hafta tazeliğini korur; diğer meyvelerden ayrı tutulması önerilir çünkü saldığı etilen gazı komşu meyveleri hızla olgunlaştırır. Oda sıcaklığında birkaç gün dayanır ama daha çabuk yumuşar."]]],["Mutfakta Elma Kullanımı",[["p","Elma çoğunlukla çiğ tüketilir; ayrıca fırında, komposto ve reçel yapımında pişirilir. Kesildikten sonra kararmasını geciktirmek için üzerine birkaç damla limon suyu gezdirilebilir."]]],["Fırında Elma Nasıl Yapılır?",[["p","Çekirdek kısmı oyulan elmanın içine ceviz, tarçın ve az bal doldurulup orta ateşli fırında 25–30 dakika yumuşayana kadar pişirilir. Sıcak servis edildiğinde kış aylarının klasik tatlısıdır."]]],["Elma Kompostosu",[["p","Dilimlenmiş elmalar su, şeker ve tarçınla birlikte kaynatılıp yumuşayana kadar haşlanır. Soğuk ya da ılık servis edilebilir; karanfil eklenerek aroması zenginleştirilebilir."]]],["Elma Hangi Tariflerle Kullanılır?",[["p","Elmalı turta, fırında elma, elma kompostosu ve elmalı yulaf ezmesi en sık başvurulan tariflerdendir. Rendelenmiş elma, havuçlu salatalara ve kek hamurlarına da eklenir."]]]],"s":[["Elma neye iyi gelir?","Elma; lif, C vitamini ve potasyum içeren, dengeli beslenmenin parçası olarak tüketilebilecek bir meyvedir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Elma kabuğuyla mı yenir?","Evet, iyice yıkandığı sürece kabuğuyla yenmesi önerilir; lifin ve bazı bitkisel bileşiklerin önemli kısmı kabukta bulunur."],["Elma neden çabuk kararır?","Kesilen yüzeydeki enzimler havadaki oksijenle tepkimeye girip kahverengileşmeye yol açar. Üzerine limon suyu gezdirmek ya da soğuk suda bekletmek kararmayı yavaşlatır."],["Elma kaç kalori?","Orta boy bir elma (yaklaşık 180 g) 90–95 kcal civarındadır; 100 gramında ise ortalama 52 kcal bulunur."],["Elma dondurulabilir mi?","Evet, dilimlenip limon suyuyla harmanlandıktan sonra dondurulabilir; ancak çözüldüğünde dokusu yumuşar, bu yüzden çiğ tüketim yerine pişmiş tariflerde kullanılması önerilir."]],"q":[["i-droplet","Kabuğunu yıkayıp ye","Lifin büyük kısmı kabukta bulunur"],["i-snowflake","Serin sakla","Sıcakta hızla yumuşar ve un tadı alır"],["i-arrow-rotate-left","Alternatifi","Armut, ayva"]],"i":["avokado","armut","cilek"],"ic":"i-apple-whole","l":"Malus domestica","n":["(100 g çiğ, kabuklu)",[["Enerji","52 kcal"],["Protein","0,3 g"],["Lif","2,4 g"],["Karbonhidrat","13,8 g"],["C Vitamini","4,6 mg"],["Potasyum","107 mg"]]],"tb":"Elmalı tarifler","t":[{"a":"Elmalı Kurabiye | Tarçınlı İçli Tarif","k":"Kurabiye","g":"1333","d":"55 dk","z":"Kolay","p":"20 kişilik","s":"Ogün Fahri","r":"0,0","b":1},{"a":"Karışık Meyve Salatası | Ballı Naneli Meyve Salatası","k":"Meyve Tarifleri","g":"1378","d":"15 dk","z":"Çok Kolay","p":"4 kişilik","s":"Emel Tekand","r":"0,0","b":2},{"a":"Elma Kompostosu | Karanfilli Ev Yapımı Komposto","k":"Meyve Tarifleri","g":"1379","d":"30 dk","z":"Çok Kolay","p":"6 kişilik","s":"Emel Tekand","r":"5,0","b":1}]},
"enginar":{"a":"Enginar","k":"Sebze","e":"Lif kaynağı","o":"Yeşil-mor renkli, katmanlı yapraklarıyla dikkat çeken ilkbahar sebzesi. Zeytinyağlı yemeklerin klasiği; kalbi ve etli yaprak dipleriyle değerlendirilir.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","İlkbahar"],["i-fire","Kalori (100 g, çiğ)","47 kcal"],["i-box-archive","Saklama (sapları suya batırılmış halde)","Buzdolabında 3–4 gün"]],"b":[["Enginar Nedir?",[["p","Enginar (<i>Cynara cardunculus</i>), papatyagiller familyasından, açmamış çiçek tomurcuğu yenen bir sebzedir. Akdeniz kökenlidir; Türkiye'de özellikle Ege bölgesinde ilkbahar aylarında yoğun yetişir."],["p","Etli yaprak dipleri ve ortasındaki \"kalp\" kısmı yenir; yaprakların içindeki tüylü samanlık kısım çıkarılmadan tüketilmez. Hafif buruk, yer fıstığına yakın bir tadı vardır."]]],["Enginarın Besin Değerleri",[["p","Enginar diğer sebzelere göre nispeten yüksek lif içerir; 100 gramı yaklaşık 47 kcal enerji ve 5,4 g lif taşır. <b>Folat</b> ve <b>potasyum</b> bakımından zengindir, ayrıca magnezyum içerir."]]],["Enginarın Faydaları Nelerdir?",[["p","Yüksek lif içeriğiyle enginar, dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. İçerdiği bitkisel bileşikler (ör. sinarin) üzerine araştırmalar sürmektedir; bu çalışmalar henüz genel bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; enginar bir besindir, tıbbi tedavi yerine geçmez."]]],["Enginar Nasıl Seçilir?",[["p","Taze enginar sıkı kapanmış yapraklı, ağır ve sapı diri olandır; açılmış yapraklar bayatlamayı gösterir."],["ul",["Yapraklar sıkıca kapalı olmalı; gevşek, açılmış yapraklar tazeliğini yitirmiştir.","Elde sıkıldığında hafif gıcırtı sesi vermesi tazelik işaretidir.","Sap ucu kesildiğinde nemli ve yeşil görünmeli, kurumuş olmamalı."]]]],["Enginar Nasıl Saklanır?",[["p","Enginar, sapı kesilip suya batırıldıktan sonra buzdolabında 3-4 gün tazeliğini korur. Temizlenmiş enginar kalpleri limonlu suda bekletilip dondurularak uzun süre saklanabilir."]]],["Mutfakta Enginar Kullanımı",[["p","Enginar haşlanarak, zeytinyağlı olarak yavaş pişirilerek ya da kalpleri ayıklanıp sotelenerek değerlendirilir. Kesim sonrası hızla kararması nedeniyle limonlu suda bekletilmesi önemlidir."]]],["Enginar Nasıl Temizlenir?",[["p","Dış sert yapraklar koparılır, sap soyulur ve üst kısım kesilir; ortadaki tüylü samanlık bir kaşıkla kazınarak çıkarılır. Temizlenen enginar hemen limonlu suya atılarak kararması önlenir."]]],["Enginar Hangi Tariflerle Kullanılır?",[["p","Zeytinyağlı enginar, enginarlı bakla, enginar dolması ve enginar çorbası en bilinen tariflerdendir. Kalpler salata ve mezelerde de sıkça kullanılır."]]]],"s":[["Enginar neye iyi gelir?","Enginar; lif, folat ve potasyum açısından zengindir, dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Enginarın hangi kısmı yenir?","Yaprakların etli dipleri ve ortadaki kalp kısmı yenir; dış sert yapraklar ile tüylü samanlık kısmı atılır."],["Enginar neden kararır?","Enginarda bulunan bazı bitkisel bileşikler havayla temas edince oksitlenip kararır; kesim sonrası limonlu suda bekletmek bu reaksiyonu yavaşlatır."],["Konserve enginar taze olan kadar besleyici mi?","Konserve enginar pratik bir alternatiftir ancak işleme sırasında bir miktar C vitamini kaybı olabilir; buna karşın lif ve mineral içeriğinin büyük bölümünü korur."],["Enginar çiğ yenir mi?","Genç ve küçük enginarlar ince dilimlenip limonla marine edilerek çiğ tüketilebilir; olgun enginarlar ise sertliği nedeniyle pişirilerek tüketilir."]],"q":[["i-droplet","Limonlu suda bekletin","Kesilen enginar hızla kararır, limonlu su önler"],["i-fire-burner","Kalbini çıkarın","Tüylü kısım (samanlık) yenmez, kalp öncesi temizlenir"],["i-arrow-rotate-left","Alternatifi","Kereviz, bakla"]],"i":["ispanak","kabak","pirasa"],"ic":"i-carrot","l":"Cynara cardunculus","n":["(100 g çiğ)",[["Enerji","47 kcal"],["Protein","3,3 g"],["Lif","5,4 g"],["Karbonhidrat","10,5 g"],["Potasyum","370 mg"],["Folat","68 µg"]]],"tb":"Enginarlı tarifler","t":[{"a":"Zeytinyağlı Enginar | Bezelyeli Etsiz Tarif","k":"Zeytinyağlılar","g":"1304","d":"60 dk","z":"Orta","p":"4 kişilik","s":"Rüya Evliyaoğlu","r":"3,0","b":2},{"a":"Zeytinyağlı Enginarlı Makarna | Limonlu Bahar Tarifi","k":"Makarna","g":"1729","d":"35 dk","z":"Kolay","p":"4 kişilik","s":"İrem Ertürk","r":"4,0","b":2},{"a":"Enginarlı Pilav | Ege Usulü Zeytinyağlı Enginarlı Pirinç Pilavı","k":"Pilav","g":"1818","d":"60 dk","z":"Orta","p":"4 kişilik","s":"Emel Karaduman","r":"4,0","b":2}]},
"feslegen":{"a":"Fesleğen","k":"Ot","e":"İtalyan mutfağının imzası","o":"Tatlı, hafif karanfilimsi aromasıyla İtalyan ve Akdeniz mutfaklarının vazgeçilmez otu. Pestodan salataya, domatesli yemeklerden çaya kadar geniş kullanım alanı vardır.","y":[["i-layer-group","Kategori","Ot"],["i-calendar-days","Mevsim","İlkbahar–Sonbahar (sıcak havada yetişir)"],["i-fire","Kalori (100 g, taze)","23 kcal"],["i-box-archive","Saklama (buzdolabında soğuktan yaprakları kararabilir)","Oda sıcaklığında suda demet halinde 3–5 gün"]],"b":[["Fesleğen Nedir?",[["p","Fesleğen (<i>Ocimum basilicum</i>), nane familyasından, Güney Asya kökenli aromatik bir bitkidir. İtalyan mutfağında “basilico” adıyla bilinen, tatlı ve hafif karanfilimsi kokulu geniş yeşil yapraklı bir türdür."],["p","Türk mutfağında hem taze bir yeşillik hem de kurutulmuş baharat olarak kullanılır; ısıyla aroması hızla değişir, bu yüzden genellikle pişirmenin sonunda eklenir."]]],["Fesleğenin Besin Değerleri",[["p","Fesleğen az miktarda tüketilse de besin yoğunluğu yüksek bir yeşilliktir; 100 gramı yaklaşık 23 kcal enerji içerir. Özellikle <b>K vitamini</b> ve <b>A vitamini</b> bakımından zengindir, ayrıca C vitamini taşır."]]],["Fesleğenin Faydaları Nelerdir?",[["p","K ve A vitamini içeriğiyle fesleğen, dengeli beslenmenin parçası olarak öne çıkan bir yeşilliktir. Uçucu yağları üzerine yapılan araştırmalar sürmektedir; bu çalışmalar henüz genel bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; fesleğen bir besindir, tıbbi tedavi yerine geçmez."]]],["Fesleğen Nasıl Seçilir?",[["p","Taze fesleğen canlı yeşil, geniş ve pörsümemiş yapraklara sahip olmalıdır."],["ul",["Yapraklar parlak açık-koyu yeşil olmalı; kararmış ya da lekeli yapraklardan kaçının.","Demet koklandığında tatlı, hafif karanfilimsi bir koku vermelidir.","Sap dik ve diri durmalı, solmuş-eğilmiş sap tazeliğin azaldığını gösterir."]]]],["Fesleğen Nasıl Saklanır?",[["p","Fesleğen soğuğa hassas bir bitkidir; buzdolabında yaprakları kararıp kokusunu kaybedebilir. Sapları bir bardak suya batırılıp oda sıcaklığında, doğrudan güneş almayan bir yerde tutulursa 3–5 gün taze kalır. Uzun süreli saklama için yapraklar zeytinyağıyla robotta çekilip dondurulabilir."]]],["Mutfakta Fesleğen Kullanımı",[["p","Fesleğen çoğunlukla çiğ ya da pişirmenin son anında eklenir; uzun pişirme aromasını büyük ölçüde uçurur. Domatesli yemekler, salatalar ve İtalyan soslarıyla klasik bir eşleşmedir."]]],["Fesleğen Pestosu Nasıl Yapılır?",[["p","Taze fesleğen yaprakları, çam fıstığı (ya da ceviz), sarımsak, parmesan peyniri ve zeytinyağıyla robotta çekilerek klasik İtalyan sosu pesto elde edilir; makarna, ekmek ve ızgara sebzelerle servis edilir."]]],["Fesleğen Çayı Nasıl Yapılır?",[["p","Birkaç taze ya da kurutulmuş fesleğen yaprağı sıcak suda 5–8 dakika demlenerek hafif tatlımsı aromalı bir bitki çayı elde edilir; bal ile tatlandırılabilir."]]],["Fesleğen Hangi Tariflerle Kullanılır?",[["p","Fesleğen pesto, domates-fesleğen salatası (caprese), fesleğenli makarna ve zeytinyağlı sebze yemekleri en sevilen kullanım alanlarıdır. Pizza üzerine pişirmeden sonra eklenmesi aromasını korur."]]]],"s":[["Fesleğen neye iyi gelir?","Fesleğen; K vitamini, A vitamini ve C vitamini açısından zengin bir yeşilliktir ve dengeli beslenmenin parçası olarak öne çıkar. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Fesleğen neden buzdolabında kararır?","Fesleğen tropik kökenli bir bitki olduğundan düşük sıcaklıklara hassastır; buzdolabındaki soğuk, yaprak hücrelerine zarar vererek kararmaya yol açar. Oda sıcaklığında suda saklamak bu sorunu önler."],["Fesleğen çeşitleri nelerdir?","Tatlı (İtalyan) fesleğen en yaygın türdür; ayrıca Tayland fesleğeni ve mor fesleğen gibi farklı aroma ve görünüme sahip çeşitler de bulunur. Her biri farklı mutfaklarda tercih edilir."],["Fesleğen dondurulabilir mi?","Doğrudan dondurmak yaprakları kararttığından, fesleğenin zeytinyağıyla robotta çekilip buz kalıplarında dondurulması önerilir; bu yöntem aromayı büyük ölçüde korur."],["Kurutulmuş fesleğen taze fesleğenin yerini tutar mı?","Kısmen; kurutma işlemi aromayı yoğunlaştırıp değiştirir, bu yüzden kurutulmuş fesleğen genellikle taze olana göre daha az miktarda kullanılır. Pişmiş yemeklerde kurutulmuş, taze tüketimde ve son dokunuşta taze fesleğen tercih edilir."]],"q":[["i-snowflake","Buzdolabına koyma","Soğuk yaprakları kararmaya iter"],["i-person","Elle yırt, bıçakla kesme","Metal bıçak yaprağı kararmaya iter"],["i-arrow-rotate-left","Alternatifi","Nane (tatlar farklı, dikkatli değiştirin)"]],"i":["maydanoz","nane","dereotu"],"ic":"i-seedling","l":"Ocimum basilicum","n":["(100 g taze)",[["Enerji","23 kcal"],["Protein","3,2 g"],["Karbonhidrat","2,7 g"],["Lif","1,6 g"],["K Vitamini","415 µg"],["A Vitamini","264 µg"],["C Vitamini","18 mg"]]],"tb":"Fesleğenli tarifler","t":[{"a":"Margherita Pizza | Ev Yapımı İtalyan Pizzası","k":"Pizza ve Pide","g":"1314","d":"100 dk","z":"Orta","p":"4 dilim","s":"Ali Öztuna","r":"3,0","b":2},{"a":"Napoliten Makarna | Domates Soslu Fesleğenli Makarna","k":"Makarna","g":"1320","d":"35 dk","z":"Kolay","p":"4 kişilik","s":"İrem Yıldızoğlu","r":"4,0","b":1},{"a":"Domates Sos | Makarna Sosu","k":"Sos","g":"1449","d":"35 dk","z":"Çok Kolay","p":"4 kişilik","s":"Çağan Öymen","r":"4,0","b":1}]},
"findik":{"a":"Fındık","k":"Kuruyemiş","e":"E vitamini deposu","o":"Karadeniz kıyı şeridinin simgesi, gevrek dokusu ve tatlımsı aromasıyla sevilen bir kuruyemiş. Çiğ, kavrulmuş, ezme ve unlu mamullerde geniş kullanım alanı bulur.","y":[["i-layer-group","Kategori","Kuruyemiş"],["i-calendar-days","Mevsim","Ağustos–Eylül hasadı, tüm yıl tüketilir"],["i-fire","Kalori (100 g, çiğ)","628 kcal"],["i-box-archive","Saklama (hava almayan kapta, ışıktan uzak)","Kabuksuz halde serin kuru yerde 2–3 ay, buzdolabında 6 ay"]],"b":[["Fındık Nedir?",[["p","Fındık (<i>Corylus avellana</i>), fındıkgiller familyasından bir ağacın sert kabuklu meyvesidir. Türkiye, dünya fındık üretiminin büyük bölümünü karşılar; özellikle Karadeniz kıyı şeridi (Giresun, Ordu, Trabzon) fındık tarımının merkezidir."],["p","Yuvarlak, sert kahverengi kabuğunun içinde krem rengi, yağlı ve tatlımsı bir iç bulunur. Çiğ, kavrulmuş, kabuklu ya da kabuksuz; tek başına atıştırmalık olarak da tatlı ve tuzlu tariflerde malzeme olarak da kullanılır."]]],["Fındığın Besin Değerleri",[["p","Fındık, tekli doymamış yağ oranı yüksek, enerji yoğunluğu fazla bir kuruyemiştir; 100 gramı yaklaşık 628 kcal, 15 g protein ve 60,8 g yağ içerir. Özellikle <b>E vitamini</b> ve magnezyum bakımından zengindir, ayrıca lif deposu sayılır."]]],["Fındığın Faydaları Nelerdir?",[["p","Fındığın içerdiği tekli doymamış yağlar ve E vitamini, dengeli beslenmenin bir parçası olarak öne çıkan bileşenlerdendir. Düzenli ama ölçülü tüketimin kalp-damar sağlığı ile ilişkisini inceleyen çalışmalar vardır; bu bulgular henüz kesin bir tedavi önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; fındık bir besindir, tıbbi tedavi yerine geçmez. Kalori yoğunluğu yüksek olduğundan günlük tüketimde bir avuç (yaklaşık 20-30 g) ölçüsü önerilir."]]],["Fındık Nasıl Seçilir?",[["p","Kabuklu fındıkta kabuğun sağlam, çatlaksız ve ağır olması tazelik göstergesidir; kabuksuz fındıkta ise iç rengin canlı krem tonunda olması aranır."],["ul",["Kabuklu fındığı sallayınca iç boşluk hissi vermemeli; boş kabuk kurumuş demektir.","Kabuksuz fındığın kırılınca ekşimsi ya da acımsı koku vermemesine dikkat edilmeli.","Renk homojen krem-kahve olmalı; küflü leke veya kararma tazeliğini yitirdiğini gösterir."]]]],["Fındık Nasıl Saklanır?",[["p","Fındık, yağ oranı yüksek olduğu için oda sıcaklığında uzun süre bekletilirse acılaşır. Kabuksuz fındık hava almayan bir kapta, serin ve karanlık bir yerde 2–3 ay; buzdolabında 6 aya, dondurucuda ise 1 yıla kadar tazeliğini korur."]]],["Mutfakta Fındık Kullanımı",[["p","Fındık; çiğ atıştırmalık olarak, kavrulmuş halde tuzlu-tatlı tariflerde, öğütülerek pasta ve kurabiye hamurlarında, ezme haline getirilerek de kahvaltılık kreması olarak kullanılır."]]],["Fındık Nasıl Kavrulur?",[["p","Kabuksuz fındıklar tek sıra halinde fırın tepsisine dizilip 160–170°C fırında 10–12 dakika, arada karıştırılarak kavrulur. Kabuğu incecik gevşediğinde bir mutfak beziyle ovularak kolayca soyulabilir."]]],["Fındık Ezmesi Nasıl Yapılır?",[["p","Kavrulmuş ve soyulmuş fındıklar, mutfak robotunda önce un kıvamına, ardından uzun süre çekilerek kendi yağını salıp pürüzsüz bir ezmeye dönüşür; istenirse az tuz veya bal eklenir."]]],["Fındık Hangi Tariflerle Kullanılır?",[["p","Fındık ezmesi, fındıklı kek, fındıklı kurabiye, çikolatalı fındık kreması ve fındıklı salata en sevilen kullanım alanlarıdır. Kavrulmuş fındık, tatlılara ve granolalara çıtırlık katmak için de eklenir."]]]],"s":[["Fındık günde ne kadar yenmeli?","Kalori yoğunluğu nedeniyle günde bir avuç (yaklaşık 20-30 g, 15-20 adet) dengeli bir porsiyon sayılır. Bu miktar, dengeli beslenme planına kolayca eklenebilir."],["Fındık kilo aldırır mı?","Fındık yağ ve kalori bakımından yoğun bir besindir; ölçüsüz tüketildiğinde günlük kalori dengesini bozabilir. Porsiyon kontrolüyle tüketildiğinde dengeli beslenmenin parçası olabilir."],["Çiğ fındık mı kavrulmuş fındık mı daha faydalı?","Çiğ fındık bazı ısıya duyarlı besin ögelerini daha fazla korur; kavurma ise aromayı belirginleştirir ve kabuğun kolay soyulmasını sağlar. İkisi de dengeli beslenmenin parçası olabilir."],["Fındık alerjisi nedir?","Fındık, sert kabuklu yemiş alerjileri arasında sık görülenlerden biridir; hassasiyeti olan kişiler tüketmeden önce mutlaka doktoruna danışmalıdır."],["Fındık ile ceviz arasındaki fark nedir?","Fındık daha yuvarlak, tatlımsı ve yağ oranı yüksek bir kuruyemişken, ceviz kıvrımlı iç yapısı ve omega-3 içeriğiyle öne çıkar; ikisi de mutfakta farklı tariflerde tercih edilir."]],"q":[["i-jar","Hava almayan kapta sakla","Yağ oranı yüksek olduğu için açık havada çabuk acılaşır"],["i-scale-balanced","Bir avuç ölçü","Günlük 20-30 g kalori dengesini korur"],["i-arrow-rotate-left","Alternatifi","Badem, ceviz"]],"i":["ceviz","badem","antep-fistigi"],"ic":"i-seedling","l":"Corylus avellana","n":["(100 g çiğ)",[["Enerji","628 kcal"],["Protein","15 g"],["Yağ","60,8 g"],["Lif","9,7 g"],["E Vitamini","15 mg"],["Magnezyum","163 mg"]]],"tb":"Fındıklı tarifler","t":[{"a":"Şekerpare | Geleneksel Şerbetli Tarif","k":"Tatlı","g":"1325","d":"55 dk","z":"Orta","p":"6 kişilik","s":"Koray Karaer","r":"5,0","b":1},{"a":"Fındıklı Kurabiye | Kavrulmuş Fındıklı Tarif","k":"Kurabiye","g":"1475","d":"40 dk","z":"Kolay","p":"22 kişilik","s":"Rüya Saygıner","r":"4,0","b":2},{"a":"Fındık Ezmeli Çörek | Kakaolu Fındık Ezmeli Tatlı Çörek","k":"Hamur İşi","g":"1571","d":"115 dk","z":"Orta","p":"12 dilim","s":"İrem Akgül","r":"4,0","b":2}]},
"ispanak":{"a":"Ispanak","k":"Sebze","e":"Demir kaynağı","o":"Koyu yeşil, ince yapraklı ve besin değeri yüksek bir yaprak sebzesi. Çiğ haliyle salatalarda, pişmiş haliyle börek ve yemeklerde Türk mutfağının en çok kullanılan yeşilliklerinden biridir.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","Sonbahar–İlkbahar"],["i-fire","Kalori (100 g, çiğ)","23 kcal"],["i-box-archive","Saklama (yıkanmadan, nemli kağıt havluyla sarılı poşette)","Buzdolabında 3–5 gün"]],"b":[["Ispanak Nedir?",[["p","Ispanak (<i>Spinacia oleracea</i>), kazayağıgiller familyasından, koyu yeşil ve ince dokulu yapraklarıyla tanınan bir yaprak sebzesidir. Orta Asya kökenli olduğu düşünülür; serin iklimi sever ve Türkiye'de özellikle sonbahar ile ilkbahar aylarında bol yetişir."],["p","Genç yapraklar ince ve yumuşak, olgun yapraklar ise daha kalın ve belirgin damarlıdır. Hafif toprağımsı bir tadı vardır; çiğ tüketildiğinde ferahlatıcı, pişirildiğinde ise yoğun ve dolgun bir aroma kazanır."]]],["Ispanağın Besin Değerleri",[["p","Ispanak düşük kalorili olmasına karşın besin yoğunluğu yüksek bir sebzedir; 100 gramı yaklaşık 23 kcal enerji taşır. <b>Demir</b> ve <b>K vitamini</b> içeriğiyle öne çıkar; ayrıca folat, magnezyum ve A vitamini kaynağıdır."]]],["Ispanağın Faydaları Nelerdir?",[["p","Demir ve folat içeriğiyle ıspanak, dengeli beslenmenin parçası olarak öne çıkan yeşil yapraklı sebzelerden biridir. Lif içeriği sindirim düzenine katkı sağlayabilir; K vitamini kemik sağlığıyla ilişkilendirilen besinler arasında sayılır."],["p","Bu bilgiler geneldir; ıspanak bir besindir, tıbbi tedavi yerine geçmez. Ispanaktaki demir bitkisel (non-hem) formdadır; C vitamini içeren besinlerle birlikte tüketmek emilimini destekleyebilir."]]],["Ispanak Nasıl Seçilir?",[["p","Taze ıspanak canlı koyu yeşil renkte, yaprakları diri ve sapları kırılgan olandır; sararmış veya cılkımsı yapraklar bayatlamanın işaretidir."],["ul",["Yapraklar canlı yeşil ve pürüzsüz olmalı; sarı veya kahverengi lekeli demetlerden kaçının.","Sap ince ve diri olmalı; büyük, kalın saplı demetler daha lifli ve sert olabilir.","Demet elde sıkıldığında yapraklar hışırdamalı, sünger gibi yumuşak olmamalı."]]]],["Ispanak Nasıl Saklanır?",[["p","Ispanak buzdolabının sebzeliğinde, yıkanmadan, nemli bir kağıt havluya sarılıp delikli bir poşette 3-5 gün tazeliğini korur. Uzun süreli saklama için yapraklar kısa süre haşlanıp (blanch) süzüldükten sonra dondurulabilir; dondurulmuş ıspanak birkaç ay bekletilebilir."]]],["Mutfakta Ispanak Kullanımı",[["p","Ispanak çiğ olarak salatalarda, hafif soteyle garnitür olarak, haşlanıp süzülerek börek ve mantı içi gibi hamur işlerinde kullanılır. Pişirirken yapraklar hızla hacim kaybeder; bu yüzden az miktarda yağla, kısa sürede pişirmek en iyi sonucu verir."]]],["Ispanak Nasıl Pişirilir?",[["p","Yıkanmış yapraklar, kızgın bir tavada birkaç damla zeytinyağıyla, kapak kapatılarak 2-3 dakika soteleneir; kendi suyunu bırakıp büzüşünce ocaktan alınır. Fazla pişirmek hem rengi hem besin değerini azaltır."]]],["Ispanaklı Börek İçin Hazırlık",[["p","Börek içi için ıspanak ince kıyılıp hafifçe tuzlanarak suyu süzülür; bu adım hamurun ıslanmasını önler. Süzülen ıspanak, peynir ile karıştırılıp yufka arasına serilerek geleneksel ıspanaklı börek elde edilir."]]],["Ispanak Hangi Tariflerle Kullanılır?",[["p","Ispanaklı börek, ıspanaklı yumurta, kremalı ıspanak çorbası ve zeytinyağlı ıspanak en sevilen tariflerdendir. Peynirli mantı ve omletlerde de sıkça yer bulur."]]]],"s":[["Ispanak neye iyi gelir?","Ispanak; demir, folat, K vitamini ve lif açısından zengindir ve dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Ispanak çiğ yenir mi?","Evet, iyice yıkanmış taze ıspanak çiğ olarak salatalarda tüketilebilir; genç yapraklar bu amaç için daha yumuşak ve lezzetlidir."],["Dondurulmuş ıspanak besin değerini kaybeder mi?","Hasat sonrası hızlı dondurulan ıspanak besin değerinin büyük bölümünü korur; bazı çalışmalar dondurmanın bazı vitaminleri tazeye yakın seviyede tuttuğunu göstermektedir."],["Ispanak neden büzüşür?","Ispanak yaklaşık %90 su içerir; ısıyla hücre duvarları çözülüp su serbest kalınca yapraklar önemli ölçüde hacim kaybeder. Bu nedenle pişirme için görünenden çok daha fazla ıspanak gerekir."],["Ispanağın sapı kullanılır mı?","İnce saplar yapraklarla birlikte pişirilebilir; kalın ve odunsu saplar ise ayıklanıp atılmalıdır. Çorba ve suyu süzülen tariflerde sap da değerlendirilebilir."]],"q":[["i-droplet","İyice yıkayın","Yapraklar arasında toprak ve kum gizlenir"],["i-fire-burner","Kısa sürede pişer","Fazla ısı yaprakları büzüp suyunu kaçırır"],["i-arrow-rotate-left","Alternatifi","Pazı, semizotu, roka"]],"i":["kabak","enginar","pirasa"],"ic":"i-carrot","l":"Spinacia oleracea","n":["(100 g çiğ)",[["Enerji","23 kcal"],["Protein","2,9 g"],["Lif","2,2 g"],["Karbonhidrat","3,6 g"],["Demir","2,7 mg"],["K Vitamini","483 µg"]]],"tb":"Ispanaklı tarifler","t":[{"a":"Ispanaklı Ravioli | İç Harçlı İtalyan Mantısı","k":"Mantı ve Dolgulu Hamurlar","g":"1316","d":"75 dk","z":"Zor","p":"4 kişilik","s":"Ali Öztuna","r":"5,0","b":2},{"a":"Ispanaklı Patates Püresi | 8 Ay ve Üzeri Bebekler İçin","k":"Bebek Tarifleri","g":"1411","d":"26 dk","z":"Çok Kolay","p":"3 kişilik","s":"Bora Küçükler","r":"4,5","b":1},{"a":"Ispanaklı Tortellini | Peynirli İtalyan Dolgulu Makarnası","k":"Mantı ve Dolgulu Hamurlar","g":"1542","d":"70 dk","z":"Zor","p":"4 kişilik","s":"Aşkın Akay","r":"4,0","b":2}]},
"kabak":{"a":"Kabak","k":"Sebze","e":"Yaz sebzesi","o":"Yumuşak kabuğu ve sulu, hafif tadıyla yaz aylarının vazgeçilmez sebzesi. Dolma, mücver, sote ve çorbada; kabuğuyla birlikte tüketilebilen az kalorili bir kabakgil.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","Yaz"],["i-fire","Kalori (100 g, çiğ)","17 kcal"],["i-box-archive","Saklama (delikli poşette, yıkanmadan)","Buzdolabında 4–5 gün"]],"b":[["Kabak Nedir?",[["p","Kabak (<i>Cucurbita pepo</i>), kabakgiller familyasından, ince yeşil kabuğu ve beyazımsı sulu etiyle tanınan bir yaz sebzesidir. Türkiye'de \"yaz kabağı\" olarak da bilinir; Amerika kıtası kökenlidir ve sıcak iklimde hızla büyür."],["p","Tadı hafif ve nötrdür; bu yüzden başka malzemelerin aromasını kolayca üzerine alır. Kabuğu yumuşak olduğundan soyulmadan, tohumları küçükken çıkarılmadan tüketilebilir."]]],["Kabağın Besin Değerleri",[["p","Kabak %90'ın üzerinde su içerdiğinden düşük kalorilidir; 100 gramı yaklaşık 17 kcal enerji taşır. <b>C vitamini</b> ve <b>potasyum</b> kaynağıdır, az miktarda lif ve B grubu vitaminler içerir."]]],["Kabağın Faydaları Nelerdir?",[["p","Yüksek su içeriği ve düşük kalorisiyle kabak, dengeli beslenmenin parçası olarak tercih edilen sebzelerdendir. İçerdiği potasyum ve C vitamini genel beslenme çeşitliliğine katkı sağlar."],["p","Bu bilgiler geneldir; kabak bir besindir, tıbbi tedavi yerine geçmez."]]],["Kabak Nasıl Seçilir?",[["p","İyi bir kabak orta boy, sıkı kabuklu ve ağırdır; büyük ve gevşek kabaklar genelde tohumlu ve lifli çıkar."],["ul",["Kabuk parlak, lekesiz ve sıkı olmalı; buruşuk veya yumuşamış bölgeler bayatlığın işaretidir.","Orta boy tercih edilmeli; aşırı büyük kabaklarda tohum sertleşir, et lifli olur.","Sap ucu taze ve nemli görünmeli, kurumuş sap eski hasadı gösterir."]]]],["Kabak Nasıl Saklanır?",[["p","Kabak buzdolabının sebzeliğinde, yıkanmadan, delikli bir poşette 4-5 gün tazeliğini korur. Kesildikten sonra kesim yüzeyi hızla nem kaybettiğinden aynı gün tüketilmesi önerilir; dilimlenmiş kabak dondurularak da saklanabilir."]]],["Mutfakta Kabak Kullanımı",[["p","Kabak sotelenerek, fırınlanarak, dolma yapılarak ya da rendelenip mücver haline getirilerek pişirilir. Suyu bol olduğundan tarife göre önceden tuzlanıp süzülmesi gereken tarifler vardır."]]],["Kabak Mücveri Nasıl Yapılır?",[["p","Rendelenen kabak tuzlanıp 10 dakika bekletilir, eldeki fazla su sıkılarak alınır. Un, yumurta ve baharatla karıştırılan karışım, kızgın yağda her iki yüzü altın rengi alana dek kızartılır."]]],["Kabak Hangi Tariflerle Kullanılır?",[["p","Kabak mücveri, kabak dolması, zeytinyağlı kabak ve kabaklı çorba en bilinen tariflerdendir. Fırında sebze karışımlarında ve makarna soslarında da sıkça kullanılır."]]]],"s":[["Kabak neye iyi gelir?","Kabak; su, C vitamini ve potasyum bakımından zengindir, düşük kalorili beslenmede tercih edilen sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Kabak kabuğuyla mı yenir?","Evet, genç ve ince kabuklu kabaklar soyulmadan tüketilebilir; kabuk hem lif hem de görsel canlılık katar. Kabuk sertleşmişse soyulması önerilir."],["Kabak neden sulanır?","Kabağın hücre yapısı büyük oranda sudan oluşur; tuzlama veya pişirme sırasında bu su hızla açığa çıkar. Mücver ve dolma gibi tariflerde fazla suyun süzülmesi kıvamı korur."],["Kabak çiğ yenir mi?","Evet, ince dilimlenmiş taze kabak salatalarda çiğ olarak tüketilebilir; hafif ve çıtır bir doku sunar."],["Kabak dondurulabilir mi?","Evet, dilimlenip kısa süre haşlandıktan (blanch) sonra dondurulan kabak birkaç ay saklanabilir; çözüldüğünde doku yumuşadığından çoğunlukla pişmiş tariflerde kullanılır."]],"q":[["i-droplet","Suyunu alın","Mücver ve dolma öncesi rendelenip tuzlanarak suyu süzülmeli"],["i-fire-burner","Az pişirin","Fazla pişen kabak suyunu bırakıp lapa kıvamına gelir"],["i-arrow-rotate-left","Alternatifi","Sakız kabağı, patlıcan"]],"i":["ispanak","enginar","pirasa"],"ic":"i-carrot","l":"Cucurbita pepo","n":["(100 g çiğ)",[["Enerji","17 kcal"],["Protein","1,2 g"],["Lif","1,0 g"],["Karbonhidrat","3,1 g"],["C Vitamini","17,9 mg"],["Potasyum","261 mg"]]],"tb":"Kabaklı tarifler","t":[{"a":"Sebze Türlüsü | Fırında Zeytinyağlı Karışık Sebze","k":"Sebze","g":"1308","d":"80 dk","z":"Kolay","p":"5 kişilik","s":"Rüzgar Yıldızoğlu","r":"4,0","b":1},{"a":"Fırın Kabak Cipsi | Baharatlı Çıtır","k":"Atıştırmalık","g":"1366","d":"50 dk","z":"Çok Kolay","p":"4 kişilik","s":"Türker Erdoğan","r":"4,7","b":1},{"a":"Izgara Sebzeli Sandviç | Zeytinyağlı Közlenmiş Sebze Sandviçi","k":"Sandviç, Burger ve Dürüm","g":"1392","d":"27 dk","z":"Kolay","p":"2 kişilik","s":"Ümran Numanoğlu","r":"0,0","b":1}]},
"karabiber":{"a":"Karabiber","k":"Baharat","e":"Baharatların kralı","o":"Sarmaşık formunda bir tropikal bitkinin kurutulmuş meyvesinden elde edilen, keskin ve hafif yakıcı tada sahip dünyanın en çok tüketilen baharatı. Tuzla birlikte mutfağın en temel ikilisini oluşturur.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu (tropikal, kurutulmuş baharat olarak satılır)"],["i-fire","Kalori (100 g, öğütülmüş)","251 kcal"],["i-box-archive","Saklama (bütün tane, öğütülmüşten çok daha uzun aromasını korur)","Kapalı kavanozda, serin ve karanlık yerde 2–3 yıl"]],"b":[["Karabiber Nedir?",[["p","Karabiber (<i>Piper nigrum</i>), sarmaşık formunda büyüyen tropikal bir bitkinin kurutulmuş meyvesinden elde edilen, dünyanın en çok tüketilen baharatıdır. Hindistan’ın Malabar kıyılarına özgü olup bugün birçok tropikal bölgede yetiştirilir; tane olgunlaşma derecesine göre siyah, beyaz veya yeşil karabiber elde edilir."],["p","Siyah karabiber, henüz olgunlaşmamış yeşil taneler kaynatılıp güneşte kurutularak elde edilir; bu işlem kabuğun buruşup koyulaşmasını sağlar. Keskin, hafif yakıcı tadını <b>piperin</b> adlı bileşiğe borçludur."]]],["Karabiberin Besin Değerleri",[["p","Karabiber küçük porsiyonlarda tüketildiği için günlük beslenmeye kayda değer bir kalori katkısı yapmaz; yine de 100 gramı yaklaşık 251 kcal enerji, 10,4 g protein ve 25 g’ın üzerinde lif içerir. Demir ve manganez gibi minerallerin yanı sıra keskin tadını veren piperin bileşiğini barındırır."]]],["Karabiberin Faydaları Nelerdir?",[["p","<b>Piperin</b> içeriğiyle bilinen karabiber, geleneksel olarak sindirimi rahatlatıcı bir baharat olarak tüketilir; bazı çalışmalar piperinin belirli besin ögelerinin emilimini destekleyebileceğini öne sürer. Bu alandaki araştırmalar sürmekte olup kesin sağlık iddiaları için yeterli değildir."],["p","Bu bilgiler geneldir; karabiber bir baharattır, tıbbi tedavi yerine geçmez."]]],["Karabiber Nasıl Seçilir?",[["p","Aroması en güçlü karabiber bütün tane halinde satılandır; toz haldeki karabiber daha çabuk aroma kaybeder."],["ul",["Tane iri, koyu ve buruşuk kabuklu olmalı; soluk veya tozlu görünenlerden kaçının.","Sıkıldığında sert olmalı; yumuşak ya da nemli tane bayatlamış demektir.","Mümkünse değirmenli kavanoz tercih edin; tazelik kullanım anında korunur."]]]],["Karabiber Nasıl Saklanır?",[["p","Bütün karabiber taneleri, hava almayan bir kavanozda serin ve karanlık bir yerde 2–3 yıla kadar aromasını korur. Öğütülmüş karabiber ise uçucu yağlarını daha hızlı kaybettiğinden birkaç ay içinde tüketilmesi önerilir."]]],["Mutfakta Karabiber Kullanımı",[["p","Karabiber tuzla birlikte mutfağın en temel ikili baharatını oluşturur; et, sebze, çorba ve soslara pişirmenin sonuna doğru eklenerek keskinliği korunur."]]],["Karabiber Ne Zaman Eklenmeli?",[["p","Uzun süre kaynayan yemeklerde erken eklenen karabiber acılığını kaybedip yalnızca hafif bir buruk tat bırakır; bu yüzden en iyi sonuç için pişirmenin son dakikalarında veya servis anında taze öğütülerek eklenmesi önerilir."]]],["Karabiber Hangi Tariflerle Kullanılır?",[["p","Karabiber; kavurma, çorba, salata sosu, marine ve hemen hemen tüm tuzlu tariflerde kullanılır. Karabiberli biftek, tavuklu karabiber sote ve sebze çorbalarında sıkça tercih edilir."]]]],"s":[["Karabiber neye iyi gelir?","Karabiber; piperin içeriğiyle geleneksel olarak sindirime destek olduğu düşünülen bir baharattır. Bir baharattır; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Siyah ve beyaz karabiber arasındaki fark nedir?","Siyah karabiber olgunlaşmamış yeşil tanenin kabuğuyla birlikte kurutulmasıyla, beyaz karabiber ise olgun tanenin kabuğu soyulup yalnızca çekirdeğinin kurutulmasıyla elde edilir. Beyaz karabiber daha hafif ve az keskin bir tada sahiptir."],["Karabiber bozulur mu?","Karabiber küflenme veya nem almadığı sürece bozulmaz; ancak zamanla uçucu yağlarını kaybederek aroma gücünü yitirir. Bu yüzden “raf ömrü” kavramı bozulmadan çok tat kaybıyla ilgilidir."],["Toz karabiber yerine bütün tane mi tercih edilmeli?","Evet, mümkün olduğunda bütün tane tercih edilip kullanım anında öğütülmesi önerilir; bu yöntem aromanın büyük kısmını korur ve toz haline göre çok daha belirgin bir tat sağlar."],["Karabiber hangi yemeklerle uyumludur?","Karabiber neredeyse tüm tuzlu yemeklerle uyumludur; kırmızı et, tavuk, balık, sebze yemekleri, çorbalar ve hatta bazı tatlı tariflerinde (çilekli tatlılar gibi) kullanılabilir."]],"q":[["i-mortar-pestle","Kullanmadan önce öğüt","Bütün tane aromayı çok daha uzun korur"],["i-clock","Pişirmenin sonuna ekle","Uzun kaynamada keskinliği azalır"],["i-jar","Bütün tane sakla","Toz karabiber birkaç ayda aroma kaybeder"]],"i":["zencefil","sumak","pul-biber"],"ic":"i-mortar-pestle","l":"Piper nigrum","n":["(100 g, öğütülmüş (yaklaşık; günlük tüketim bir tutamla sınırlıdır))",[["Enerji","251 kcal"],["Protein","10,4 g"],["Yağ","3,3 g"],["Karbonhidrat","64,0 g"],["Lif","25,3 g"],["Demir","9,7 mg"]]],"tb":"Karabiberli tarifler","t":[{"a":"Etli Kuru Fasulye | Geleneksel Ev Yapımı Tarif","k":"Bakliyat","g":"1277","d":"110 dk","z":"Orta","p":"4 kişilik","s":"Ahmet Ayaydın","r":"0,0","b":1},{"a":"Kuzu Tandır | Fırında Ağır Ateş Tarifi","k":"Kırmızı Et","g":"1280","d":"270 dk","z":"Orta","p":"6 kişilik","s":"Ahmet Ayaydın","r":"5,0","b":3},{"a":"Dana Rosto | Fırında Sebzeli Dana Fileto","k":"Kırmızı Et","g":"1281","d":"95 dk","z":"Orta","p":"5 kişilik","s":"Ahmet Ayaydın","r":"0,0","b":3}]},
"kasar-peyniri":{"a":"Kaşar Peyniri","k":"Peynir","e":"Eritmelik sert peynir","o":"İnek sütünden yapılan, sarımsı renkte, olgunlaştıkça sertleşen bir peynir türü. Kahvaltıdan tost ve kızartmaya kadar eritilerek de kullanılan çok yönlü bir Türk peyniri.","y":[["i-layer-group","Kategori","Peynir"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g (yaklaşık, olgunlaşma süresine göre değişir))","~356 kcal"],["i-box-archive","Saklama (kesim yüzeyi streç filmle kapatılmalı)","Buzdolabında sıkı sarılı 3–4 hafta"]],"b":[["Kaşar Peyniri Nedir?",[["p","Kaşar peyniri, genellikle inek sütünden yapılan, haşlama-yoğurma tekniğiyle üretilen sarımsı renkte bir Türk peyniridir. Olgunlaşma süresine göre “taze kaşar” ve “eski kaşar” olarak ikiye ayrılır."],["p","Taze kaşar yumuşak, hafif tatlımsı bir tada sahipken; aylarca olgunlaştırılan eski kaşar sertleşir, tadı belirgin şekilde keskinleşir ve rendelenmeye daha uygun hale gelir."]]],["Kaşar Peynirinin Besin Değerleri",[["p","Kaşar peyniri, benzer sert-yarı sert sarı peynirlere yakın olarak 100 gramda yaklaşık 356 kcal enerji ve 24,9 g protein içerir. Kalsiyum açısından zengindir; olgunlaşma sürecine bağlı olarak tuz (sodyum) oranı da göz ardı edilmeyecek düzeydedir."]]],["Kaşar Peynirinin Faydaları Nelerdir?",[["p","Yüksek protein ve kalsiyum içeriğiyle kaşar peyniri, dengeli beslenmenin parçası olarak öne çıkan bir süt ürünüdür. Porsiyon kontrolü, yağ ve tuz oranı yüksek bir peynir olduğu için önemlidir."],["p","Bu bilgiler geneldir; kaşar peyniri bir besindir, tıbbi tedavi yerine geçmez."]]],["Kaşar Peyniri Nasıl Seçilir?",[["p","Taze kaşar seçerken renk, koku ve kıvam gözlemlenmelidir."],["ul",["Renk açık sarımsı-krem olmalı; aşırı koyu sarı ya da gri lekeler bayatlamayı gösterebilir.","Yüzeyde nem ya da yağlanma dışında ıslaklık, küf olmamalı.","İstenen kullanım amacına göre taze (yumuşak, eritmelik) ya da eski (sert, rendelik) tercih edilmeli."]]]],["Kaşar Peyniri Nasıl Saklanır?",[["p","Kaşar peyniri buzdolabında, kesim yüzeyi streç film ya da mumlu kağıtla sıkıca sarılarak 3–4 hafta saklanabilir. Hava almayan ambalajlarda kurumadan korunur; uzun süre açıkta bırakılması yüzeyde sertleşme ve kuruma yaratır."]]],["Mutfakta Kaşar Peyniri Kullanımı",[["p","Kaşar peyniri kahvaltıda dilim halinde çiğ tüketilir, ayrıca kolay erime özelliği sayesinde tost, kızartma ve fırın tariflerinde sıkça kullanılır. Eski kaşar rendelenerek makarna ve çorbaların üzerine serpiştirilir."]]],["Kaşarlı Tost Nasıl Yapılır?",[["p","Dilimlenmiş ekmek arasına ince kaşar dilimleri konularak tost makinesinde ya da tavada, peynir eriyene kadar her iki taraf altın rengi kızarana dek pişirilir."]]],["Kaşar Nasıl Kızartılır?",[["p","Kalın dilimlenmiş kaşar, hafif unlanıp sıcak yağda her iki tarafı da altın rengi kızarana kadar kısa sürede kızartılır; sıcak servis edilir."]]],["Kaşar Peyniri Hangi Tariflerle Kullanılır?",[["p","Kaşarlı tost, kızarmış kaşar, kaşarlı makarna ve fırında kaşarlı sebze en sevilen kullanım alanlarıdır. Rendelenmiş eski kaşar, çorba ve pilavların üzerine serpiştirilerek de tüketilir."]]]],"s":[["Kaşar peyniri neye iyi gelir?","Kaşar peyniri; protein ve kalsiyum açısından zengin bir süt ürünüdür ve dengeli beslenmenin parçası olarak öne çıkar. Herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Taze kaşar ile eski kaşar arasındaki fark nedir?","Taze kaşar birkaç haftalık olgunlaşmayla yumuşak ve hafif tatlı kalırken, eski kaşar aylarca olgunlaştırılarak sertleşir ve tadı belirgin şekilde keskinleşir; eski kaşar genellikle rendelik olarak tercih edilir."],["Kaşar peyniri dondurulabilir mi?","Dondurmak dokusunu ufalanır hale getirebileceğinden, en iyi sonuç için kaşar peynirinin buzdolabında sıkıca sarılı saklanması önerilir; dondurulmuşsa genellikle pişmiş tariflerde kullanılması daha uygundur."],["Kaşar peyniri neden kolay erir?","Üretim sürecindeki yoğurma tekniği, peynirin protein yapısını erimeye uygun hale getirir; bu özellik onu tost ve kızartma gibi ısıyla tüketilen tariflerde tercih edilen bir peynir yapar."],["Kaşar peynirinin küflenen kısmı kesilip geri kalanı yenir mi?","Sert peynirlerde yüzeydeki küçük küf bölgesi geniş bir marjla kesilip atılırsa geri kalan kısım genellikle tüketilebilir kabul edilir; ancak yaygın küflenme ya da şüphe durumunda peynirin tamamının atılması güvenli tercihtir."]],"q":[["i-fire-burner","Kolay erir","Tost ve kızartmada tercih edilme nedeni"],["i-clock","Olgunlaşma süresi kıvamı belirler","Taze kaşar yumuşak, eski kaşar sert ve keskindir"],["i-arrow-rotate-left","Alternatifi","Gouda, kaşkaval"]],"i":["beyaz-peynir","lor-peyniri","tulum-peyniri"],"ic":"i-cheese","n":["(100 g (sert-yarı sert sarı peynir verisine yakın, ~))",[["Enerji","~356 kcal"],["Protein","~24,9 g"],["Yağ","~27,4 g"],["Kalsiyum","~700 mg"],["Sodyum","~819 mg"]]],"tb":"Kaşarlı tarifler","t":[{"a":"Kaşarlı Pide | Fırında Peynirli Pide","k":"Pizza ve Pide","g":"1312","d":"105 dk","z":"Orta","p":"4 kişilik","s":"Rüzgar Yıldızoğlu","r":"4,0","b":2},{"a":"Fırın Makarnası | Beşamel Soslu Kaşarlı Makarna","k":"Makarna","g":"1321","d":"60 dk","z":"Orta","p":"6 kişilik","s":"İrem Yıldızoğlu","r":"5,0","b":2},{"a":"Peynirli Omlet | Kabarık ve Yumuşak","k":"Yumurta Tarifleri","g":"1343","d":"11 dk","z":"Çok Kolay","p":"2 kişilik","s":"Ece Yetkiner","r":"4,7","b":1}]},
"kinoa":{"a":"Kinoa","k":"Bakliyat","e":"Tam protein","o":"Dokuz esansiyel amino asidi içeren, glütensiz bir \"sözde tahıl\". Bulgur ve pirince modern bir alternatif olarak salata ve pilavlarda kullanılır.","y":[["i-layer-group","Kategori","Bakliyat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, haşlanmış)","120 kcal"],["i-box-archive","Saklama (kuru tane)","12–24 ay, ağzı kapalı kavanoz"]],"b":[["Kinoa Nedir?",[["p","Kinoa (<i>Chenopodium quinoa</i>), And Dağları kökenli bir tohumdur. Halk arasında tahıl gibi anılsa da botanik olarak buğdaygillerden değil, ıspanağın akrabası bir bitkiden gelir; bu yüzden \"sözde tahıl\" (psödotahıl) olarak adlandırılır ve doğal olarak <b>glütensizdir</b>."],["p","Beyaz, kırmızı ve siyah gibi renk çeşitleri vardır. Piştiğinde taneler şeffaflaşır ve dışındaki ince halka açığa çıkar; hafif fındığımsı tadı ve tane tane kalan dokusuyla pilav ve salatalarda öne çıkar."]]],["Kinoanın Besin Değerleri",[["p","Kinoanın en dikkat çekici yönü, <b>dokuz esansiyel amino asidin tamamını</b> içeren nadir bitkisel kaynaklardan biri olmasıdır. Haşlanmış kinoanın 100 gramı yaklaşık 120 kcal enerji, 4,4 g protein ve 2,8 g lif taşır; ayrıca magnezyum ve demir açısından da değerlidir."]]],["Kinoanın Faydaları Nelerdir?",[["p","Tam protein profili ve lif içeriği sayesinde kinoa, dengeli beslenmenin bir parçası olarak özellikle bitkisel ağırlıklı ve glütensiz beslenme düzenlerinde değerli bir seçenek olarak öne çıkar. Kompleks karbonhidrat yapısı enerjinin dengeli salınmasına katkı sağlayabilir."],["p","Bu bilgiler geneldir; kinoa bir besindir ve tıbbi tedavi yerine geçmez."]]],["Kinoa Nasıl Seçilir?",[["p","Kaliteli kuru kinoa temiz, kuru ve eşit taneli olur. Paketli ürünlerde \"yıkanmış\" (pre-rinsed) ibaresi acılığı azaltır ama yine de bir kez daha durulamak en garantili yoldur."],["ul",["Taneler kuru ve dağınık olsun; nemli topaklanma istenmez.","Renk çeşidine göre canlı; küf ya da böcek izi bulunmamalı.","Dökme alınıyorsa kokusu tatlımsı-fındığımsı olmalı, ekşi değil."]]]],["Kinoa Nasıl Saklanır?",[["p","Kuru kinoa, ağzı kapalı bir kavanozda serin ve kuru bir yerde bir-iki yıl saklanabilir. Yağ içeriği nedeniyle sıcak ve nemli ortamda zamanla acılaşabilir; bu yüzden serin dolap tercih edilir. Pişmiş kinoa buzdolabında 3–4 gün, dondurucuda birkaç ay dayanır."]]],["Mutfakta Kinoa Kullanımı",[["p","Kinoanın pişirmeden önce mutlaka yıkanması gerekir: tanelerin üzerindeki doğal <b>saponin</b> tabakası acımsı bir tat bırakır ve ince süzgeçte akan suda ovularak giderilir. Genel oran bir ölçü kinoaya iki ölçü sudur."]]],["Kinoa Nasıl Pişirilir?",[["p","Yıkanan kinoa, iki katı su ya da et/sebze suyuyla kaynatılıp kısık ateşte suyunu çekene dek yaklaşık 15 dakika pişirilir. Ocaktan alındıktan sonra kapağı kapalı 5 dakika dinlendirilip çatalla kabartılır; böylece taneler dağılmadan ayrışır."]]],["Salata ve Pilav Olarak",[["p","Soğutulmuş kinoa; domates, salatalık, maydanoz ve limon-zeytinyağı sosuyla ferah bir salata olur. Sıcak servis edildiğinde ise baharatlı bir pilav ya da et yanına garnitür olarak kullanılır."]]],["Kinoa Hangi Tariflerle Kullanılır?",[["p","Kinoa salatası, kinoa pilavı, sebzeli kinoa, kinoalı köfte ve kahvaltı kaseleri en yaygın tariflerdir. Bulgur ya da pirinç isteyen çoğu tarifte alternatif olarak da kullanılabilir."]]]],"s":[["Kinoa neye iyi gelir?","Kinoa; tam protein profili, lif ve mineral içeriğiyle dengeli beslenmenin parçası olarak özellikle bitkisel ve glütensiz beslenme düzenlerinde değerli bir seçenektir. Bir besindir; hastalık iyileştirme iddiası taşımaz."],["Kinoa nasıl pişirilir?","Yıkanan kinoa iki katı suyla kaynatılıp kısık ateşte suyunu çekene dek yaklaşık 15 dakika pişirilir, ardından kapağı kapalı 5 dakika dinlendirilir. Çatalla kabartıldığında taneler tane tane ayrışır."],["Kinoa neden yıkanır?","Tanelerin dışındaki doğal saponin tabakası acımsı ve sabunumsu bir tat bırakır. İnce süzgeçte akan suda ovarak yıkamak bu acılığı giderir ve kinoanın tadını yumuşatır."],["Kinoa glütensiz midir?","Evet, kinoa botanik olarak buğdaygillerden gelmediği için doğal olarak glütensizdir. Ancak çapraz bulaşma riski nedeniyle glüten hassasiyeti olanların \"glütensiz\" etiketli ürünleri tercih etmesi önerilir."],["Kinoa mı bulgur mu daha besleyici?","İkisi de değerli seçeneklerdir; kinoa tam protein profili ve glütensiz olmasıyla, bulgur ise lif içeriği ve ekonomik olmasıyla öne çıkar. Beslenme hedefine göre biri diğerinin yerine kullanılabilir."]],"q":[["i-droplet","Önce yıka","Saponin acılığını akan suda akıt"],["i-fire-burner","Pişme","1 ölçü kinoa / 2 ölçü su, ~15 dk"],["i-arrow-rotate-left","Alternatifi","Bulgur, pirinç"]],"i":["barbunya","kirmizi-mercimek","nohut"],"ic":"i-seedling","l":"Chenopodium quinoa","n":["(100 g haşlanmış)",[["Enerji","120 kcal"],["Protein","4,4 g"],["Karbonhidrat","21,3 g"],["Lif","2,8 g"],["Magnezyum","64 mg"],["Demir","1,5 mg"]]],"tb":"Kinoalı tarifler","t":[{"a":"Kinoa Kahvaltı Kasesi | Proteinli Meyveli Kahvaltılık","k":"Kahvaltılık","g":"1661","d":"25 dk","z":"Kolay","p":"2 kişilik","s":"Rüya Akal","r":"0,0","b":2},{"a":"Kinoalı Sebzeli Pilav | Hafif ve Modern Tahıl Pilavı","k":"Pilav","g":"1812","d":"40 dk","z":"Kolay","p":"4 kişilik","s":"Ege Köylüoğlu","r":"4,2","b":2},{"a":"Kinoa Salatası | Cherry Domatesli Fesleğenli Tarif","k":"Salata","g":"1828","d":"35 dk","z":"Kolay","p":"4 kişilik","s":"Rüzgar Ekici","r":"5,0","b":2}]},
"kirmizi-mercimek":{"a":"Kırmızı Mercimek","k":"Bakliyat","e":"Hızlı pişen bakliyat","o":"Kabuğu soyulmuş, turuncu-kırmızı taneleriyle en hızlı pişen bakliyatlardan biri. Mercimek çorbasının ve köftesinin vazgeçilmez temel malzemesi.","y":[["i-layer-group","Kategori","Bakliyat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, kuru çiğ)","340 kcal"],["i-box-archive","Saklama (kapalı kavanozda)","Kuru serin yerde 1 yıla kadar"]],"b":[["Kırmızı Mercimek Nedir?",[["p","Kırmızı mercimek (<i>Lens culinaris</i>), baklagiller familyasından, kabuğu soyulmuş ve ikiye bölünmüş haliyle satılan turuncu-kırmızı renkli bir bakliyattır. Pişince rengi soluk sarıya döner."],["p","Kabuksuz ve bölünmüş yapısı sayesinde diğer bakliyatlara göre çok daha hızlı pişer, çoğu zaman ıslatmaya bile gerek kalmaz. Hafif tatlımsı, toprağımsı bir tadı vardır."]]],["Kırmızı Mercimeğin Besin Değerleri",[["p","Kırmızı mercimek yüksek bitkisel protein içeriğiyle dikkat çeker; 100 gramı yaklaşık 340 kcal enerji, 23,1 g protein ve 10,7 g lif taşır. <b>Demir</b> ve <b>potasyum</b> kaynağıdır."]]],["Kırmızı Mercimeğin Faydaları Nelerdir?",[["p","Yüksek protein ve lif içeriğiyle kırmızı mercimek, dengeli beslenmenin parçası olarak öne çıkan baklagillerdendir; özellikle bitkisel ağırlıklı beslenmede önemli bir protein kaynağıdır."],["p","Bu bilgiler geneldir; kırmızı mercimek bir besindir, tıbbi tedavi yerine geçmez."]]],["Kırmızı Mercimek Nasıl Seçilir?",[["p","İyi kalite kırmızı mercimek parlak turuncu renkte, eşit boyutlu ve tozsuz olmalıdır."],["ul",["Taneler arasında kırık veya toz fazlaysa paket eski olabilir.","Renk canlı turuncu olmalı; solgun, grimsi tonlar bayatlamayı gösterebilir.","Ambalajın hava almadığından ve nem tutmadığından emin olun."]]]],["Kırmızı Mercimek Nasıl Saklanır?",[["p","Kırmızı mercimek kapalı bir kavanozda, serin ve kuru bir yerde 1 yıla kadar saklanabilir. Pişmiş mercimek buzdolabında 3-4 gün, dondurucuda birkaç ay bekletilebilir."]]],["Mutfakta Kırmızı Mercimek Kullanımı",[["p","Kırmızı mercimek en çok çorbalarda, ayrıca mercimek köftesi ve pilavlarda kullanılır. Islatmaya gerek duymadan, yıkanıp süzüldükten sonra doğrudan kaynar suya eklenerek pişirilir."]]],["Mercimek Çorbası Nasıl Yapılır?",[["p","Soğan ve havuç kısık ateşte kavrulur, yıkanmış mercimek ve su eklenerek taneler dağılıp pürüzsüzleşene dek 20-25 dakika kaynatılır. Blenderdan geçirilip kıvamı ayarlanan çorba, tereyağlı baharatla servis edilir."]]],["Kırmızı Mercimek Hangi Tariflerle Kullanılır?",[["p","Mercimek çorbası, mercimek köftesi, mercimekli pilav ve mercimekli köfte en bilinen tariflerdendir. Bulgur ile karıştırılan tariflerde de sıkça yer alır."]]]],"s":[["Kırmızı mercimek neye iyi gelir?","Kırmızı mercimek; bitkisel protein, lif, demir ve potasyum açısından zengindir, dengeli beslenmenin parçası olarak öne çıkan baklagillerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Kırmızı mercimek ıslatılmalı mı?","Kabuğu soyulup bölündüğü için genellikle ıslatmaya gerek yoktur; yıkanıp süzülerek doğrudan pişirilebilir."],["Kırmızı mercimek ile yeşil mercimek farkı nedir?","Kırmızı mercimek kabuğu soyulmuş ve bölünmüş olduğu için hızlı pişer ve dağılır; yeşil mercimek ise kabuklu olduğundan şeklini daha çok korur ve pişme süresi uzundur."],["Mercimek neden köpürür?","Kaynarken yüzeye çıkan köpük, mercimekteki bazı bitkisel proteinlerin ve sabun benzeri bileşiklerin (saponin) su yüzeyinde birikmesinden kaynaklanır; kaşıkla alınması önerilir."],["Mercimek köftesi neden dağılır?","Mercimek yeterince pişirilip iyice ezilmeden veya bulgur oranı düşük tutulduğunda köfte harcı bağlanmayabilir; sıcakken yoğurmak ve dinlendirmek harcın toparlanmasına yardımcı olur."]],"q":[["i-droplet","Yıkayıp süzün","Toz ve nişasta fazlasını giderir"],["i-fire-burner","Islatmaya gerek yok","Kabuğu soyulduğu için hızlı pişer"],["i-arrow-rotate-left","Alternatifi","Sarı mercimek, yeşil mercimek"]],"i":["barbunya","kinoa","nohut"],"ic":"i-seedling","l":"Lens culinaris","n":["(100 g kuru çiğ)",[["Enerji","340 kcal"],["Protein","23,1 g"],["Lif","10,7 g"],["Karbonhidrat","57,3 g"],["Demir","~7,5 mg"],["Potasyum","~955 mg"]]],"tb":"Kırmızı mercimekli tarifler","t":[{"a":"Kırmızı Mercimek Köftesi | Etsiz Mercimek Köftesi","k":"Bakliyat","g":"1299","d":"55 dk","z":"Orta","p":"6 kişilik","s":"Ümran Tanrıkulu","r":"0,0","b":1},{"a":"Mercimek Çorbası | Klasik Ezme Kırmızı Mercimek Çorbası","k":"Çorba","g":"1305","d":"50 dk","z":"Kolay","p":"5 kişilik","s":"Rüya Evliyaoğlu","r":"3,9","b":1},{"a":"Ezogelin Çorbası | Naneli Kırmızı Mercimek Çorbası","k":"Çorba","g":"1306","d":"55 dk","z":"Kolay","p":"5 kişilik","s":"Rüya Evliyaoğlu","r":"0,0","b":1}]},
"kurutulmus-domates":{"a":"Kurutulmuş Domates","k":"Domates","e":"Yoğun aroma","o":"Güneşte ya da fırında kurutularak suyu alınmış, yoğun ve tatlı-ekşi aromalı bir domates ürünü. Zeytinyağında ya da kuru haliyle mezelerde ve soslarda kullanılır.","y":[["i-layer-group","Kategori","Domates"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, kuru (yağsız))","258 kcal"],["i-box-archive","Saklama (yağa batırılmışsa serin yerde)","Kuru: kapalı kapta 6-12 ay; yağda: buzdolabında 2-3 hafta"]],"b":[["Kurutulmuş Domates Nedir?",[["p","Kurutulmuş domates, olgun domateslerin ikiye kesilip güneşte veya fırında kurutularak su içeriğinin büyük bölümünün uzaklaştırılmasıyla elde edilen bir üründür. Bu işlem tadı yoğunlaştırır ve raf ömrünü belirgin şekilde uzatır."],["p","Kuru haliyle sert ve büzülmüş, zeytinyağına batırılmış haliyle ise yumuşak ve parlak görünümlüdür. Tatlı-ekşi, yoğun bir domates aroması taşır."]]],["Kurutulmuş Domatesin Besin Değerleri",[["p","Su kaybı nedeniyle kurutulmuş domates, taze domatese göre çok daha yoğun besin içeriğine sahiptir; 100 gram kuru (yağsız) ürün yaklaşık 258 kcal enerji taşır. <b>Potasyum</b> ve <b>demir</b> bakımından oldukça zengindir."]]],["Kurutulmuş Domatesin Faydaları Nelerdir?",[["p","Kurutma işlemi domatesteki likopen gibi bazı bitkisel bileşiklerin yoğunlaşmasına yol açabilir; bu konudaki araştırmalar sürmektedir. Yüksek potasyum içeriğiyle dengeli beslenmenin parçası olarak değerlendirilebilir."],["p","Bu bilgiler geneldir; kurutulmuş domates bir besindir, tıbbi tedavi yerine geçmez. Yağda saklanan ürünlerin kalori ve yağ içeriği kuru haline göre belirgin şekilde daha yüksektir."]]],["Kurutulmuş Domates Nasıl Seçilir?",[["p","İyi kalite kurutulmuş domates koyu kırmızı-bordo renkte, esnek ve küflenmemiş olmalıdır."],["ul",["Renk koyu kırmızı-bordo olmalı; griye çalan tonlar bayatlamayı gösterebilir.","Doku aşırı sert ve taş gibi olmamalı, hafif esnek olmalı.","Zeytinyağında satılanlarda yağın berrak, küf lekesi olmadığından emin olun."]]]],["Kurutulmuş Domates Nasıl Saklanır?",[["p","Kuru haliyle kapalı bir kapta, serin ve kuru bir yerde 6-12 ay saklanabilir. Zeytinyağına batırılmış kurutulmuş domates buzdolabında 2-3 hafta tazeliğini korur; kullanılan yağ da aromalı olarak değerlendirilebilir."]]],["Mutfakta Kurutulmuş Domates Kullanımı",[["p","Kurutulmuş domates makarna soslarına, pizzalara, mezelere ve salatalara yoğun bir domates aroması katmak için kullanılır. Sert kuru hali, kullanılmadan önce genellikle sıcak suda ya da yağda yumuşatılır."]]],["Kurutulmuş Domates Nasıl Yumuşatılır?",[["p","Kuru domatesler sıcak suya batırılıp 10-15 dakika bekletilir, ardından süzülüp kullanılır. İstenirse zeytinyağı, sarımsak ve kekikle birlikte bir kavanozda bekletilerek hem yumuşatılır hem aromalandırılır."]]],["Kurutulmuş Domates Hangi Tariflerle Kullanılır?",[["p","Kurutulmuş domatesli makarna, pesto, pizza ve mezeler en bilinen kullanım şekillerindendir. Peynirli kanepelerde ve salatalarda da sıkça tercih edilir."]]]],"s":[["Kurutulmuş domates neye iyi gelir?","Kurutulmuş domates; potasyum, demir ve yoğunlaşmış bitkisel bileşikler açısından zengindir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Kurutulmuş domates ile taze domates aynı miktarda mı kullanılır?","Hayır, kurutulmuş domates aroması çok daha yoğun olduğundan tariflerde genellikle daha az miktarda ve genelde yumuşatılmış haliyle kullanılır."],["Kurutulmuş domates evde nasıl yapılır?","İkiye kesilen domatesler hafif tuzlanıp kesik yüzü yukarı bakacak şekilde düşük ısılı fırında (yaklaşık 80-100°C) birkaç saat kurutulur; güneşli ve kuru iklimde açık havada da kurutulabilir."],["Kurutulmuş domates küflenir mi?","Yeterince kurutulmamış veya nemli ortamda saklanan kurutulmuş domateste küf oluşabilir; iyi kurutulmuş ve doğru saklanan ürün uzun süre güvenle bekletilebilir."],["Zeytinyağındaki kurutulmuş domatesin yağı kullanılır mı?","Evet, domatesin aromasını alan bu yağ salata sosu ve makarna tariflerinde lezzetli bir katkı olarak değerlendirilebilir."]],"q":[["i-droplet","Sıcak suda yumuşatın","Çok sert kurutulmuş domates suda 10 dakika bekletilerek yumuşatılır"],["i-jar","Yağa batırın","Zeytinyağında saklanan kurutulmuş domates hem yumuşar hem uzun ömürlü olur"],["i-arrow-rotate-left","Alternatifi","Taze domates (uzun pişmiş), domates salçası"]],"i":["ceri-domates","pembe-domates","salkim-domates"],"ic":"i-carrot","n":["(100 g kuru (yağsız))",[["Enerji","258 kcal"],["Protein","14,1 g"],["Lif","12,3 g"],["Karbonhidrat","55,8 g"],["Potasyum","3427 mg"],["Demir","9,1 mg"]]],"tb":"Kurutulmuş domatesli tarifler","t":[{"a":"Akdeniz Sebzeli Pizza | Zeytinli Kurutulmuş Domatesli Pizza","k":"Pizza ve Pide","g":"2363","d":"45 dk","z":"Kolay","p":"4 dilim","s":"Ada Eliçin","r":"0,0","b":2}]},
"lor-peyniri":{"a":"Lor Peyniri","k":"Peynir","e":"Hafif ve proteinli","o":"Peynir altı suyundan veya süzme yoğurttan elde edilen, tanecikli ve hafif tuzlu taze bir peynir. Böreklerde, tatlılarda ve kahvaltı sofralarında sıkça kullanılır.","y":[["i-layer-group","Kategori","Peynir"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, tam yağlı)","174 kcal"],["i-box-archive","Saklama","Buzdolabında, kapalı kapta 5–7 gün"]],"b":[["Lor Peyniri Nedir?",[["p","Lor peyniri, peynir yapımından arta kalan peynir altı suyunun ısıtılmasıyla ayrışan proteinlerin toplanmasıyla elde edilen taze, tanecikli bir peynirdir. İtalyan ricottasına benzer bir üretim mantığı taşır."],["p","Hafif tuzlu ve nötr tada sahiptir; hem tatlı hem tuzlu tariflerde rahatça kullanılabilir. Süzme, taze veya hafif tuzlanmış çeşitleri bulunur."]]],["Lor Peynirinin Besin Değerleri",[["p","Lor peyniri, 100 gramında yaklaşık 174 kcal enerji, 11,3 g protein ve 207 mg <b>kalsiyum</b> içeren, göreceli olarak hafif bir peynirdir. Yağ oranı kullanılan sütün türüne göre değişebilir."]]],["Lor Peynirinin Faydaları Nelerdir?",[["p","Lor peyniri, diğer olgun peynirlere kıyasla daha düşük tuz ve kalori içerdiğinden dengeli beslenmenin bir parçası olarak tercih edilebilir. Protein içeriği doygunluk hissine katkıda bulunabilir."],["p","Bu bilgiler geneldir; lor peyniri bir besindir, tıbbi tedavi yerine geçmez."]]],["Lor Peyniri Nasıl Seçilir?",[["p","Lor peyniri seçerken tanelerinin taze, kokusunun ferah ve renginin beyaz-krem tonunda olmasına dikkat edilmelidir."],["ul",["Aşırı sulu görünen lor, tazeliğini yitirmiş olabilir; süzgeçten geçirilerek kullanılabilir.","Ekşimsi veya keskin bir koku bayatlama belirtisidir.","Ambalajlı ürünlerde son kullanma tarihi kontrol edilmelidir."]]]],["Lor Peyniri Nasıl Saklanır?",[["p","Lor peyniri buzdolabında kapalı bir kapta 5–7 gün tazeliğini korur. Suyu sızdırma eğiliminde olduğundan altına bir süzgeç veya kağıt havlu konması önerilir."]]],["Mutfakta Lor Peyniri Kullanımı",[["p","Lor peyniri; peynirli börekte, mantıda, tatlılarda (lorlu kurabiye, cheesecake) ve kahvaltı sofralarında bal veya reçelle kullanılır."]]],["Lorlu Börek İçin Lor Nasıl Hazırlanır?",[["p","Lor peyniri bir süzgeçte fazla suyu akıtılıp çatalla ezilir; yumurta, maydanoz ve isteğe göre az tuz eklenerek börek içi harcı hazırlanır. Fazla su bırakması, hamurun ıslanmasını önlemek için giderilmelidir."]]],["Lor Peyniri Hangi Tariflerle Kullanılır?",[["p","Lorlu su böreği, lorlu mantı, lorlu kurabiye ve lorlu cheesecake en sevilen tariflerdendir. Kahvaltı tabaklarında da bal veya zeytinyağıyla sunulur."]]]],"s":[["Lor peyniri neye iyi gelir?","Lor peyniri; protein ve kalsiyum içeriğiyle dengeli beslenmenin parçası olarak tercih edilebilecek hafif bir peynirdir. Herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Lor peyniri ile ricotta aynı mı?","İkisi de peynir altı suyundan elde edilir ve benzer dokudadır; ricotta İtalyan mutfağının, lor ise Türk mutfağının aynı üretim mantığına dayanan karşılığıdır."],["Lor peyniri diyette yenir mi?","Göreceli olarak düşük kalorili ve yüksek proteinli olması nedeniyle dengeli beslenme planlarında sıkça tercih edilir; miktar kişinin genel beslenme hedefine göre belirlenmelidir."],["Lor peyniri neden su bırakır?","Lor, yüksek nem oranına sahip taze bir peynir olduğundan zamanla peynir altı suyunu bırakabilir; bu durum bozulma değil, doğal bir ayrışmadır."],["Lor peyniri dondurulabilir mi?","Lor peyniri dondurulabilir ancak çözüldüğünde su ayrışması ve tanecikli doku kaybı yaşanabilir; bu yüzden pişirilecek tariflerde kullanılması önerilir."]],"q":[["i-wheat-awn","Börekte kullan","Sızdırmaması için hafif süzülüp kullanılmalı"],["i-flask","Pürüzsüzleştir","Çatalla ezmek yerine süzgeçten geçirmek daha ipeksi kıvam verir"],["i-arrow-rotate-left","Alternatifi","Ricotta, süzme lor"]],"i":["beyaz-peynir","kasar-peyniri","tulum-peyniri"],"ic":"i-cheese","n":["(100 g, tam yağlı)",[["Enerji","174 kcal"],["Protein","11,3 g"],["Yağ","13 g"],["Karbonhidrat","3 g"],["Kalsiyum","207 mg"]]],"tb":"Lorlu tarifler","t":[{"a":"Ispanaklı Ravioli | İç Harçlı İtalyan Mantısı","k":"Mantı ve Dolgulu Hamurlar","g":"1316","d":"75 dk","z":"Zor","p":"4 kişilik","s":"Ali Öztuna","r":"5,0","b":2},{"a":"Ispanaklı Tortellini | Peynirli İtalyan Dolgulu Makarnası","k":"Mantı ve Dolgulu Hamurlar","g":"1542","d":"70 dk","z":"Zor","p":"4 kişilik","s":"Aşkın Akay","r":"4,0","b":2},{"a":"Tepsi Böreği | Peynirli Kat Kat Yufka Böreği","k":"Hamur İşi","g":"1564","d":"55 dk","z":"Orta","p":"15 dilim","s":"Ahmet Ayaydın","r":"3,5","b":1}]},
"maydanoz":{"a":"Maydanoz","k":"Ot","e":"Vitamin K deposu","o":"Keskin, taze aromasıyla neredeyse her tarifin garnitürü olan yaygın bir yeşil ot. Düz ve kıvırcık yapraklı iki ana çeşidiyle salata, sos ve süslemede kullanılır.","y":[["i-layer-group","Kategori","Ot"],["i-calendar-days","Mevsim","İlkbahar–Sonbahar (serin havada yıl boyu yetişir)"],["i-fire","Kalori (100 g, çiğ)","36 kcal"],["i-box-archive","Saklama (kökleri suda, üstü poşetle örtülü)","Buzdolabında suda demet halinde 1 hafta"]],"b":[["Maydanoz Nedir?",[["p","Maydanoz (<i>Petroselinum crispum</i>), maydanozgiller familyasından, Akdeniz kökenli iki yıllık bir bitkidir. Düz yapraklı (İtalyan) ve kıvırcık yapraklı olmak üzere iki ana çeşidi bulunur; düz yapraklı tür genellikle daha yoğun aromalı kabul edilir."],["p","Türk mutfağında hem taze bir yeşillik hem de vazgeçilmez bir garnitür olarak kullanılır; keskin, hafif buruk ve ferahlatıcı bir tadı vardır."]]],["Maydanozun Besin Değerleri",[["p","Maydanoz, az miktarda tüketilse de besin yoğunluğu yüksek bir yeşilliktir; 100 gramı yaklaşık 36 kcal enerji ve 3,3 g lif içerir. Özellikle <b>K vitamini</b> ve <b>C vitamini</b> bakımından son derece zengindir."]]],["Maydanozun Faydaları Nelerdir?",[["p","Yüksek K ve C vitamini içeriğiyle maydanoz, dengeli beslenmenin parçası olarak öne çıkan bir yeşilliktir. Nefes tazeleyici etkisiyle geleneksel olarak yemek sonrası çiğnenir."],["p","Bu bilgiler geneldir; maydanoz bir besindir, tıbbi tedavi yerine geçmez. Kan sulandırıcı ilaç kullananların yüksek K vitamini içeren yeşillik tüketimini uzmanına danışması önerilir."]]],["Maydanoz Nasıl Seçilir?",[["p","Taze maydanoz canlı yeşil renkte, diri saplı ve pörsümemiş olmalıdır."],["ul",["Yapraklar parlak koyu yeşil olmalı; sararmış ya da kararmış uçlar bayatlamayı gösterir.","Sap kesildiğinde nemli ve diri görünmeli, kurumuş olmamalıdır.","Demet koklandığında keskin, taze bir koku vermelidir; küf kokusu bozulma işaretidir."]]]],["Maydanoz Nasıl Saklanır?",[["p","Maydanoz, sapları bir bardak suya batırılıp üzeri gevşek bir poşetle örtülerek buzdolabında yaklaşık 1 hafta tazeliğini korur; su birkaç günde bir değiştirilmelidir. Uzun süreli saklama için doğranıp buz kalıplarında biraz suyla dondurulabilir."]]],["Mutfakta Maydanoz Kullanımı",[["p","Maydanoz çoğunlukla çiğ olarak kullanılır; salatalarda ana malzeme, çorba ve yemeklerde ise pişirmenin sonunda eklenen bir tazeleyici olarak yer alır. Isıya uzun süre maruz kalması aromasını ve canlı rengini kaybettirir."]]],["Tabbule Nasıl Yapılır?",[["p","İnce doğranmış maydanoz, bulgur, domates, soğan, nane, limon suyu ve zeytinyağıyla karıştırılarak Ortadoğu mutfağının klasik salatası tabbule hazırlanır; maydanoz burada yan malzeme değil ana bileşendir."]]],["Maydanoz Sosu Nasıl Yapılır?",[["p","Maydanoz, sarımsak, limon suyu ve zeytinyağı robotta çekilerek ferah bir yeşil sos elde edilir; ızgara et ve balığın yanında kullanılır."]]],["Maydanoz Hangi Tariflerle Kullanılır?",[["p","Tabbule, maydanoz sosu, maydanozlu köfte içi ve zeytinyağlı sebze yemekleri en sevilen kullanım alanlarıdır. Doğranmış maydanoz, çorba ve pilavların üzerine serpiştirilerek de tüketilir."]]]],"s":[["Maydanoz neye iyi gelir?","Maydanoz; K vitamini, C vitamini ve lif açısından zengindir ve dengeli beslenmenin parçası olarak öne çıkan bir yeşilliktir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Maydanoz sapı da yenir mi?","Evet, sap kısmı yapraklara göre daha keskin ve lifli olsa da ince doğranarak sos, çorba ve köfte harcında değerlendirilebilir; israfı önler."],["Düz ve kıvırcık maydanoz arasındaki fark nedir?","Düz yapraklı (İtalyan) maydanoz genellikle daha yoğun aromalı kabul edilir ve pişmiş yemeklerde tercih edilir; kıvırcık yapraklı tür daha hafif bir tada sahiptir ve süslemede sıkça kullanılır."],["Maydanoz dondurulabilir mi?","Evet, doğranmış maydanoz az suyla birlikte buz kalıplarına dökülüp dondurulabilir; bu yöntem tazeliğe yakın bir aroma korur ve doğrudan çorba-sosa eklenebilir."],["Maydanoz neden çabuk soluyor?","İnce yaprak yapısı nedeniyle su kaybı hızlıdır; bu yüzden kesildikten sonra suya batırılmadan oda sıcaklığında bırakılan maydanoz birkaç saat içinde pörsüyebilir."]],"q":[["i-droplet","Demet halinde suda sakla","Kesme çiçekler gibi tazeliğini uzatır"],["i-utensils","Pişirmenin sonuna ekle","Isı aroma ve rengini hızla kaybettirir"],["i-arrow-rotate-left","Alternatifi","Dereotu, kişniş (tatlar farklı, dikkatli değiştirin)"]],"i":["feslegen","nane","dereotu"],"ic":"i-seedling","l":"Petroselinum crispum","n":["(100 g çiğ)",[["Enerji","36 kcal"],["Protein","3,0 g"],["Karbonhidrat","6,3 g"],["Lif","3,3 g"],["C Vitamini","133 mg"],["K Vitamini","1640 µg"]]],"tb":"Maydanozlu tarifler","t":[{"a":"Arnavut Ciğeri | Klasik Tava","k":"Sakatat","g":"1290","d":"30 dk","z":"Orta","p":"4 kişilik","s":"İrem Akgül","r":"0,0","b":1},{"a":"Barbunya Pilaki | Zeytinyağlı Soğuk Servis","k":"Bakliyat","g":"1296","d":"85 dk","z":"Kolay","p":"5 kişilik","s":"Rüya Öymen","r":"0,0","b":1},{"a":"Piyaz | Kuru Fasulye Salatası","k":"Bakliyat","g":"1298","d":"70 dk","z":"Çok Kolay","p":"4 kişilik","s":"Ümran Tanrıkulu","r":"4,0","b":1}]},
"nane":{"a":"Nane","k":"Ot","e":"Serinletici aroma","o":"Keskin, serinletici kokusuyla tanınan çok yıllık bir yeşillik. Taze yapraklar salata ve içeceklerden cacığa, kuru yaprak ise çaya kadar geniş bir yelpazede kullanılır.","y":[["i-layer-group","Kategori","Ot"],["i-calendar-days","Mevsim","İlkbahar–Yaz"],["i-fire","Kalori (100 g, taze)","44 kcal"],["i-box-archive","Saklama (nemli kağıt havluya sarılı, kavanozda)","Buzdolabında 5–7 gün"]],"b":[["Nane Nedir?",[["p","Nane (<i>Mentha spicata</i>), ıtır familyasından çok yıllık, keskin mentollü kokusuyla tanınan bir yeşilliktir. Türkiye mutfağında en çok kullanılan tür yeşil naneyle (spearmint) karıştırılabilen ama daha keskin mentollü olan biberiye naneyi (peppermint) birbirinden ayırmak önemlidir; cacık ve salatalarda genelde yeşil nane tercih edilir."],["p","Taze halde parlak yeşil, dişli kenarlı yapraklara sahiptir; kurutulunca aroması yoğunlaşır ama serinletici tazelik bir miktar kaybolur. Bu yüzden taze nane, tada anında canlılık katmak istenen soğuk yemek ve içeceklerde tercih edilir."]]],["Nanenin Besin Değerleri",[["p","Nane düşük kalorili ama besin yoğunluğu yüksek bir yeşilliktir; 100 gramı yaklaşık 44 kcal enerji, 3,3 g protein ve 6,8 g lif içerir. <b>Demir</b> ve <b>kalsiyum</b> açısından dikkat çekici oranlarda değer taşır, ayrıca C vitamini sağlar."]]],["Nanenin Faydaları Nelerdir?",[["p","Nane geleneksel olarak sindirimi rahatlatmak amacıyla çay şeklinde tüketilir; ferahlatıcı kokusu nedeniyle de tercih edilir. Mentol bileşiği üzerine yapılan çalışmalar sürmektedir; bu bulgular henüz kesin bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler geneldir; nane bir besindir ve tıbbi tedavi yerine geçmez. Reflü şikâyeti olanların yoğun nane tüketimini dikkatli değerlendirmesi önerilir."]]],["Nane Nasıl Seçilir?",[["p","Taze nane demeti canlı yeşil, dik duran ve solmamış yapraklardan oluşmalıdır."],["ul",["Yapraklar parlak yeşil olsun; kararma veya sararma bayatlama işaretidir.","Sap kesildiğinde nemli ve diri görünmeli, kurumuş olmamalı.","Ezildiğinde belirgin, keskin bir koku yaymalı; kokusu zayıfsa tazeliği azalmıştır."]]]],["Nane Nasıl Saklanır?",[["p","Taze nane, sapları nemli bir kağıt havluya sarılıp buzdolabında saklandığında 5–7 gün tazeliğini korur; alternatif olarak sap uçları suya batırılmış bir bardağa dikilip üzeri gevşek bir poşetle örtülerek de saklanabilir. Uzun süreli saklama için yapraklar temizlenip dondurulabilir; buz kalıbında az suyla dondurmak aromayı iyi korur."]]],["Mutfakta Nane Kullanımı",[["p","Nane cacık, çoban salatası, limonata ve mezelerde taze halde; çorba ve etli yemeklerde kuru halde kullanılır. Aroması ısıyla hızlı uçtuğundan sıcak yemeklere genellikle pişirme sonunda eklenir."]]],["Nane Çayı Nasıl Demlenir?",[["p","Bir tutam taze veya kuru nane yaprağı, kaynamış suyun üzerine eklenip 5–7 dakika demlenmeye bırakılır. Taze yaprakla demlenen çay daha ferahlatıcı, kuru yaprakla demlenen ise daha yoğun aromalı olur; istenirse limon dilimiyle zenginleştirilir."]]],["Taze Nane Dondurularak Nasıl Saklanır?",[["p","Yıkanıp kurutulan yapraklar buz kalıplarına yerleştirilip üzerine az su veya zeytinyağı eklenerek dondurulur. Bu küpler doğrudan çorba, sote veya içeceklere atılarak kullanılabilir; aroma birkaç ay korunur."]]],["Nane Hangi Tariflerle Kullanılır?",[["p","Naneli cacık, nane-limon şerbeti, kuzu etli nane sote ve nanetli mercimek çorbası en çok tercih edilen tariflerdendir. Taze nane ayrıca meyve salatalarına ve yoğurtlu soslara da eklenir."]]]],"s":[["Nane neye iyi gelir?","Nane geleneksel olarak sindirimi rahatlatmak için çay şeklinde tüketilir ve serinletici aromasıyla bilinir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Kuru nane ile taze nane arasında fark var mı?","Evet. Kurutma işlemi aromayı yoğunlaştırır ama mentollü tazeliği azaltır. Soğuk yemek ve içeceklerde taze, sıcak yemek ve çorbalarda genelde kuru nane tercih edilir."],["Nane hangi yemeklerle iyi gider?","Yoğurtlu mezeler, kuzu ve dana etli yemekler, bakliyat çorbaları ve serinletici içeceklerle çok iyi uyum sağlar. Akdeniz ve Ortadoğu mutfağının vazgeçilmez otlarındandır."],["Nane yaprakları neden kararır?","Kesilip doğrandıktan sonra havayla temas eden nane yaprakları hızla kararır (enzimatik esmerleşme). Bu yüzden nane servisten hemen önce doğranmalı, önceden hazırlanmamalıdır."],["Nane saksıda nasıl tazeliğini korur?","Saksıda yetişen nane, düzenli sulanıp güneşli fakat çok sıcak olmayan bir yerde tutulduğunda hafta boyunca taze yaprak vermeye devam eder. Yaprak toplarken uçtan kesim yapmak bitkinin dallanmasını teşvik eder."]],"q":[["i-droplet","Kullanmadan önce yıka","Yapraklar arasında toprak ve kum kalabilir"],["i-utensils","Servisten hemen önce kıy","Erken doğranırsa kararır ve aromasını kaybeder"],["i-arrow-rotate-left","Alternatifi","Fesleğen, taze kişniş (tatlı yerine değil, tazelik için)"]],"i":["maydanoz","feslegen","dereotu"],"ic":"i-seedling","l":"Mentha spicata","n":["(100 g taze)",[["Enerji","44 kcal"],["Protein","3,3 g"],["Lif","6,8 g"],["C Vitamini","13,3 mg"],["Kalsiyum","199 mg"],["Demir","11,9 mg"]]],"tb":"Naneli tarifler","t":[{"a":"Zeytinyağlı Yaprak Sarma | Çam Fıstıklı Geleneksel Tarif","k":"Dolma ve Sarma","g":"1301","d":"95 dk","z":"Zor","p":"6 kişilik","s":"Ümran Tanrıkulu","r":"4,0","b":2},{"a":"Zeytinyağlı Biber Dolması | Etsiz Pirinç Dolması","k":"Dolma ve Sarma","g":"1302","d":"80 dk","z":"Orta","p":"5 kişilik","s":"Rüya Evliyaoğlu","r":"4,0","b":1},{"a":"Mercimek Çorbası | Klasik Ezme Kırmızı Mercimek Çorbası","k":"Çorba","g":"1305","d":"50 dk","z":"Kolay","p":"5 kişilik","s":"Rüya Evliyaoğlu","r":"3,9","b":1}]},
"nohut":{"a":"Nohut","k":"Bakliyat","e":"Bitkisel protein","o":"Fındık kıvamında tadıyla çok yönlü bir baklagil; humustan nohutlu pilava, falafelden çorbaya uzanan geniş bir mutfağı vardır.","y":[["i-layer-group","Kategori","Bakliyat"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, haşlanmış)","164 kcal"],["i-box-archive","Saklama (kuru tane)","12 ay+, serin kuru yer"]],"b":[["Nohut Nedir?",[["p","Nohut (<i>Cicer arietinum</i>), baklagiller familyasından, bej-sarımsı renkli ve hafif fındığımsı tada sahip bir tanedir. İnsanlığın en eski kültür bitkilerinden biridir ve Akdeniz’den Orta Doğu’ya, Hindistan’dan Anadolu’ya kadar geniş bir coğrafyanın mutfağında temel malzemedir."],["p","Kuru tanesi haşlanarak kullanılır; ayrıca öğütülmüş nohut unu ve közlenmiş leblebi gibi türevleri de vardır. Piştiğinde yumuşayan ama dağılmayan yapısı, onu hem tane hem ezme tarifleri için ideal kılar."]]],["Nohudun Besin Değerleri",[["p","Nohut, bitkisel protein ve lif bakımından zengin bir baklagildir. Haşlanmış nohudun 100 gramı yaklaşık 164 kcal enerji, 8,9 g protein ve 7,6 g lif içerir. Ayrıca demir, folat ve magnezyum gibi mineraller açısından değerlidir; bu profil onu et tüketiminin azaltıldığı beslenme düzenlerinde önemli bir kaynak yapar."]]],["Nohudun Faydaları Nelerdir?",[["p","Yüksek lif ve bitkisel protein içeriği sayesinde nohut, dengeli beslenmenin bir parçası olarak tokluk hissini destekleyebilecek besinler arasında sayılır. Kompleks karbonhidrat yapısı, enerjinin daha dengeli salınmasına katkıda bulunabilir."],["p","Bu bilgiler geneldir; nohut bir besindir, tıbbi tedavi yerine geçmez. Baklagillere hassasiyeti olanların porsiyonu kademeli artırması önerilir."]]],["Nohut Nasıl Seçilir?",[["p","Kaliteli kuru nohut dolgun, eşit boyda ve parlak taneli olur; buruşuk ve mat taneler eskimiştir ve zor pişer."],["ul",["Taneler iri, dolgun ve kırıksız olsun.","Renk canlı bej olmalı; koyulaşmış tane eskidiğini gösterir.","İçinde taş ve yabancı madde bulunmayan, elenmiş ürünü tercih et."]]]],["Nohut Nasıl Saklanır?",[["p","Kuru nohut, ağzı kapalı kavanozda serin ve kuru bir yerde bir yıldan uzun dayanır. Ancak çok eskiyen taneler ne kadar pişirilse de sertliğini korur. Haşlanmış nohut, suyuyla birlikte buzdolabında 3–4 gün, dondurucuda ise aylarca saklanabilir."]]],["Mutfakta Nohut Kullanımı",[["p","Nohudun pişme sırrı ıslatmadadır: kuru tane 8–12 saat bol suda bekletildiğinde hem daha kolay pişer hem daha az sindirim zorluğu yaratır. Bir tutam karbonat suya katılırsa kabuk yumuşar ve humus gibi pürüzsüz ezmeler daha kolay elde edilir."]]],["Humus Nasıl Yapılır?",[["p","Yumuşayana kadar haşlanmış nohut; tahin, sarımsak, limon suyu ve zeytinyağıyla pürüzsüz olana dek ezilir. Üzerine pul biber ve zeytinyağı gezdirilerek servis edilir. Kremamsı bir kıvam için haşlama suyundan bir miktar eklenebilir."]]],["Nohutlu Pilav ve Yemekler",[["p","Haşlanmış nohut, tereyağlı pilava eklendiğinde klasik nohutlu pilav olur; etli nohut yemeği ve nohut çorbası ise kış sofralarının doyurucu seçenekleridir."]]],["Nohut Hangi Tariflerle Kullanılır?",[["p","Humus, nohutlu pilav, etli nohut, falafel, nohut çorbası ve nohutlu salata en sevilen tariflerdir. Kavrulmuş hali leblebi olarak da atıştırmalık şeklinde tüketilir."]]]],"s":[["Nohut neye iyi gelir?","Nohut yüksek lif ve bitkisel protein içeriğiyle dengeli beslenmenin parçası olarak tokluk hissini destekleyebilecek besinler arasında sayılır. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Nohut ne kadar sürede pişer?","Önceden 8–12 saat ıslatılmış nohut, tane büyüklüğüne göre yaklaşık 40–60 dakikada pişer. Düdüklü tencerede bu süre 15–20 dakikaya iner. Islatılmadan pişirmek hem süreyi uzatır hem sindirimi zorlaştırır."],["Nohut neden ıslatılır?","Islatmak taneyi yumuşatarak pişme süresini kısaltır ve hazımsızlığa yol açan bazı bileşiklerin suya geçmesini sağlar. Islatma suyu döküldüğünde nohut daha kolay sindirilir."],["Nohut kabuğu nasıl kolay çıkar?","Haşlama suyuna bir tutam karbonat eklemek kabuğun gevşemesini sağlar; pişen nohut avuç içinde hafifçe ovulup suda çalkalandığında kabuklar yüzeye çıkar. Bu, humusun daha pürüzsüz olmasını sağlar."],["Haşlanmış nohut nasıl saklanır?","Haşlanmış nohut, haşlama suyuyla birlikte kapalı bir kapta buzdolabında 3–4 gün dayanır. Daha uzun saklamak için porsiyonlara ayırıp dondurmak pratiktir; çözüldüğünde tazesi gibi kullanılır."]],"q":[["i-clock","Islatma şart","Kuru tane 8–12 saat suda bekler"],["i-fire-burner","Pişme süresi","Islatılmış tane 40–60 dk"],["i-arrow-rotate-left","Alternatifi","Barbunya, kuru fasulye"]],"i":["barbunya","kirmizi-mercimek","kinoa"],"ic":"i-seedling","l":"Cicer arietinum","n":["(100 g haşlanmış)",[["Enerji","164 kcal"],["Protein","8,9 g"],["Lif","7,6 g"],["Karbonhidrat","27,4 g"],["Demir","2,9 mg"],["Folat","172 µg"]]],"tb":"Nohutlu tarifler","t":[{"a":"Terbiyeli Sulu Köfte | Ekşili Klasik","k":"Köfte ve Kebap","g":"1285","d":"65 dk","z":"Orta","p":"4 kişilik","s":"Ebru Ozansoy","r":"0,0","b":2},{"a":"Etsiz Nohut Yemeği | Zeytinyağlı Ev Usulü","k":"Bakliyat","g":"1295","d":"85 dk","z":"Kolay","p":"4 kişilik","s":"Rüya Öymen","r":"3,0","b":1},{"a":"Nohut Salatası | Zeytinyağlı Ferah Tarif","k":"Bakliyat","g":"1300","d":"70 dk","z":"Çok Kolay","p":"4 kişilik","s":"Ümran Tanrıkulu","r":"4,0","b":1}]},
"pembe-domates":{"a":"Pembe Domates","k":"Domates","e":"Etli sofralık domates","o":"İnce kabuklu, pembemsi-kırmızı ve bol etli iri bir sofralık domates çeşidi. Az çekirdekli, tatlı-hafif ekşi dengesiyle özellikle salata ve sandviçte tercih edilir.","y":[["i-layer-group","Kategori","Domates"],["i-calendar-days","Mevsim","Yaz (serada yıl boyu)"],["i-fire","Kalori (100 g, çiğ (yaklaşık))","18 kcal"],["i-box-archive","Saklama (buzdolabı tadını ve dokusunu bozar)","Oda sıcaklığında 3–5 gün"]],"b":[["Pembe Domates Nedir?",[["p","Pembe domates, olgunlaştığında pembemsi-kırmızı bir renk alan, ince kabuklu ve bol etli bir sofralık domates çeşididir (<i>Solanum lycopersicum</i>). Az çekirdekli ve sulu yapısıyla çiğ tüketimde, özellikle salatalarda tercih edilir."],["p","Tatlı ile hafif ekşinin dengeli olduğu aroması ve yumuşak kabuğu, onu sanayi (salça) domateslerinden ayırır; buna karşılık ince kabuğu nedeniyle daha çabuk ezilir ve kısa raf ömrüne sahiptir."]]],["Pembe Domatesin Besin Değerleri",[["p","Domates düşük kalorili (100 gramı yaklaşık 18 kcal), su oranı yüksek bir sebzedir; <b>C vitamini</b>, potasyum ve likopen içerir. USDA verileri kültivara göre ayrım yapmadığından bu değerler olgun domates için yaklaşık kabul edilmelidir."]]],["Pembe Domatesin Faydaları Nelerdir?",[["p","C vitamini, potasyum ve likopen içeriğiyle domates, dengeli beslenmenin bir parçası olarak değerlendirilebilir. Likopen üzerine çeşitli araştırmalar sürmektedir; sofralık tüketim bir tıbbi etki iddiası taşımaz."],["p","Bu bilgiler geneldir; pembe domates bir besindir, tıbbi tedavi yerine geçmez."]]],["Pembe Domates Nasıl Seçilir?",[["p","İyi bir pembe domates, hafif bastırıldığında esnek ama diri olmalı; sapından belirgin domates kokusu almalıdır. Aşırı yumuşak veya çatlak olanlar fazla olgunlaşmıştır."],["ul",["Kabuk pürüzsüz, çatlaksız ve mat parlaklıkta olmalı","Sap kısmı yeşil ve taze görünmeli","Ağırlığına göre dolgun hissedilmeli; hafif olanlar pamuklaşmış olabilir"]]]],["Pembe Domates Nasıl Saklanır?",[["p","Pembe domates oda sıcaklığında, doğrudan güneş görmeyen bir yerde 3–5 gün saklanır. Buzdolabı hem aromasını hem dokusunu bozduğundan, ancak çok olgunlaştıysa ve kısa süreliğine tercih edilmelidir."]]],["Mutfakta Pembe Domates Kullanımı",[["p","Pembe domates en çok çiğ olarak salata, sandviç ve meze tabaklarında kullanılır; ince kabuğu ve tatlı aromasıyla dilimlenip zeytinyağı ve tuzla sade servise de uygundur."]]],["Domates Salatası İçin Neden Pembe Domates?",[["p","İnce kabuğu, az çekirdeği ve bol eti sayesinde çiğ tüketimde daha yumuşak bir doku ve dengeli tat verdiğinden salatalarda tercih edilir."]]],["Pembe Domatesin Kabuğu Soyulur mu?",[["p","İnce kabuklu olduğundan genellikle soyulmadan tüketilir; isteyenler kaynar suda birkaç saniye bekletip şoklayarak kolayca soyabilir."]]],["Pembe Domates Hangi Tariflerle Kullanılır?",[["p","Çoban salata, domates-peynir tabağı, bruschetta ve domatesli sandviç pembe domatesin en sık kullanıldığı tariflerdendir."]]]],"s":[["Pembe domates ile kırmızı domates farkı nedir?","Pembe domates daha ince kabuklu, az çekirdekli ve genellikle daha tatlıdır; kırmızı (sanayi) domatesler daha kalın kabuklu ve salça/sos yapımına daha uygundur."],["Pembe domates neden buzdolabında bozulur?","Soğuk, domatesin aroma bileşiklerinin oluşumunu durdurur ve etini pamuklaştırır; bu yüzden oda sıcaklığında saklanması tadını korur."],["Pembe domates salçalık olur mu?","Su oranı yüksek ve eti yumuşak olduğundan salçalık için ideal değildir; salça için daha etli, kalın kabuklu sanayi domatesleri tercih edilir."],["Pembe domates ne zaman en lezzetlidir?","Açık tarlada yetişen pembe domates en aromatik hâline yaz aylarında ulaşır; serada yıl boyu üretilse de yaz domatesinin tadı daha yoğundur."],["Pembe domates olgunlaşmadan toplanırsa ne olur?","Ham toplanan domates oda sıcaklığında bir miktar olgunlaşır ama tarlada olgunlaşanın aromasına tam ulaşamaz; bu yüzden mümkünse dalında olgunlaşmışı tercih edilir."]],"q":[["i-fire","Buzdolabına koymayın","Soğuk, domatesin aromasını ve dokusunu bozar"],["i-utensils","Salatanın yıldızı","İnce kabuğu ve bol etiyle çiğ tüketimde öne çıkar"],["i-arrow-rotate-left","Alternatifi","Beefsteak (dana yüreği) domates benzer etli dokuyu verir"]],"i":["ceri-domates","kurutulmus-domates","salkim-domates"],"ic":"i-carrot","l":"Solanum lycopersicum","n":["(100 g çiğ, ~yaklaşık (USDA olgun domates; kültivar ayrılmaz))",[["Enerji","~18 kcal"],["Protein","0,9 g"],["Karbonhidrat","3,9 g"],["Lif","1,2 g"],["C Vitamini","14 mg"],["Potasyum","237 mg"]]]},
"pirasa":{"a":"Pırasa","k":"Sebze","e":"Kış sebzesi","o":"Keskin ama soğana göre daha hafif aromasıyla soğangiller familyasından bir kış sebzesi. Zeytinyağlılardan çorbaya kadar Türk mutfağının klasiklerinden biri.","y":[["i-layer-group","Kategori","Sebze"],["i-calendar-days","Mevsim","Kış"],["i-fire","Kalori (100 g, çiğ)","61 kcal"],["i-box-archive","Saklama (gevşek poşette, dik konumda)","Buzdolabında 1–2 hafta"]],"b":[["Pırasa Nedir?",[["p","Pırasa (<i>Allium ampeloprasum</i>), soğangiller familyasından, uzun beyaz gövdesi ve koyu yeşil yapraklarıyla tanınan bir kış sebzesidir. Soğan ve sarımsağın akrabasıdır; ancak kokusu ve tadı çok daha hafiftir."],["p","Beyaz gövde kısmı en çok tercih edilen bölümdür; yeşil yapraklar daha sert olsa da çorbalarda değerlendirilebilir. Soğuğa dayanıklıdır, en lezzetli dönemi kıştır."]]],["Pırasanın Besin Değerleri",[["p","Pırasa 100 gramda yaklaşık 61 kcal enerji taşır; diğer soğangillere göre biraz daha yüksek karbonhidrat içerir. <b>K vitamini</b> ve <b>demir</b> kaynağıdır, ayrıca folat ve C vitamini barındırır."]]],["Pırasanın Faydaları Nelerdir?",[["p","Lif ve K vitamini içeriğiyle pırasa, dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Soğangillerin genel özelliği olan kükürtlü bileşikler üzerine araştırmalar sürmektedir."],["p","Bu bilgiler geneldir; pırasa bir besindir, tıbbi tedavi yerine geçmez."]]],["Pırasa Nasıl Seçilir?",[["p","Taze pırasa beyaz gövdesi sert, yaprakları canlı yeşil olandır; sararmış veya yumuşamış gövdeler bayatlamanın işaretidir."],["ul",["Beyaz-açık yeşil geçiş bölgesi uzun olmalı; bu, gövdenin daha gevrek olduğunu gösterir.","Gövde elde sıkıldığında sert ve diri hissettirmeli, sünger gibi yumuşak olmamalı.","Kök ucu nemli, kesim yüzeyi taze görünmeli."]]]],["Pırasa Nasıl Saklanır?",[["p","Pırasa buzdolabında, gevşek bir poşette ve dik konumda 1-2 hafta tazeliğini korur. Doğranmış pırasa dondurularak birkaç ay saklanabilir; ancak doku yumuşadığından pişmiş tariflerde kullanılması önerilir."]]],["Mutfakta Pırasa Kullanımı",[["p","Pırasa zeytinyağlı yemeklerde ana malzeme, çorbalarda lezzet tabanı, kıymalı yemeklerde ise tamamlayıcı olarak kullanılır. Katlar arasında toprak biriktiğinden dikine yarılıp bol suda yıkanmalıdır."]]],["Pırasa Nasıl Temizlenir?",[["p","Kök ve koyu yeşil uçlar kesildikten sonra gövde boyuna yarılır, katlar akan su altında açılarak yıkanır. Bu yöntem, halkalar arasına sıkışan toprağı tamamen temizler."]]],["Pırasa Hangi Tariflerle Kullanılır?",[["p","Zeytinyağlı pırasa, pırasa çorbası, kıymalı pırasa ve pırasa graten en sevilen tariflerdendir. Sebze soslarında lezzet tabanı olarak da sıkça kullanılır."]]]],"s":[["Pırasa neye iyi gelir?","Pırasa; K vitamini, demir ve lif açısından zengindir, dengeli beslenmenin parçası olarak öne çıkan sebzelerdendir. Bir besindir; herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Pırasanın yeşil kısmı kullanılır mı?","Evet, koyu yeşil yapraklar daha sert olsa da ince doğranıp çorbalarda veya suyu süzülen tariflerde değerlendirilebilir."],["Pırasa çiğ yenir mi?","Çok ince dilimlenmiş taze pırasa salatalarda çiğ olarak kullanılabilir; ancak genel olarak pişirilerek tüketilmesi tercih edilir."],["Pırasa neden topraklı olur?","Pırasa toprak altında büyürken katları arasına toprak sızar; bu yüzden dikine yarılıp katları açılarak bol suda yıkanması gerekir."],["Pırasa ile soğan aynı mı?","Hayır, ikisi de soğangiller familyasındandır ancak pırasa daha hafif, tatlımsı bir aroma taşır ve gövdesi silindirik uzundur; soğan ise küçük katmanlı bir yumrudur."]],"q":[["i-droplet","Katları yıkayın","Toprak halkalar arasında gizlenir"],["i-fire-burner","Yavaş pişirin","Kısık ateşte pişirmek doğal tatlılığını ortaya çıkarır"],["i-arrow-rotate-left","Alternatifi","Taze soğan, kuru soğan"]],"i":["ispanak","kabak","enginar"],"ic":"i-carrot","l":"Allium ampeloprasum","n":["(100 g çiğ)",[["Enerji","61 kcal"],["Protein","1,5 g"],["Lif","1,8 g"],["Karbonhidrat","14,2 g"],["K Vitamini","47 µg"],["Demir","2,1 mg"]]],"tb":"Pırasalı tarifler","t":[{"a":"Zeytinyağlı Pırasa | Havuçlu Pirinçli","k":"Zeytinyağlılar","g":"1520","d":"50 dk","z":"Kolay","p":"4 kişilik","s":"Emir Tuğluk","r":"3,0","b":1},{"a":"Dana Etli Pırasa | Zeytinyağlı Kışlık Yemek","k":"Kırmızı Et","g":"1719","d":"65 dk","z":"Kolay","p":"4 kişilik","s":"Esma Orbay","r":"0,0","b":1},{"a":"Kremalı Pırasalı Makarna | Sade Sebze Soslu Tarif","k":"Makarna","g":"1759","d":"35 dk","z":"Kolay","p":"4 kişilik","s":"Esma Kasapoğlu","r":"0,0","b":1}]},
"pul-biber":{"a":"Pul Biber","k":"Baharat","e":"Acı-tatlı katman","o":"Olgunlaşmış kırmızı biberlerin güneşte kurutulup kabaca çekilmesiyle elde edilen, Urfa ve Maraş türleriyle bilinen bir baharat. Çorbadan kavurmaya kadar geniş bir mutfakta yaygın kullanılır.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Sonbahar (kırmızı biber hasadı ve kurutma dönemi)"],["i-fire","Kalori (100 g, kurutulmuş)","318 kcal"],["i-box-archive","Saklama (doğrudan güneş ışığı rengini ve acılığını azaltır)","Kapalı kavanozda serin, karanlık yerde 1–2 yıl"]],"b":[["Pul Biber Nedir?",[["p","Pul biber, olgunlaşmış kırmızı biberlerin (<i>Capsicum annuum</i>) güneşte veya fırında kurutulup kabaca çekilmesiyle elde edilen, tane tane pulcuklar halindeki bir baharattır. Türkiye’de en çok bilinen türleri Urfa ve Maraş biberidir; ikisi de farklı kurutma yöntemleriyle kendine özgü tat ve renk kazanır."],["p","Maraş biberi güneşte kurutularak parlak kırmızı ve keskin acı bir tat kazanırken, Urfa biberi gölgede kurutulup güneşte terletilerek koyu, isli ve daha yumuşak bir acılığa sahip olur."]]],["Pul Biberin Besin Değerleri",[["p","Kurutulmuş kırmızı biberden elde edildiği için pul biber, 100 gramda yaklaşık 318 kcal enerji, 12 g protein ve 27 g’a yakın lif içerir. Kırmızı rengini veren karotenoidler sayesinde A vitamini bakımından da zengindir; ancak günlük tüketim miktarı çok az olduğundan pratikte katkısı sınırlıdır."]]],["Pul Biberin Faydaları Nelerdir?",[["p","Pul biberin acılığından sorumlu <b>kapsaisin</b> bileşiği üzerine yapılan araştırmalar, metabolizma ve iştah üzerindeki olası etkilerini incelemeye devam etmektedir; bu bulgular henüz kesin bir sağlık önerisine dönüşmüş değildir."],["p","Bu bilgiler geneldir; pul biber bir baharattır, tıbbi tedavi yerine geçmez. Mide hassasiyeti olanların acı baharat tüketimini dikkatli ayarlaması önerilir."]]],["Pul Biber Nasıl Seçilir?",[["p","Kaliteli pul biber parlak kırmızı renkli, yağlı görünümlü ve elde ovulduğunda hafif yapışkan hissettiren biberdir."],["ul",["Renk donuk kahverengiye dönmüşse biber eskimiş demektir.","Elle sıkıldığında hafif yağ bırakması, iyi bir yağ oranına işaret eder.","Aşırı tuzlu veya boyalı ürünlerden kaçının; saf pul biberde ek katkı olmamalıdır."]]]],["Pul Biber Nasıl Saklanır?",[["p","Pul biber, kapalı bir kavanozda serin ve karanlık bir yerde saklandığında 1–2 yıl tazeliğini korur. Nem çekmesi hem küflenmeye hem topaklanmaya yol açacağından kavanozun ağzı iyi kapatılmalıdır."]]],["Mutfakta Pul Biber Kullanımı",[["p","Pul biber; çorbalara, kavurmalara, közlemelere ve salatalara doğrudan serpiştirilerek ya da tereyağı/zeytinyağında kavrularak (acı yağ) kullanılır."]]],["Acı Yağ (Kırmızı Yağ) Nasıl Yapılır?",[["p","Tereyağı veya zeytinyağı hafif ısıtılıp içine pul biber eklenerek birkaç saniye kavrulur; yanmadan alevden alınıp mercimek çorbası, mantı veya kavurma üzerine gezdirilir."]]],["Pul Biber Hangi Tariflerle Kullanılır?",[["p","Mercimek çorbası, mantı, çiğ köfte, kavurma ve közlenmiş sebze tarifleri pul biberin en çok kullanıldığı lezzetler arasındadır."]]]],"s":[["Urfa biberi ile Maraş biberi arasındaki fark nedir?","Urfa biberi gölgede kurutulup terletilerek koyu, dumanımsı ve nispeten yumuşak acılı olurken; Maraş biberi güneşte kurutularak daha parlak kırmızı, keskin ve doğrudan bir acılık kazanır."],["Pul biber neye iyi gelir?","Pul biber içerdiği kapsaisin ile bilinir; geleneksel mutfaklarda lezzet ve sıcaklık katmak için tüketilir. Bir baharattır, hastalık tedavisi iddiası taşımaz."],["Pul biber neden topaklanır?","Nem çekmesi pul biberin topaklanmasına ve zamanla küflenmesine yol açar; bu yüzden kavanozun kuru bir ortamda ve sıkı kapaklı saklanması önemlidir."],["Acı yağ neden yakılmamalı?","Pul biber yüksek ısıda birkaç saniyeden fazla kavrulursa acılaşır ve yanık bir tat bırakır; bu yüzden yağ ocaktan alındıktan hemen sonra pul biber eklenmesi önerilir."],["Pul biber yerine ne kullanılabilir?","Elde yoksa kırmızı toz biber ile az miktarda karabiber karışımı yakın bir tat verebilir; ancak pul biberin karakteristik dumanımsı-tatlı notasını tam olarak taklit etmez."]],"q":[["i-fire","Isıdan uzak sakla","Doğrudan güneş ışığı rengini soldurur"],["i-fire","Yağda kısa süre kavur","Acı yağ, tadı derinleştirir"],["i-scale-balanced","Az ekleyip tadına bak","Acı düzeyi partiden partiye değişir"]],"i":["zencefil","sumak","karabiber"],"ic":"i-mortar-pestle","l":"Capsicum annuum","n":["(100 g, kurutulmuş (yaklaşık; günlük tüketim bir tutamla sınırlıdır))",[["Enerji","318 kcal"],["Protein","12,0 g"],["Yağ","17,3 g"],["Karbonhidrat","56,6 g"],["Lif","27,2 g"],["A Vitamini","Yüksek (karotenoid)"]]],"tb":"Pul biberli tarifler","t":[{"a":"Etli Kuru Fasulye | Geleneksel Ev Yapımı Tarif","k":"Bakliyat","g":"1277","d":"110 dk","z":"Orta","p":"4 kişilik","s":"Ahmet Ayaydın","r":"0,0","b":1},{"a":"Tas Kebabı | Geleneksel Sulu Et Yemeği","k":"Kırmızı Et","g":"1282","d":"110 dk","z":"Kolay","p":"4 kişilik","s":"Ebru Ozansoy","r":"4,0","b":2},{"a":"Adana Kebabı | Ev Yapımı Zırh Kıymalı","k":"Köfte ve Kebap","g":"1284","d":"50 dk","z":"Orta","p":"4 kişilik","s":"Ebru Ozansoy","r":"5,0","b":2}]},
"salkim-domates":{"a":"Salkım Domates","k":"Domates","e":"Dalında olgunlaşan domates","o":"Sap salkımıyla birlikte, dalında olgunlaştırılıp satılan orta boy domates. Salkımdan gelen yoğun kokusu ve dengeli tadıyla hem çiğ hem pişmiş kullanılır.","y":[["i-layer-group","Kategori","Domates"],["i-calendar-days","Mevsim","Yaz (serada yıl boyu)"],["i-fire","Kalori (100 g, çiğ (yaklaşık))","18 kcal"],["i-box-archive","Saklama (sapından ayırmadan saklamak tazeliği uzatır)","Salkımı üzerinde, oda sıcaklığında 4–6 gün"]],"b":[["Salkım Domates Nedir?",[["p","Salkım domates, tek tek koparılmak yerine sap salkımıyla birlikte, dalında olgunlaştırılarak toplanan orta boy bir domates çeşididir (<i>Solanum lycopersicum</i>). Dalında olgunlaştığı için aroması genellikle daha yoğundur."],["p","Yeşil salkım, domatesin karakteristik kokusunun büyük bölümünü taşır; bu yüzden salkım domates hem tazelik algısı hem raf ömrü açısından avantajlı kabul edilir."]]],["Salkım Domatesin Besin Değerleri",[["p","Domates düşük kalorili (100 gramı yaklaşık 18 kcal), su oranı yüksek bir sebzedir; <b>C vitamini</b>, potasyum ve likopen içerir. Değerler olgun domates için yaklaşık olup kültivara göre küçük farklar gösterebilir."]]],["Salkım Domatesin Faydaları Nelerdir?",[["p","C vitamini, potasyum ve likopen içeriğiyle salkım domates, dengeli beslenmenin bir parçası olarak değerlendirilebilir; dalında olgunlaştığından aroması ve C vitamini algısı yüksektir."],["p","Bu bilgiler geneldir; salkım domates bir besindir, tıbbi tedavi yerine geçmez."]]],["Salkım Domates Nasıl Seçilir?",[["p","İyi bir salkım domateste taneler eşit olgunlukta, kabuk çatlaksız ve salkım yeşil-diri olmalıdır; salkımı kuruyup kararmış ürünler beklemiştir."],["ul",["Salkım (yeşil sap) taze, diri ve yeşil olmalı","Taneler eşit renkte ve çatlaksız olmalı","Salkımdan belirgin domates kokusu gelmesi tazeliğin işaretidir"]]]],["Salkım Domates Nasıl Saklanır?",[["p","Salkım domates, sapından ayrılmadan ve salkımı aşağı bakacak şekilde oda sıcaklığında 4–6 gün saklanabilir; bu, tanelerin sap dibinden nem kaybını yavaşlatır. Buzdolabı aromayı bozduğundan tercih edilmez."]]],["Mutfakta Salkım Domates Kullanımı",[["p","Salkım domates hem çiğ olarak salata ve mezelerde hem de fırınlanarak, sotelenerek pişmiş yemeklerde kullanılır; salkımıyla birlikte fırınlanması sunumda etkileyici bir görünüm verir."]]],["Fırında Salkım Domates Nasıl Yapılır?",[["p","Salkım bütün hâlde zeytinyağı, tuz ve sarımsakla fırın tepsisine dizilip yüksek ısıda kabukları çatlayana dek pişirilir; makarna, tost ve ızgara etlerin yanında sıcak servis edilir."]]],["Salkım Domates Sosu",[["p","Doğranan salkım domatesler soğan ve zeytinyağıyla kısık ateşte pişirilip ezilerek taze bir makarna sosu elde edilir."]]],["Salkım Domates Hangi Tariflerle Kullanılır?",[["p","Fırında salkım domates, domates sosu, çoban salata ve bruschetta salkım domatesin sık kullanıldığı tariflerdendir."]]]],"s":[["Salkım domates neden daha kokuludur?","Karakteristik domates kokusunun büyük kısmı yeşil salkımdan yayılır; ayrıca dalında olgunlaştığı için aroma bileşikleri daha gelişmiş olur."],["Salkım domates neden dalıyla satılır?","Sapıyla birlikte satılması hem tazelik algısını artırır hem de tanelerin sap dibinden su kaybını yavaşlatarak raf ömrünü uzatır."],["Salkım domates buzdolabında saklanır mı?","Tercih edilmez; soğuk aromayı ve dokuyu bozar. Oda sıcaklığında, salkımı üzerinde saklamak en iyi sonucu verir."],["Salkım domatesin salkımı yenir mi?","Hayır, yeşil salkım ve yapraklar yenmez; yalnızca koku ve tazelik için üründe bırakılır, tüketimden önce ayrılır."],["Salkım domates ile normal domates besin olarak farklı mı?","Besin değerleri büyük ölçüde benzerdir; temel fark olgunlaşma biçiminden gelen aroma yoğunluğudur, sayısal besin farkı belirgin değildir."]],"q":[["i-leaf","Koku sapından gelir","Karakteristik domates kokusunun çoğu yeşil salkımdan yayılır"],["i-clock","Salkımda saklayın","Sapından ayırmadan bekletmek tazeliğini uzatır"],["i-fire","Oda sıcaklığı","Buzdolabı yerine tezgahta saklamak tadını korur"]],"i":["ceri-domates","kurutulmus-domates","pembe-domates"],"ic":"i-carrot","l":"Solanum lycopersicum","n":["(100 g çiğ, ~yaklaşık (USDA olgun domates; kültivar ayrılmaz))",[["Enerji","~18 kcal"],["Protein","0,9 g"],["Karbonhidrat","3,9 g"],["Lif","1,2 g"],["C Vitamini","14 mg"],["Potasyum","237 mg"]]]},
"sumak":{"a":"Sumak","k":"Baharat","e":"Ekşi baharat","o":"Koyu bordo renkli, mayhoş-ekşi tadıyla salataların ve kebapların vazgeçilmez baharatı. Limonun keskinliği yerine yumuşak bir ekşilik verir.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu (hasat: yaz sonu–sonbahar)"],["i-fire","Kalori (100 g toz, yaklaşık)","~250 kcal"],["i-box-archive","Saklama (serin, ışıksız)","Ağzı kapalı kavanozda 1 yıl"]],"b":[["Sumak Nedir?",[["p","Sumak (<i>Rhus coriaria</i>), Akdeniz ve Orta Doğu’ya özgü bir çalının olgunlaşmış kırmızı meyvelerinin kurutulup öğütülmesiyle elde edilen koyu bordo renkli bir baharattır. Kendine has, keskin olmayan bir <b>ekşilik</b> verir; bu yüzden mutfakta çoğu zaman limon ya da sirkeye alternatif olarak düşünülür."],["p","Toz halinin yanı sıra iri kırık (pul) formu da bulunur. Türk mutfağında özellikle çiğ soğanla, kebap yanı sofralarda ve salatalarda öne çıkar; tadı yumuşak, aroması hafif meyvemsidir."]]],["Sumağın Besin Değerleri",[["p","Sumak bir baharat olarak çok küçük miktarlarda tüketildiğinden makro besin katkısı düşüktür. Toz sumağın 100 gramı yaklaşık 250 kcal enerji taşır; lif oranı yüksektir ve içerdiği <b>tanenler</b> ile organik asitler sayesinde antioksidan bakımından zengin kabul edilir. Standart bir USDA profili bulunmadığından bu değerler yaklaşık niteliktedir."]]],["Sumağın Faydaları Nelerdir?",[["p","Sumak, geleneksel Anadolu ve Orta Doğu mutfağında yüzyıllardır iştah açıcı ve yemeğe ferahlık veren bir baharat olarak tüketilir. İçerdiği antioksidan bileşikler üzerine güncel araştırmalar sürmektedir; bu çalışmalar henüz genel bir sağlık önerisine dönüşmemiştir."],["p","Bu bilgiler genel niteliktedir. Sumak bir baharattır; herhangi bir hastalığı tedavi ettiği ya da iyileştirdiği iddiası taşımaz."]]],["Sumak Nasıl Seçilir?",[["p","Kaliteli sumak canlı, koyu bordo-mor bir renge sahiptir; soluk kahverengi ton eskidiğini ya da düşük kaliteyi gösterir."],["ul",["Renk canlı ve koyu olsun; kararmış, grileşmiş ürünü alma.","Nemli topaklanma yerine ince, dağınık bir toz tercih et.","Bazı ürünlere tuz eklenebilir; içeriği kontrol et."]]]],["Sumak Nasıl Saklanır?",[["p","Sumak, ağzı sıkıca kapalı bir kavanozda, serin ve ışık görmeyen bir dolapta saklandığında rengini ve ekşiliğini yaklaşık bir yıl korur. Nem ve ışık hem rengini soldurur hem aromasını köreltir."]]],["Mutfakta Sumak Kullanımı",[["p","Sumak, pişirmenin sonunda ya da servis sırasında serpilerek kullanılır; uzun ısı aromasını zayıflatır. Ekşiliği yemeğe limon kadar keskin gelmeden denge kattığı için soğan, mercimek ve kırmızı et ile çok iyi anlaşır."]]],["Sumaklı Soğan Nasıl Yapılır?",[["p","İnce piyazlık doğranmış soğan tuzla ovulup suyu hafifçe alınır, ardından bolca sumak ve isteğe göre maydanozla harmanlanır. Kebap, köfte ve ızgara yanında klasik bir garnitürdür."]]],["Salata ve Mezelerde Sumak",[["p","Çoban salatasına, mercimek köftesine ve humusa üzerinden serpilen sumak, hem renk hem de mayhoş bir ferahlık verir. Zeytinyağı ile birleştirildiğinde basit bir salata sosuna dönüşür."]]],["Sumak Hangi Tariflerle Kullanılır?",[["p","Sumaklı soğan, çoban salatası, mercimek köftesi, fattuş ve tavuk-et marinasyonları sumağın en sık kullanıldığı tariflerdir. Zahter (za’atar) karışımının da temel bileşenlerindendir."]]]],"s":[["Sumak neye iyi gelir?","Sumak geleneksel olarak iştah açan ve yemeğe ferahlık katan bir baharat olarak tüketilir. Antioksidan bileşikleri üzerine araştırmalar sürse de, bir baharat olarak herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Sumağın tadı nasıldır?","Sumak, limonun keskinliği olmadan yumuşak ve mayhoş bir ekşilik verir. Hafif meyvemsi bir aroması vardır; bu yüzden salata ve ızgara yanlarında limona alternatif olarak kullanılır."],["Sumak limon yerine kullanılabilir mi?","Evet, birçok tarifte ekşilik kaynağı olarak limonun yerini tutar. Limon gibi sıvı katmadığından, özellikle soğan ve salataları sulandırmadan ekşilik vermek istenen durumlarda pratiktir."],["Sumak yemeğin neresinde eklenir?","Aroması ısıya karşı hassas olduğu için genellikle pişirmenin sonunda ya da servis sırasında serpilerek eklenir. Uzun süre kaynatmak ekşiliğini ve rengini köreltir."],["Sumak nasıl saklanır?","Ağzı kapalı bir kavanozda, serin ve ışık almayan bir yerde saklanmalıdır. Bu koşullarda rengini ve tadını yaklaşık bir yıl korur; nem topaklanmaya ve aroma kaybına yol açar."]],"q":[["i-compass","Kökeni","Akdeniz · Orta Doğu"],["i-apple-whole","Tat profili","Mayhoş, yumuşak ekşi"],["i-users","En iyi eşleşme","Soğan, kebap, mercimek, salata"]],"i":["zencefil","karabiber","pul-biber"],"ic":"i-mortar-pestle","l":"Rhus coriaria","n":["(100 g toz baharat (yaklaşık))",[["Enerji","~250 kcal"],["Lif","Yüksek"],["C Vitamini","Kaynak"],["Antioksidan","Zengin (tanen)"]]],"tb":"Sumaklı tarifler","t":[{"a":"Arnavut Ciğeri | Klasik Tava","k":"Sakatat","g":"1290","d":"30 dk","z":"Orta","p":"4 kişilik","s":"İrem Akgül","r":"0,0","b":1},{"a":"Piyaz | Kuru Fasulye Salatası","k":"Bakliyat","g":"1298","d":"70 dk","z":"Çok Kolay","p":"4 kişilik","s":"Ümran Tanrıkulu","r":"4,0","b":1},{"a":"Fırında Karnabahar Salatası | Tahinli Sumaklı Tarif","k":"Salata","g":"1839","d":"40 dk","z":"Orta","p":"4 kişilik","s":"Yağız Keçeci","r":"4,3","b":2}]},
"tulum-peyniri":{"a":"Tulum Peyniri","k":"Peynir","e":"Yöresel lezzet","o":"Koyun ya da keçi sütünden yapılıp deri veya bez tulumda olgunlaştırılan, kırılgan dokulu ve keskin tatlı geleneksel bir peynir. Erzincan ve İzmir tulumu en bilinen türleridir.","y":[["i-layer-group","Kategori","Peynir"],["i-calendar-days","Mevsim","Yıl boyu"],["i-fire","Kalori (100 g, yaklaşık (İzmir tulum tipi))","~326 kcal"],["i-box-archive","Saklama","Buzdolabında, kendi yağı veya vakumlu ambalajında 2–3 hafta"]],"b":[["Tulum Peyniri Nedir?",[["p","Tulum peyniri, koyun, keçi veya inek sütünden yapılan lorun tuzlanıp geleneksel olarak deri tulumda ya da günümüzde çoğunlukla bezde/plastik ambalajda basılarak olgunlaştırılmasıyla elde edilen bir peynirdir. Olgunlaşma sürecinde keskin, biraz ekşimsi bir aroma kazanır."],["p","Erzincan tulumu (koyun sütünden, sert ve keskin) ile İzmir tulumu (genellikle keçi sütünden, daha kırılgan ve beyaz) en tanınan iki yöresel çeşididir."]]],["Tulum Peynirinin Besin Değerleri",[["p","Tulum peyniri, 100 gramında yaklaşık 326 kcal enerji, 19,6 g <b>protein</b> ve 24,3 g yağ içeren, yoğun bir peynirdir. Olgunlaşma süresi ve süt türüne göre bu değerler değişiklik gösterebilir."]]],["Tulum Peynirinin Faydaları Nelerdir?",[["p","Tulum peyniri, yüksek protein ve kalsiyum içeriğiyle dengeli beslenmenin bir parçası olarak öne çıkan geleneksel peynirlerdendir. Tuz oranı genellikle yüksektir."],["p","Bu bilgiler geneldir; tulum peyniri bir besindir, tıbbi tedavi yerine geçmez. Tansiyon takibi olan kişiler tuz içeriğine dikkat etmelidir."]]],["Tulum Peyniri Nasıl Seçilir?",[["p","Tulum peyniri seçerken rengin beyaz-krem, dokunun ufalanabilir ve kokusunun keskin ama küf kokusundan uzak olmasına dikkat edilmelidir."],["ul",["Aşırı sert ve kuru görünüm, uzun süre bekletilmiş olduğunu gösterebilir.","Yeşil-siyah küf lekesi bulunan tulum peyniri tüketilmemelidir.","Yöresel üreticilerden alınan tulum peynirleri genellikle daha otantik bir aroma taşır."]]]],["Tulum Peyniri Nasıl Saklanır?",[["p","Tulum peyniri buzdolabında kendi yağında veya vakumlu ambalajında 2–3 hafta tazeliğini korur. Açık havada bırakılırsa hızla kurur ve sertleşir."]]],["Mutfakta Tulum Peyniri Kullanımı",[["p","Tulum peyniri; kahvaltıda dilimlenerek, salata ve pilavların üzerine ufalanarak, makarna ve omletlerde eritilerek kullanılır. Keskin tadı az miktarda bile lezzeti belirginleştirir."]]],["Tulum Peyniri Nasıl Ufalanır?",[["p","Tulum peyniri elle veya çatalla kolayca ufalanır; soğukken ufalamak dağılmayı kolaylaştırır. Ufalanan peynir salata, pilav veya makarnaların üzerine servis anında serpilir."]]],["Tulum Peyniri Hangi Tariflerle Kullanılır?",[["p","Tulum peynirli makarna, tulum peynirli pilav, tulum peynirli omlet ve peynir tabağı en sevilen kullanım biçimleridir."]]]],"s":[["Tulum peyniri neye iyi gelir?","Tulum peyniri; protein ve kalsiyum bakımından zengin geleneksel bir peynirdir. Herhangi bir hastalığı iyileştirme iddiası taşımaz."],["Erzincan tulumu ile İzmir tulumu arasındaki fark nedir?","Erzincan tulumu koyun sütünden yapılır, sert ve keskin bir tadı vardır; İzmir tulumu genellikle keçi sütünden yapılır, daha kırılgan ve hafif ekşimsi bir dokuya sahiptir."],["Tulum peyniri neden tuzlu olur?","Tuz, olgunlaşma sürecinde koruyucu görevi görür ve peynirin uzun süre bozulmadan saklanmasını sağlar; bu nedenle tulum peyniri genellikle diğer taze peynirlere göre daha tuzludur."],["Tulum peyniri kaç ayda olgunlaşır?","Geleneksel üretimde tulum peyniri genellikle birkaç aydan bir yıla kadar süren bir olgunlaşma sürecinden geçer; olgunlaşma süresi arttıkça aroması da yoğunlaşır."],["Tulum peyniri dondurulabilir mi?","Tulum peyniri dondurulabilir ancak çözüldüğünde dokusu biraz daha ufalanır hale gelebilir; bu nedenle özellikle ufalanarak kullanılan tariflerde tercih edilebilir."]],"q":[["i-flask","Kendi yağında sakla","Tazeliğini ve aromasını uzun süre korur"],["i-mortar-pestle","Ufalanarak kullan","Salata ve pilavların üzerine ufalanarak eklenir"],["i-arrow-rotate-left","Alternatifi","Beyaz peynir, ezine peyniri"]],"i":["beyaz-peynir","kasar-peyniri","lor-peyniri"],"ic":"i-cheese","n":["(~100 g (yaklaşık, Türkiye ortalama))",[["Enerji","~326 kcal"],["Protein","~19,6 g"],["Yağ","~24,3 g"]]],"tb":"Tulum peynirli tarifler","t":[{"a":"Tulum Peynirli Pide | Otlu Tulum Peynirli Fırın Pidesi","k":"Pizza ve Pide","g":"2388","d":"55 dk","z":"Kolay","p":"4 kişilik","s":"Burcu Okur","r":"4,7","b":2}]},
"zencefil":{"a":"Zencefil","k":"Baharat","e":"Aromatik kök","o":"Keskin aroması ve hafif acımsı tadıyla hem taze hem toz halde kullanılan köklü bir baharat. Asya mutfağının temel taşı; çay, tatlı ve et yemeklerinde yaygın.","y":[["i-layer-group","Kategori","Baharat"],["i-calendar-days","Mevsim","Yıl boyu (taze kök: sonbahar–kış)"],["i-fire","Kalori (100 g, taze kök)","80 kcal"],["i-box-archive","Saklama (taze, kağıt havluya sarılı)","Buzdolabında 3–4 hafta"]],"b":[["Zencefil Nedir?",[["p","Zencefil (<i>Zingiber officinale</i>), zencefilgiller familyasından tropik bir bitkinin toprak altında büyüyen kök gövdesidir (rizom). Güneydoğu Asya kökenlidir ve binlerce yıldır hem baharat hem de geleneksel şifa malzemesi olarak kullanılır. Keskin, hafif acımsı ve ferahlatıcı aroması, içerdiği <b>gingerol</b> adlı bileşikten gelir."],["p","Mutfakta iki temel formu vardır: lifli ve sulu <b>taze kök</b> ile kurutulup öğütülmüş <b>toz zencefil</b>. Taze kök daha canlı ve keskin, toz form ise daha sıcak ve yoğun bir tat verir; ikisi birebir yer değiştiremez, tariflerde ayrı ayrı düşünülür."]]],["Zencefilin Besin Değerleri",[["p","Taze zencefil düşük kalorili bir baharattır; 100 gramı yaklaşık 80 kcal enerji, 17,8 g karbonhidrat ve 2 g lif içerir. Potasyum, magnezyum ve az miktarda C vitamini taşır. Ancak günlük kullanımda genellikle birkaç gramla sınırlı tüketildiği için asıl değeri makro besinlerinden çok aromatik bileşiklerindedir."]]],["Zencefilin Faydaları Nelerdir?",[["p","Zencefil, geleneksel mutfakta yüzyıllardır sindirimi rahatlatmak ve mideyi yatıştırmak amacıyla tüketilir. Bilimsel çalışmalar, zencefilin özellikle <b>bulantı hissini hafifletmeye destek olabileceğini</b> göstermektedir. İçerdiği gingerolün antioksidan özellikleri üzerine araştırmalar sürmektedir."],["p","Bu bilgiler genel niteliktedir; zencefil bir besin ve baharattır, tıbbi tedavi yerine geçmez. Düzenli ilaç kullananların ya da hamilelerin yüksek miktarda tüketimden önce bir sağlık uzmanına danışması önerilir."]]],["Zencefil Nasıl Seçilir?",[["p","Taze zencefil alırken kökün sıkı, ağır ve parlak kabuklu olmasına dikkat et. Kaliteli bir kök kırıldığında çıtırdar ve yoğun kokar."],["ul",["Kabuğu ince, gergin ve pürüzsüz olsun; buruşuk kabuk kökün kuruduğunu gösterir.","Elde ağır ve dolgun hissettiren kökler daha suludur.","Yumuşamış, küflenmiş ya da filizlenmiş kökleri alma."]]]],["Zencefil Nasıl Saklanır?",[["p","Taze kök buzdolabının sebzeliğinde, kağıt havluya sarılı olarak 3–4 hafta dayanır. Uzun saklama için kabuğu soyulmadan dondurulabilir; dondurulmuş kök rendelenerek doğrudan tencereye eklenir. Toz zencefil ise ağzı kapalı kavanozda, serin ve karanlık bir dolapta aromasını uzun süre korur."],["ul",["Taze kök: kağıda sarılı, buzdolabında 3–4 hafta.","Dondurucu: soyulmadan, aylarca; rendelemek için ideal.","Toz: ışık görmeyen kapalı kavanozda 1 yıla kadar."]]]],["Mutfakta Zencefil Kullanımı",[["p","Zencefil hem tuzlu hem tatlı tarafta iş görür: et ve tavuk marinasyonlarına derinlik, çorbalara ısıtıcı bir keskinlik, kek ve kurabiyelere baharatlı bir sıcaklık katar. Uzak Doğu soteleri, köri karışımları ve turşularda vazgeçilmezdir."]]],["Zencefil Çayı Nasıl Yapılır?",[["p","Bir bardak kaynar suya 2–3 ince dilim taze zencefil ekleyip 5–10 dakika demlemek yeterlidir. Üzerine bir dilim limon ve isteğe göre bir tatlı kaşığı bal katılarak içilir. Kış aylarında ferahlatıcı, ısıtıcı bir içecek olarak tercih edilir."]]],["Yemeklerde Taze Zencefil",[["p","Taze kök soteye ekleneceği zaman en son aşamada, sarımsakla birlikte kısa süre kavrulur; uzun pişirme aromasını köreltir. Rendelenmiş zencefil, salata soslarına ve marine karışımlarına çiğ olarak da katılabilir."]]],["Zencefil Hangi Tariflerle Kullanılır?",[["p","Zencefilli tavuk sote, zencefilli havuç çorbası, baharatlı kek ve zencefilli limonata en sevilen kullanımlarındandır. Toz formu zencefilli kurabiye ve kış tatlılarında; taze formu ise Uzak Doğu yemekleri ve çaylarında öne çıkar."]]]],"s":[["Zencefil neye iyi gelir?","Zencefil geleneksel olarak sindirimi rahatlatmak ve mideyi yatıştırmak amacıyla tüketilir; çalışmalar bulantı hissini hafifletmeye destek olabileceğini göstermektedir. Bir besin ve baharattır, tıbbi tedavinin yerini tutmaz."],["Günde ne kadar zencefil tüketilebilir?","Genel kullanımda günde birkaç gram taze kök ya da yarım-bir tatlı kaşığı toz zencefil çoğu kişi için makul kabul edilir. Kişisel duruma göre değişebileceğinden, düzenli ilaç kullananların uzmanına danışması yerinde olur."],["Zencefilin yan etkileri var mı?","Yüksek miktarda tüketildiğinde bazı kişilerde mide yanması ya da hazımsızlık görülebilir. Kan sulandırıcı kullananların dikkatli olması ve hamilelerin fazla tüketimden önce hekime danışması önerilir."],["Taze zencefil ile toz zencefil farkı nedir?","Taze kök daha canlı, sulu ve keskindir; toz form ise daha sıcak, yoğun ve kurudur. Genel bir kural olarak bir yemek kaşığı rendelenmiş taze zencefil yaklaşık çeyrek tatlı kaşığı toz zencefile denk gelir."],["Zencefil çayı ne zaman içilir?","Çoğunlukla sabahları güne başlarken ya da yemek sonrası ferahlamak için tercih edilir. Keskin aroması nedeniyle akşam geç saatte hafif demlenmiş içilmesi daha rahat ettirir."]],"q":[["i-compass","Kökeni","Güneydoğu Asya"],["i-mortar-pestle","Formu","Taze kök · toz · turşu · kurutulmuş"],["i-users","En iyi eşleşme","Bal, limon, sarımsak, soya"]],"i":["sumak","karabiber","pul-biber"],"ic":"i-mortar-pestle","l":"Zingiber officinale","n":["(100 g taze kök)",[["Enerji","80 kcal"],["Karbonhidrat","17,8 g"],["Lif","2,0 g"],["Protein","1,8 g"],["Potasyum","415 mg"],["C Vitamini","5 mg"]]],"tb":"Zencefilli tarifler","t":[{"a":"Portakal Havuç Zencefil Suyu | C Vitamini Deposu İçecek","k":"İçecek","g":"1376","d":"10 dk","z":"Çok Kolay","p":"2 kişilik","s":"Emel Tekand","r":"4,3","b":2},{"a":"Kabak Çorbası | Kremamsı Zencefilli","k":"Çorba","g":"1508","d":"40 dk","z":"Kolay","p":"4 kişilik","s":"Rüya Abadan","r":"3,0","b":1},{"a":"Chai Latte | Hint Usulü Baharatlı Sütlü Çay","k":"İçecek","g":"1600","d":"30 dk","z":"Orta","p":"4 kişilik","s":"Ali Öztuna","r":"5,0","b":2}]}
};
